tool_schemas.implementation:
def contacts(action, workspace_id, contact_id=None, email=None, phone_e164=None, whatsapp_e164=None, first_name=None, last_name=None, attributes=None, list_ids=None, consent=None, status=None, source=None, external_ids=None, created_by_principal_id=None, updated_by_principal_id=None, query=None, limit=None, cursor=None, sort_by=None, sort_order=None, import_job=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0080000" if __import__("os").path.isdir("./environment_mix/0080000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- audit/rate/quota logging (api calls) ----
    def _ensure_usage_today(ws):
        if not isinstance(ws.get("usage_today"), dict):
            ws["usage_today"] = {}
        ut = ws["usage_today"]
        for k in ("emails_sent", "sms_sent", "whatsapp_sent", "events_ingested", "api_calls"):
            if not isinstance(ut.get(k), int) or ut.get(k) < 0:
                ut[k] = 0

    def _log_call(resolved_ws_id, status_code, credential=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "brv_req_" + hashlib.sha1((now + str(time.time())).encode("utf-8")).hexdigest()[:20].upper(),
            "endpoint": "contacts",
            "action": action,
            "workspace_id": resolved_ws_id,
            "credential": credential,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        if extra is not None:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check(ws):
        # Enforce a simple per-workspace rate: 300 calls / rolling 60 seconds.
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-5000:]:
            if r.get("workspace_id") != ws["id"]:
                continue
            ts = r.get("timestamp")
            if isinstance(ts, str):
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    cnt += 1
        if cnt >= 300:
            return _err("RATE_LIMIT", "Rate limit exceeded. Try again later.", limit_per_minute=300)
        return None

    # ---- validation helpers ----
    wsp_pat = re.compile(r"^brv_wsp_[0-9A-Z]{18,}$")
    cnt_pat = re.compile(r"^brv_cnt_[0-9A-Z]{18,}$")
    prn_pat = re.compile(r"^brv_prn_[0-9A-Z]{18,}$")

    def _is_iso_dt(s):
        if not isinstance(s, str):
            return False
        try:
            datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            return True
        except Exception:
            return False

    def _gen_id(prefix):
        # 18+ chars uppercase-ish; use sha1 for determinism-ish
        return prefix + hashlib.sha1((prefix + now + str(time.time())).encode("utf-8")).hexdigest()[:20].upper()

    def _workspace_and_authz_for_mutation(workspaces, principals, wsid, principal_id, mutate_kind="mutate_contacts"):
        ws = next((w for w in workspaces if w.get("id") == wsid), None)
        if not ws:
            return None, _err("NOT_FOUND", "Workspace not found.", workspace_id=wsid)
        if ws.get("status") != "active":
            return None, _err("UNAUTHORIZED", "Workspace is not active.", workspace_status=ws.get("status"))

        if principal_id is None:
            # Ambient auth: pick any active principal in workspace that can perform this mutation.
            candidates = [p for p in principals if p.get("workspace_id") == wsid and p.get("status") == "active"]
            if not candidates:
                return None, _err("UNAUTHORIZED", "No active principal available for this workspace.")
            # enforce role constraints:
            for p in candidates:
                role = p.get("role")
                if role == "read_only":
                    continue
                # analysts cannot send messages, but contacts mutations are allowed
                return p, None
            return None, _err("UNAUTHORIZED", "No authorized principal available to perform this mutation.")
        else:
            if not isinstance(principal_id, str) or not prn_pat.match(principal_id):
                return None, _err("VALIDATION_ERROR", "Invalid principal id.", field="principal_id")
            p = next((x for x in principals if x.get("id") == principal_id and x.get("workspace_id") == wsid), None)
            if not p:
                return None, _err("NOT_FOUND", "Principal not found in workspace.", principal_id=principal_id)
            if p.get("status") != "active":
                return None, _err("UNAUTHORIZED", "Principal is not active.", principal_status=p.get("status"))
            if p.get("role") == "read_only":
                return None, _err("UNAUTHORIZED", "Principal role is read-only and cannot mutate.")
            return p, None

    def _enforce_contact_identifiers(em, ph, wa):
        if (em is None or em == "") and (ph is None or ph == "") and (wa is None or wa == ""):
            return _err("VALIDATION_ERROR", "At least one of email, phone_e164, whatsapp_e164 must be provided.")
        return None

    def _uniq_conflict(contacts_rows, wsid, em, ph, wa, exclude_id=None):
        for c in contacts_rows:
            if c.get("workspace_id") != wsid:
                continue
            if exclude_id and c.get("id") == exclude_id:
                continue
            if em is not None and em != "" and c.get("email") == em:
                return _err("CONFLICT", "Email already exists in workspace.", field="email")
            if ph is not None and ph != "" and c.get("phone_e164") == ph:
                return _err("CONFLICT", "Phone already exists in workspace.", field="phone_e164")
            if wa is not None and wa != "" and c.get("whatsapp_e164") == wa:
                return _err("CONFLICT", "WhatsApp number already exists in workspace.", field="whatsapp_e164")
        return None

    def _validate_list_ids(li):
        if li is None:
            return None
        if not isinstance(li, list) or any(not isinstance(x, str) for x in li):
            return _err("VALIDATION_ERROR", "list_ids must be an array of strings.", field="list_ids")
        # We don't have a lists collection; treat as syntactically valid ids only to avoid partial updates.
        # If caller supplies any non-matching id, fail atomically.
        bad = [x for x in li if not re.match(r"^brv_lst_[0-9A-Z]{6,}$", x)]
        if bad:
            return _err("VALIDATION_ERROR", "One or more list_ids are invalid.", invalid_list_ids=bad)
        if len(li) != len(set(li)):
            return _err("VALIDATION_ERROR", "Duplicate list_ids are not allowed.", field="list_ids")
        return None

    # ---- validate top-level params ----
    if action not in ("list", "get", "create", "update", "delete", "import"):
        return _err("VALIDATION_ERROR", "Invalid action.", field="action")
    if not isinstance(workspace_id, str) or not wsp_pat.match(workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.", field="workspace_id")

    workspaces = _load("workspaces.json")
    principals = _load("principals.json")
    contacts_rows = _load("contacts.json")
    import_jobs = _load("contact_import_jobs.json")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        _log_call(workspace_id, "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    _ensure_usage_today(ws)
    rl = _rate_limit_check(ws)
    if rl:
        _log_call(workspace_id, "RATE_LIMIT")
        return rl

    # increment api_calls quota-like counter
    ws["usage_today"]["api_calls"] += 1
    ws["updated_at"] = now
    _save("workspaces.json", workspaces)

    # ---- action implementations ----
    if action == "list":
        if limit is None:
            limit = 100
        if not isinstance(limit, int) or limit < 1 or limit > 500:
            _log_call(workspace_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be between 1 and 500.", field="limit")
        if cursor is not None and not isinstance(cursor, str):
            _log_call(workspace_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
        if sort_by is None:
            sort_by = "updated_at"
        if sort_by not in ("created_at", "updated_at", "email", "last_name"):
            _log_call(workspace_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid sort_by.", field="sort_by")
        if sort_order is None:
            sort_order = "desc"
        if sort_order not in ("asc", "desc"):
            _log_call(workspace_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid sort_order.", field="sort_order")

        rows = [c for c in contacts_rows if c.get("workspace_id") == workspace_id]

        # filters
        if email is not None:
            if not isinstance(email, str):
                _log_call(workspace_id, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "email must be a string.", field="email")
            rows = [c for c in rows if c.get("email") == email]
        if phone_e164 is not None:
            if not isinstance(phone_e164, str):
                _log_call(workspace_id, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "phone_e164 must be a string.", field="phone_e164")
            rows = [c for c in rows if c.get("phone_e164") == phone_e164]
        if whatsapp_e164 is not None:
            if not isinstance(whatsapp_e164, str):
                _log_call(workspace_id, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "whatsapp_e164 must be a string.", field="whatsapp_e164")
            rows = [c for c in rows if c.get("whatsapp_e164") == whatsapp_e164]
        if status is not None:
            if status not in ("active", "unsubscribed", "bounced", "blacklisted", "deleted"):
                _log_call(workspace_id, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid status filter.", field="status")
            rows = [c for c in rows if c.get("status") == status]
        if source is not None:
            if source not in ("api", "import", "ecommerce", "crm", "conversation", "unknown"):
                _log_call(workspace_id, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid source filter.", field="source")
            rows = [c for c in rows if c.get("source") == source]
        if query is not None:
            if not isinstance(query, str):
                _log_call(workspace_id, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "query must be a string.", field="query")
            q = query.strip().lower()
            if q:
                def _blob(c):
                    return " ".join([
                        str(c.get("email") or ""),
                        str(c.get("phone_e164") or ""),
                        str(c.get("whatsapp_e164") or ""),
                        str(c.get("first_name") or ""),
                        str(c.get("last_name") or ""),
                    ]).lower()
                rows = [c for c in rows if q in _blob(c)]

        # sort
        def _key(c):
            v = c.get(sort_by)
            if v is None:
                return ""
            return v
        reverse = (sort_order == "desc")
        rows.sort(key=_key, reverse=reverse)

        # cursor is base64 of integer offset
        offset = 0
        if cursor:
            try:
                offset = int(base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8"))
                if offset < 0:
                    raise ValueError()
            except Exception:
                _log_call(workspace_id, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        total = len(rows)
        page = rows[offset:offset + limit]
        next_off = offset + len(page)
        has_more = next_off < total
        next_cursor = base64.urlsafe_b64encode(str(next_off).encode("utf-8")).decode("utf-8") if has_more else None

        _log_call(workspace_id, "OK", extra={"returned": len(page), "total": total})
        return {"data": page, "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor}}

    if action == "get":
        if not isinstance(contact_id, str) or not cnt_pat.match(contact_id):
            _log_call(workspace_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "contact_id is required and must be a valid id.", field="contact_id")
        c = next((x for x in contacts_rows if x.get("id") == contact_id and x.get("workspace_id") == workspace_id), None)
        if not c:
            _log_call(workspace_id, "NOT_FOUND")
            return _err("NOT_FOUND", "Contact not found.", contact_id=contact_id)
        _log_call(workspace_id, "OK")
        return {"data": c}

    if action in ("create", "update", "delete", "import"):
        # authorize (contacts mutations allowed for analyst; only read_only blocked)
        principal_id = updated_by_principal_id if action in ("update", "delete") else created_by_principal_id
        p, e = _workspace_and_authz_for_mutation(workspaces, principals, workspace_id, principal_id)
        if e:
            _log_call(workspace_id, e["error"]["code"])
            return e

    if action == "create":
        # validate payload fields
        if status is not None and status not in ("active", "unsubscribed", "bounced", "blacklisted", "deleted"):
            _log_call(workspace_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status.", field="status")
        if source is not None and source not in ("api", "import", "ecommerce", "crm", "conversation", "unknown"):
            _log_call(workspace_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid source.", field="source")
        if attributes is not None and not isinstance(attributes, dict):
            _log_call(workspace_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "attributes must be an object.", field="attributes")
        if external_ids is not None and not isinstance(external_ids, dict):
            _log_call(workspace_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "external_ids must be an object.", field="external_ids")
        if consent is not None and not isinstance(consent, dict):
            _log_call(workspace_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "consent must be an object.", field="consent")
        li_err = _validate_list_ids(list_ids)
        if li_err:
            _log_call(workspace_id, li_err["error"]["code"])
            return li_err

        id_err = _enforce_contact_identifiers(email, phone_e164, whatsapp_e164)
        if id_err:
            _log_call(workspace_id, id_err["error"]["code"])
            return id_err

        conf = _uniq_conflict(contacts_rows, workspace_id, email, phone_e164, whatsapp_e164)
        if conf:
            _log_call(workspace_id, conf["error"]["code"])
            return conf

        cid = _gen_id("brv_cnt_")
        row = {
            "id": cid,
            "workspace_id": workspace_id,
            "email": email,
            "phone_e164": phone_e164,
            "whatsapp_e164": whatsapp_e164,
            "first_name": first_name,
            "last_name": last_name,
            "attributes": attributes if isinstance(attributes, dict) else {},
            "list_ids": list_ids if isinstance(list_ids, list) else [],
            "consent": consent if isinstance(consent, dict) else {"consent_updated_at": now},
            "status": status or "active",
            "source": source or "api",
            "external_ids": external_ids if isinstance(external_ids, dict) else {},
            "created_by_principal_id": p.get("id"),
            "updated_by_principal_id": p.get("id"),
            "created_at": now,
            "updated_at": now,
        }
        contacts_rows.append(row)
        _save("contacts.json", contacts_rows)
        _log_call(workspace_id, "OK", credential=p.get("id"))
        return {"data": row}

    if action == "update":
        if not isinstance(contact_id, str) or not cnt_pat.match(contact_id):
            _log_call(workspace_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "contact_id is required and must be a valid id.", field="contact_id")
        c = next((x for x in contacts_rows if x.get("id") == contact_id and x.get("workspace_id") == workspace_id), None)
        if not c:
            _log_call(workspace_id, "NOT_FOUND", credential=p.get("id"))
            return _err("NOT_FOUND", "Contact not found.", contact_id=contact_id)

        # If identifiers are being changed, enforce at least one non-null in result
        new_email = c.get("email") if email is None else email
        new_phone = c.get("phone_e164") if phone_e164 is None else phone_e164
        new_wa = c.get("whatsapp_e164") if whatsapp_e164 is None else whatsapp_e164
        id_err = _enforce_contact_identifiers(new_email, new_phone, new_wa)
        if id_err:
            _log_call(workspace_id, id_err["error"]["code"], credential=p.get("id"))
            return id_err

        # uniqueness checks if changed
        conf = _uniq_conflict(contacts_rows, workspace_id, new_email, new_phone, new_wa, exclude_id=contact_id)
        if conf:
            _log_call(workspace_id, conf["error"]["code"], credential=p.get("id"))
            return conf

        li_err = _validate_list_ids(list_ids)
        if li_err:
            _log_call(workspace_id, li_err["error"]["code"], credential=p.get("id"))
            return li_err

        if status is not None:
            if status not in ("active", "unsubscribed", "bounced", "blacklisted", "deleted"):
                _log_call(workspace_id, "VALIDATION_ERROR", credential=p.get("id"))
                return _err("VALIDATION_ERROR", "Invalid status.", field="status")
            # lifecycle transitions
            transitions = {
                "active": {"unsubscribed", "bounced", "blacklisted", "deleted"},
                "unsubscribed": {"active", "deleted"},
                "bounced": {"active", "blacklisted", "deleted"},
                "blacklisted": {"active", "deleted"},
                "deleted": set(),
            }
            cur = c.get("status")
            if cur != status and status not in transitions.get(cur, set()):
                _log_call(workspace_id, "INVALID_TRANSITION", credential=p.get("id"))
                return _err("INVALID_TRANSITION", "Illegal contact status transition.", from_status=cur, to_status=status)

        if source is not None and source not in ("api", "import", "ecommerce", "crm", "conversation", "unknown"):
            _log_call(workspace_id, "VALIDATION_ERROR", credential=p.get("id"))
            return _err("VALIDATION_ERROR", "Invalid source.", field="source")
        if attributes is not None and not isinstance(attributes, dict):
            _log_call(workspace_id, "VALIDATION_ERROR", credential=p.get("id"))
            return _err("VALIDATION_ERROR", "attributes must be an object.", field="attributes")
        if external_ids is not None and not isinstance(external_ids, dict):
            _log_call(workspace_id, "VALIDATION_ERROR", credential=p.get("id"))
            return _err("VALIDATION_ERROR", "external_ids must be an object.", field="external_ids")
        if consent is not None and not isinstance(consent, dict):
            _log_call(workspace_id, "VALIDATION_ERROR", credential=p.get("id"))
            return _err("VALIDATION_ERROR", "consent must be an object.", field="consent")

        # apply updates
        if email is not None: c["email"] = email
        if phone_e164 is not None: c["phone_e164"] = phone_e164
        if whatsapp_e164 is not None: c["whatsapp_e164"] = whatsapp_e164
        if first_name is not None: c["first_name"] = first_name
        if last_name is not None: c["last_name"] = last_name
        if attributes is not None: c["attributes"] = attributes
        if list_ids is not None: c["list_ids"] = list_ids
        if consent is not None:
            c["consent"] = consent
            if isinstance(c["consent"], dict) and "consent_updated_at" not in c["consent"]:
                c["consent"]["consent_updated_at"] = now
        if status is not None: c["status"] = status
        if source is not None: c["source"] = source
        if external_ids is not None: c["external_ids"] = external_ids

        c["updated_by_principal_id"] = p.get("id")
        c["updated_at"] = now
        _save("contacts.json", contacts_rows)
        _log_call(workspace_id, "OK", credential=p.get("id"))
        return {"data": c}

    if action == "delete":
        if not isinstance(contact_id, str) or not cnt_pat.match(contact_id):
            _log_call(workspace_id, "VALIDATION_ERROR", credential=p.get("id"))
            return _err("VALIDATION_ERROR", "contact_id is required and must be a valid id.", field="contact_id")
        c = next((x for x in contacts_rows if x.get("id") == contact_id and x.get("workspace_id") == workspace_id), None)
        if not c:
            _log_call(workspace_id, "NOT_FOUND", credential=p.get("id"))
            return _err("NOT_FOUND", "Contact not found.", contact_id=contact_id)

        if c.get("status") == "deleted":
            # idempotent delete: return tombstone
            _log_call(workspace_id, "OK", credential=p.get("id"), extra={"idempotent": True})
            return {"data": c}

        transitions = {
            "active": {"deleted"},
            "unsubscribed": {"deleted"},
            "bounced": {"deleted"},
            "blacklisted": {"deleted"},
            "deleted": set(),
        }
        cur = c.get("status")
        if "deleted" not in transitions.get(cur, set()):
            _log_call(workspace_id, "INVALID_TRANSITION", credential=p.get("id"))
            return _err("INVALID_TRANSITION", "Illegal contact status transition to deleted.", from_status=cur, to_status="deleted")

        c["status"] = "deleted"
        c["updated_by_principal_id"] = p.get("id")
        c["updated_at"] = now
        _save("contacts.json", contacts_rows)
        _log_call(workspace_id, "OK", credential=p.get("id"))
        return {"data": c}

    if action == "import":
        if not isinstance(import_job, dict):
            _log_call(workspace_id, "VALIDATION_ERROR", credential=p.get("id"))
            return _err("VALIDATION_ERROR", "import_job payload is required for action=import.", field="import_job")

        # validate import_job schema (additionalProperties=false)
        allowed = {"requested_by_principal_id", "input_format", "raw_input", "attribute_mapping", "target_list_ids", "dedupe_strategy"}
        extra_keys = [k for k in import_job.keys() if k not in allowed]
        if extra_keys:
            _log_call(workspace_id, "VALIDATION_ERROR", credential=p.get("id"))
            return _err("VALIDATION_ERROR", "import_job has unknown fields.", unknown_fields=extra_keys)

        if "input_format" not in import_job or "raw_input" not in import_job:
            _log_call(workspace_id, "VALIDATION_ERROR", credential=p.get("id"))
            return _err("VALIDATION_ERROR", "import_job.input_format and import_job.raw_input are required.")
        input_format = import_job.get("input_format")
        raw_input = import_job.get("raw_input")
        if input_format not in ("pasted_text", "csv", "json"):
            _log_call(workspace_id, "VALIDATION_ERROR", credential=p.get("id"))
            return _err("VALIDATION_ERROR", "Invalid input_format.", field="import_job.input_format")
        if not isinstance(raw_input, str):
            _log_call(workspace_id, "VALIDATION_ERROR", credential=p.get("id"))
            return _err("VALIDATION_ERROR", "raw_input must be a string.", field="import_job.raw_input")
        if len(raw_input.encode("utf-8")) > 5_000_000:
            _log_call(workspace_id, "VALIDATION_ERROR", credential=p.get("id"))
            return _err("VALIDATION_ERROR", "raw_input exceeds maximum size (5,000,000 bytes).", field="import_job.raw_input")

        attribute_mapping = import_job.get("attribute_mapping")
        if attribute_mapping is not None and not isinstance(attribute_mapping, dict):
            _log_call(workspace_id, "VALIDATION_ERROR", credential=p.get("id"))
            return _err("VALIDATION_ERROR", "attribute_mapping must be an object.", field="import_job.attribute_mapping")

        target_list_ids = import_job.get("target_list_ids") or []
        li_err = _validate_list_ids(target_list_ids)
        if li_err:
            _log_call(workspace_id, li_err["error"]["code"], credential=p.get("id"))
            return li_err
        if len(target_list_ids) > 50:
            _log_call(workspace_id, "VALIDATION_ERROR", credential=p.get("id"))
            return _err("VALIDATION_ERROR", "target_list_ids length must be <= 50.", field="import_job.target_list_ids")

        dedupe_strategy = import_job.get("dedupe_strategy") or "skip_duplicates"
        if dedupe_strategy not in ("skip_duplicates", "update_existing", "create_new"):
            _log_call(workspace_id, "VALIDATION_ERROR", credential=p.get("id"))
            return _err("VALIDATION_ERROR", "Invalid dedupe_strategy.", field="import_job.dedupe_strategy")

        # create job queued
        jid = _gen_id("brv_imp_")
        job = {
            "id": jid,
            "workspace_id": workspace_id,
            "requested_by_principal_id": import_job.get("requested_by_principal_id") or p.get("id"),
            "status": "queued",
            "input_format": input_format,
            "raw_input": raw_input,
            "detected_schema": None,
            "attribute_mapping": attribute_mapping,
            "target_list_ids": target_list_ids,
            "dedupe_strategy": dedupe_strategy,
            "summary": {"parsed_rows": 0, "valid_rows": 0, "created_contacts": 0, "updated_contacts": 0, "skipped_duplicates": 0, "errors": []},
            "error": None,
            "created_at": now,
            "updated_at": now,
        }
        import_jobs.append(job)
        _save("contact_import_jobs.json", import_jobs)

        # process transitions queued -> analyzing -> importing -> completed/failed
        def _set_status(st):
            # enforce lifecycle
            transitions = {
                "queued": {"analyzing", "cancelled"},
                "analyzing": {"importing", "failed", "cancelled"},
                "importing": {"completed", "failed", "cancelled"},
                "completed": set(),
                "failed": set(),
                "cancelled": set(),
            }
            cur = job["status"]
            if st != cur and st not in transitions.get(cur, set()):
                return _err("INVALID_TRANSITION", "Illegal import job status transition.", from_status=cur, to_status=st)
            job["status"] = st
            job["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            return None

        e1 = _set_status("analyzing")
        if e1:
            _save("contact_import_jobs.json", import_jobs)
            _log_call(workspace_id, e1["error"]["code"], credential=p.get("id"))
            return e1

        # very lightweight schema detection
        detected = {"likely_fields": {}, "confidence": {}}
        if input_format == "json":
            detected["likely_fields"] = {"email": "email", "phone_e164": "phone", "first_name": "first_name", "last_name": "last_name"}
        elif input_format == "csv":
            detected["likely_fields"] = {"email": "email", "phone_e164": "phone", "first_name": "first_name", "last_name": "last_name"}
        else:
            detected["likely_fields"] = {"email": "email"}
        job["detected_schema"] = detected

        # parse rows
        parsed_rows = []
        parse_errors = []
        if input_format == "json":
            try:
                obj = json.loads(raw_input)
                if isinstance(obj, list):
                    for i, item in enumerate(obj):
                        if isinstance(item, dict):
                            parsed_rows.append(item)
                        else:
                            parse_errors.append({"row": i, "error": "Row is not an object."})
                elif isinstance(obj, dict):
                    # accept {"contacts":[...]}
                    if isinstance(obj.get("contacts"), list):
                        for i, item in enumerate(obj["contacts"]):
                            if isinstance(item, dict):
                                parsed_rows.append(item)
                            else:
                                parse_errors.append({"row": i, "error": "Row is not an object."})
                    else:
                        parse_errors.append({"row": 0, "error": "JSON must be an array of objects or {contacts:[...]}."})
                else:
                    parse_errors.append({"row": 0, "error": "JSON must be an array/object."})
            except json.JSONDecodeError as ex:
                parse_errors.append({"row": 0, "error": f"Invalid JSON: {str(ex)}"})
        elif input_format == "csv":
            import csv, io
            try:
                reader = csv.DictReader(io.StringIO(raw_input))
                for i, r in enumerate(reader):
                    parsed_rows.append(r)
            except Exception as ex:
                parse_errors.append({"row": 0, "error": f"Invalid CSV: {str(ex)}"})
        else:
            # pasted_text: one contact per line, try to detect email/phone
            lines = [ln.strip() for ln in raw_input.splitlines() if ln.strip()]
            for i, ln in enumerate(lines):
                if "@" in ln:
                    parsed_rows.append({"email": ln})
                else:
                    parsed_rows.append({"phone_e164": ln})

        job["summary"]["parsed_rows"] = len(parsed_rows)
        if parse_errors:
            job["summary"]["errors"].extend(parse_errors)

        # dedupe rule: if dedupe_strategy != create_new, require at least one unique key per row
        if dedupe_strategy in ("skip_duplicates", "update_existing"):
            bad_rows = []
            for i, r in enumerate(parsed_rows):
                em = r.get("email") if isinstance(r, dict) else None
                ph = r.get("phone_e164") or r.get("phone") if isinstance(r, dict) else None
                wa = r.get("whatsapp_e164") or r.get("whatsapp") if isinstance(r, dict) else None
                if (em is None or str(em).strip() == "") and (ph is None or str(ph).strip() == "") and (wa is None or str(wa).strip() == ""):
                    bad_rows.append(i)
            if bad_rows:
                _set_status("failed")
                job["error"] = {"message": "Dedupe strategy requires a unique identifier per row.", "bad_rows": bad_rows[:200]}
                job["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                _save("contact_import_jobs.json", import_jobs)
                _log_call(workspace_id, "VALIDATION_ERROR", credential=p.get("id"))
                return _err("VALIDATION_ERROR", "Import job failed validation: rows missing unique identifiers.", bad_rows=bad_rows[:200])

        e2 = _set_status("importing")
        if e2:
            _save("contact_import_jobs.json", import_jobs)
            _log_call(workspace_id, e2["error"]["code"], credential=p.get("id"))
            return e2

        # apply rows
        created = updated = skipped = valid = 0
        row_errors = []

        # copy snapshot for atomic-ish behavior per row, but import as a job is not strictly atomic
        # We'll still avoid partial within a single row.
        for i, r in enumerate(parsed_rows):
            if not isinstance(r, dict):
                row_errors.append({"row": i, "error": "Row is not an object."})
                continue

            em = r.get("email")
            ph = r.get("phone_e164") or r.get("phone")
            wa = r.get("whatsapp_e164") or r.get("whatsapp")
            fn = r.get("first_name")
            ln = r.get("last_name")

            # mapping can override
            if isinstance(attribute_mapping, dict):
                # support {"email":"Email", ...} mapping by reading r[mapped_key]
                for target, src in attribute_mapping.items():
                    if src in r:
                        if target == "email":
                            em = r.get(src)
                        elif target == "phone_e164":
                            ph = r.get(src)
                        elif target == "whatsapp_e164":
                            wa = r.get(src)
                        elif target == "first_name":
                            fn = r.get(src)
                        elif target == "last_name":
                            ln = r.get(src)

            id_err = _enforce_contact_identifiers(em, ph, wa)
            if id_err:
                row_errors.append({"row": i, "error": id_err["error"]["message"]})
                continue

            # find existing contact by identifier
            existing = None
            for c in contacts_rows:
                if c.get("workspace_id") != workspace_id:
                    continue
                if em and c.get("email") == em:
                    existing = c
                    break
                if ph and c.get("phone_e164") == ph:
                    existing = c
                    break
                if wa and c.get("whatsapp_e164") == wa:
                    existing = c
                    break

            if existing:
                if dedupe_strategy == "skip_duplicates":
                    skipped += 1
                    valid += 1
                    continue
                if dedupe_strategy == "update_existing":
                    # uniqueness already by match; but if row provides additional identifiers, ensure they don't conflict with others
                    conf = _uniq_conflict(contacts_rows, workspace_id, em, ph, wa, exclude_id=existing.get("id"))
                    if conf:
                        row_errors.append({"row": i, "error": conf["error"]["message"], "field": conf["error"].get("field")})
                        continue
                    if em is not None and em != "": existing["email"] = em
                    if ph is not None and ph != "": existing["phone_e164"] = ph
                    if wa is not None and wa != "": existing["whatsapp_e164"] = wa
                    if fn is not None: existing["first_name"] = fn
                    if ln is not None: existing["last_name"] = ln
                    # merge list ids
                    if target_list_ids:
                        curset = set(existing.get("list_ids") or [])
                        curset.update(target_list_ids)
                        existing["list_ids"] = sorted(curset)
                    existing["source"] = existing.get("source") or "import"
                    existing["updated_by_principal_id"] = p.get("id")
                    existing["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                    updated += 1
                    valid += 1
                    continue

            # create new
            if dedupe_strategy in ("create_new", "skip_duplicates", "update_existing"):
                # ensure no conflicts (for create_new also)
                conf = _uniq_conflict(contacts_rows, workspace_id, em, ph, wa)
                if conf:
                    if dedupe_strategy == "create_new":
                        row_errors.append({"row": i, "error": conf["error"]["message"], "field": conf["error"].get("field")})
                        continue
                    else:
                        # shouldn't happen because we'd have matched existing; treat as error
                        row_errors.append({"row": i, "error": conf["error"]["message"], "field": conf["error"].get("field")})
                        continue
                cid = _gen_id("brv_cnt_")
                newc = {
                    "id": cid,
                    "workspace_id": workspace_id,
                    "email": em,
                    "phone_e164": ph,
                    "whatsapp_e164": wa,
                    "first_name": fn,
                    "last_name": ln,
                    "attributes": {},
                    "list_ids": list(target_list_ids),
                    "consent": {"consent_updated_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"},
                    "status": "active",
                    "source": "import",
                    "external_ids": {},
                    "created_by_principal_id": p.get("id"),
                    "updated_by_principal_id": p.get("id"),
                    "created_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
                    "updated_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
                }
                contacts_rows.append(newc)
                created += 1
                valid += 1

        job["summary"]["valid_rows"] = valid
        job["summary"]["created_contacts"] = created
        job["summary"]["updated_contacts"] = updated
        job["summary"]["skipped_duplicates"] = skipped
        if row_errors:
            job["summary"]["errors"].extend(row_errors[:1000])

        if parse_errors and not valid:
            _set_status("failed")
            job["error"] = {"message": "Import failed: could not parse input.", "details": parse_errors[:200]}
        else:
            _set_status("completed")

        # persist
        _save("contacts.json", contacts_rows)
        _save("contact_import_jobs.json", import_jobs)

        _log_call(workspace_id, "OK", credential=p.get("id"), extra={"job_status": job["status"], "created": created, "updated": updated})
        return {"data": job}

    _log_call(workspace_id, "VALIDATION_ERROR")
    return _err("VALIDATION_ERROR", "Unhandled action.")

def email(action, workspace_id, message_id=None, template_id=None, name=None, subject=None, from_email=None, from_name=None, to_contact_id=None, to_address=None, payload=None, scheduled_for=None, tracking=None, send_provider_message_id=None, event_type=None, event_at=None, created_by_principal_id=None, status=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0080000" if __import__("os").path.isdir("./environment_mix/0080000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "email"

    wsp_pat = re.compile(r"^brv_wsp_[0-9A-Z]{18,}$")
    msg_pat = re.compile(r"^brv_msg_[0-9A-Z]{18,}$")
    cnt_pat = re.compile(r"^brv_cnt_[0-9A-Z]{18,}$")
    prn_pat = re.compile(r"^brv_prn_[0-9A-Z]{18,}$")

    allowed_actions = {"send", "create_template", "update_template", "get_template", "list_templates", "track_event", "list_events"}
    allowed_event_types = {"delivered", "opened", "clicked", "bounced", "spam", "unsubscribed", "reply", "complaint", "custom", "inbound_received"}
    allowed_status = {"draft", "active", "scheduled", "sending", "sent", "delivered", "opened", "clicked", "bounced", "failed", "paused", "disabled", "received", "processed", "archived", "deleted"}
    allowed_sort_by = {"created_at", "updated_at", "event_at", "name"}
    allowed_sort_order = {"asc", "desc"}

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0)

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        rnd = random.SystemRandom()
        return prefix + "".join(rnd.choice(alphabet) for _ in range(20))

    def _ensure_usage_today(ws):
        if not isinstance(ws.get("usage_today"), dict):
            ws["usage_today"] = {}
        ut = ws["usage_today"]
        for k in ("emails_sent", "sms_sent", "whatsapp_sent", "events_ingested", "api_calls"):
            if not isinstance(ut.get(k), int) or ut.get(k) is None or ut[k] < 0:
                ut[k] = 0

    def _load_rows(filename):
        d = _load(filename)
        if isinstance(d, dict) and isinstance(d.get("rows"), list):
            return d["rows"], d
        if isinstance(d, list):
            return d, None
        return [], None

    def _save_rows(filename, rows, wrapper):
        if wrapper is None:
            _save(filename, rows)
        else:
            wrapper["rows"] = rows
            _save(filename, wrapper)

    def _log_call(ws_row, principal_id, status_code, error=None, extra=None):
        logs, logs_wrapper = _load_rows("request_logs.json")
        _ensure_usage_today(ws_row)
        ws_row["usage_today"]["api_calls"] += 1

        entry = {
            "id": _gen_id("brv_req_"),
            "ts": _now_iso(),
            "endpoint": endpoint,
            "workspace_id": ws_row.get("id"),
            "principal_id": principal_id,
            "status": int(status_code),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if extra:
            entry["meta"] = extra
        if error:
            entry["error"] = error
        logs.append(entry)
        _save_rows("request_logs.json", logs, logs_wrapper)

    # ---- validate base inputs
    if not isinstance(action, str) or action not in allowed_actions:
        return _err("VALIDATION_ERROR", "Invalid action.", allowed=sorted(allowed_actions))
    if not isinstance(workspace_id, str) or not wsp_pat.match(workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id format.")
    if message_id is not None and (not isinstance(message_id, str) or not msg_pat.match(message_id)):
        # accept provider ids passed incorrectly? no: schema says brv_msg_*
        return _err("VALIDATION_ERROR", "Invalid message_id format; must be brv_msg_... id.")
    if template_id is not None and (not isinstance(template_id, str) or not msg_pat.match(template_id)):
        return _err("VALIDATION_ERROR", "Invalid template_id format; must be brv_msg_... id.")
    if to_contact_id is not None and (not isinstance(to_contact_id, str) or not cnt_pat.match(to_contact_id)):
        return _err("VALIDATION_ERROR", "Invalid to_contact_id format.")
    if created_by_principal_id is not None and (not isinstance(created_by_principal_id, str) or not prn_pat.match(created_by_principal_id)):
        return _err("VALIDATION_ERROR", "Invalid created_by_principal_id format.")
    if event_type is not None and (not isinstance(event_type, str) or event_type not in allowed_event_types):
        return _err("VALIDATION_ERROR", "Invalid event_type.", allowed=sorted(allowed_event_types))
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        return _err("VALIDATION_ERROR", "Invalid status.", allowed=sorted(allowed_status))
    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 500:
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if sort_by is not None and (not isinstance(sort_by, str) or sort_by not in allowed_sort_by):
        return _err("VALIDATION_ERROR", "Invalid sort_by.", allowed=sorted(allowed_sort_by))
    if sort_order is not None and (not isinstance(sort_order, str) or sort_order not in allowed_sort_order):
        return _err("VALIDATION_ERROR", "Invalid sort_order.", allowed=sorted(allowed_sort_order))
    if payload is not None and not isinstance(payload, dict):
        return _err("VALIDATION_ERROR", "payload must be an object.")
    if tracking is not None and not isinstance(tracking, dict):
        return _err("VALIDATION_ERROR", "tracking must be an object.")

    scheduled_dt = _parse_dt(scheduled_for) if scheduled_for is not None else None
    if scheduled_for is not None and scheduled_dt is None:
        return _err("VALIDATION_ERROR", "scheduled_for must be an ISO 8601 datetime string.")
    event_dt = _parse_dt(event_at) if event_at is not None else None
    if event_at is not None and event_dt is None:
        return _err("VALIDATION_ERROR", "event_at must be an ISO 8601 datetime string.")

    # ---- resolve workspace
    workspaces, workspaces_wrapper = _load_rows("workspaces.json")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        # cannot log against workspace that doesn't exist
        return _err("NOT_FOUND", "Workspace not found.")
    _ensure_usage_today(ws)

    principals, principals_wrapper = _load_rows("principals.json")
    def _resolve_principal_for_ws():
        if created_by_principal_id:
            p = next((r for r in principals if isinstance(r, dict) and r.get("id") == created_by_principal_id and r.get("workspace_id") == workspace_id), None)
            if not p:
                return None
            return p
        # ambient auth: choose any active principal in workspace
        return next((r for r in principals if isinstance(r, dict) and r.get("workspace_id") == workspace_id and r.get("status") == "active"), None)

    principal = _resolve_principal_for_ws()
    if not principal:
        _log_call(ws, created_by_principal_id, 401, error={"code": "UNAUTHORIZED", "message": "No active principal available for this workspace."})
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)
        return _err("UNAUTHORIZED", "No active principal available for this workspace.")
    # enterprise authorization
    if principal.get("status") != "active":
        _log_call(ws, principal.get("id"), 401, error={"code": "UNAUTHORIZED", "message": "Principal is not active."})
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)
        return _err("UNAUTHORIZED", "Principal is not active.")
    role = principal.get("role")
    if action in {"send", "create_template", "update_template", "track_event"}:
        if role == "read_only":
            _log_call(ws, principal.get("id"), 401, error={"code": "UNAUTHORIZED", "message": "read_only principals cannot mutate."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("UNAUTHORIZED", "read_only principals cannot mutate.")
        if action == "send" and role == "analyst":
            _log_call(ws, principal.get("id"), 401, error={"code": "UNAUTHORIZED", "message": "analyst principals cannot send messages."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("UNAUTHORIZED", "analyst principals cannot send messages.")

    # workspace must be active for sending and template mutations (account tool rule extended to messaging operations)
    if action in {"send", "create_template", "update_template"} and ws.get("status") != "active":
        _log_call(ws, principal.get("id"), 409, error={"code": "CONFLICT", "message": "Workspace must be active for this operation."})
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)
        return _err("CONFLICT", "Workspace must be active for this operation.")

    contacts, contacts_wrapper = _load_rows("contacts.json")
    messaging, messaging_wrapper = _load_rows("messaging_objects.json")

    def _find_contact(cid):
        return next((c for c in contacts if isinstance(c, dict) and c.get("id") == cid and c.get("workspace_id") == workspace_id), None)

    def _find_msg(mid):
        return next((m for m in messaging if isinstance(m, dict) and m.get("id") == mid and m.get("workspace_id") == workspace_id), None)

    # ---- action handlers
    if action == "send":
        # validate recipient (at least one)
        if to_contact_id is None and (to_address is None or not isinstance(to_address, str) or not to_address.strip()):
            _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "Either to_contact_id or to_address is required."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("VALIDATION_ERROR", "Either to_contact_id or to_address is required.")

        contact = None
        resolved_to = None
        if to_contact_id is not None:
            contact = _find_contact(to_contact_id)
            if not contact:
                _log_call(ws, principal.get("id"), 404, error={"code": "NOT_FOUND", "message": "Recipient contact not found in workspace."})
                _save_rows("workspaces.json", workspaces, workspaces_wrapper)
                return _err("NOT_FOUND", "Recipient contact not found in workspace.")
            if isinstance(contact.get("email"), str) and contact.get("email").strip():
                resolved_to = contact.get("email").strip()
            elif isinstance(to_address, str) and to_address.strip():
                # allow explicit override address even if contact doesn't have email
                resolved_to = to_address.strip()
            else:
                _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "Contact has no email; provide to_address."})
                _save_rows("workspaces.json", workspaces, workspaces_wrapper)
                return _err("VALIDATION_ERROR", "Contact has no email; provide to_address.")
        else:
            resolved_to = to_address.strip()

        # template validation if provided
        tpl = None
        if template_id is not None:
            tpl = _find_msg(template_id)
            if not tpl:
                _log_call(ws, principal.get("id"), 404, error={"code": "NOT_FOUND", "message": "template_id not found in workspace."})
                _save_rows("workspaces.json", workspaces, workspaces_wrapper)
                return _err("NOT_FOUND", "template_id not found in workspace.")
            if tpl.get("object_type") != "email_template":
                _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "template_id must reference an email_template messaging object."})
                _save_rows("workspaces.json", workspaces, workspaces_wrapper)
                return _err("VALIDATION_ERROR", "template_id must reference an email_template messaging object.")

        # quotas
        if not isinstance(ws.get("quota_daily_emails"), int) or ws.get("quota_daily_emails") < 0:
            ws["quota_daily_emails"] = 0
        if ws["usage_today"]["emails_sent"] >= ws["quota_daily_emails"]:
            _log_call(ws, principal.get("id"), 429, error={"code": "QUOTA_EXCEEDED", "message": "Daily email quota exceeded."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("QUOTA_EXCEEDED", "Daily email quota exceeded.", quota=ws["quota_daily_emails"], used=ws["usage_today"]["emails_sent"])

        # idempotency-ish: if message_id provided and exists, treat as get (do not create duplicate)
        if message_id is not None:
            existing = _find_msg(message_id)
            if not existing:
                _log_call(ws, principal.get("id"), 404, error={"code": "NOT_FOUND", "message": "message_id not found for idempotent send lookup."})
                _save_rows("workspaces.json", workspaces, workspaces_wrapper)
                return _err("NOT_FOUND", "message_id not found for idempotent send lookup.")
            _log_call(ws, principal.get("id"), 200, extra={"idempotent": True, "message_id": message_id})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return {"message": existing}

        now = _now_dt()
        send_id = _gen_id("brv_msg_")
        send_row = {
            "id": send_id,
            "workspace_id": workspace_id,
            "object_type": "email_transactional_send",
            "status": "sending",
            "name": name,
            "channel": "email",
            "subject": subject,
            "from_email": from_email or ws.get("default_sender_email"),
            "from_name": from_name or ws.get("default_sender_name"),
            "to_contact_id": to_contact_id,
            "to_address": resolved_to,
            "template_id": template_id,
            "payload": payload or {},
            "scheduled_for": scheduled_dt.isoformat().replace("+00:00", "Z") if scheduled_dt else None,
            "send_provider_message_id": send_provider_message_id,
            "tracking": tracking or {},
            "event_type": None,
            "event_at": None,
            "webhook_url": None,
            "webhook_secret": None,
            "enabled_events": None,
            "retry_policy": None,
            "conversation_thread_id": None,
            "inbound_message_id": None,
            "attachments": [],
            "crm_link": {},
            "ecommerce_link": {},
            "created_by_principal_id": principal.get("id"),
            "created_at": now.isoformat().replace("+00:00", "Z"),
            "updated_at": now.isoformat().replace("+00:00", "Z"),
        }

        # scheduled_for implies scheduled status, cannot skip transition
        if scheduled_dt is not None:
            send_row["status"] = "scheduled"
        # immediate completion simulation: scheduled stays scheduled; otherwise transition to sent
        if scheduled_dt is None:
            # legal transition sending->sent; but must not skip sending: keep a short-lived 'sending' row then transition
            send_row["status"] = "sending"
        messaging.append(send_row)

        # if not scheduled, transition to sent (or failed if payload requests failure)
        if scheduled_dt is None:
            will_fail = False
            if isinstance(payload, dict):
                will_fail = bool(payload.get("force_fail")) or bool(payload.get("simulate_fail"))
            if will_fail:
                send_row["status"] = "failed"
            else:
                send_row["status"] = "sent"
                ws["usage_today"]["emails_sent"] += 1
            send_row["updated_at"] = _now_iso()

        # persist
        _save_rows("messaging_objects.json", messaging, messaging_wrapper)
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)

        _log_call(ws, principal.get("id"), 200, extra={"action": "send", "message_id": send_id, "status": send_row["status"]})
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)  # persist api_calls bump
        return {"message": send_row}

    if action == "create_template":
        now = _now_iso()
        tpl_id = _gen_id("brv_msg_")
        tpl_row = {
            "id": tpl_id,
            "workspace_id": workspace_id,
            "object_type": "email_template",
            "status": status or "draft",
            "name": name,
            "channel": "email",
            "subject": subject,
            "from_email": from_email or ws.get("default_sender_email"),
            "from_name": from_name or ws.get("default_sender_name"),
            "to_contact_id": None,
            "to_address": None,
            "template_id": None,
            "payload": payload or {},
            "scheduled_for": None,
            "send_provider_message_id": None,
            "tracking": tracking or {},
            "event_type": None,
            "event_at": None,
            "webhook_url": None,
            "webhook_secret": None,
            "enabled_events": None,
            "retry_policy": None,
            "conversation_thread_id": None,
            "inbound_message_id": None,
            "attachments": [],
            "crm_link": {},
            "ecommerce_link": {},
            "created_by_principal_id": principal.get("id"),
            "created_at": now,
            "updated_at": now,
        }
        if tpl_row["status"] == "scheduled":
            _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "Email templates cannot be created in 'scheduled' status."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("VALIDATION_ERROR", "Email templates cannot be created in 'scheduled' status.")
        messaging.append(tpl_row)
        _save_rows("messaging_objects.json", messaging, messaging_wrapper)
        _log_call(ws, principal.get("id"), 200, extra={"action": "create_template", "template_id": tpl_id})
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)
        return {"template": tpl_row}

    if action == "update_template":
        if template_id is None:
            _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "template_id is required for update_template."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("VALIDATION_ERROR", "template_id is required for update_template.")
        tpl = _find_msg(template_id)
        if not tpl or tpl.get("object_type") != "email_template":
            _log_call(ws, principal.get("id"), 404, error={"code": "NOT_FOUND", "message": "Email template not found."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("NOT_FOUND", "Email template not found.")
        old_status = tpl.get("status")
        if status is not None:
            if status not in allowed_status:
                _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "Invalid status."})
                _save_rows("workspaces.json", workspaces, workspaces_wrapper)
                return _err("VALIDATION_ERROR", "Invalid status.")
            # lifecycle transitions per schema
            transitions = {
                "draft": {"active", "scheduled", "deleted"},
                "active": {"scheduled", "paused", "disabled", "deleted"},
                "scheduled": {"sending", "paused", "disabled", "deleted"},
                "sending": {"sent", "failed"},
                "sent": {"archived"},
                "delivered": {"opened", "clicked", "archived"},
                "opened": {"clicked", "archived"},
                "clicked": {"archived"},
                "bounced": {"archived"},
                "failed": {"archived"},
                "paused": {"active", "disabled", "deleted"},
                "disabled": {"active", "deleted"},
                "received": {"processed", "failed"},
                "processed": {"archived"},
                "archived": set(),
                "deleted": set(),
            }
            if old_status != status:
                if status not in transitions.get(old_status, set()):
                    _log_call(ws, principal.get("id"), 409, error={"code": "INVALID_TRANSITION", "message": f"Illegal status transition {old_status} -> {status}."})
                    _save_rows("workspaces.json", workspaces, workspaces_wrapper)
                    return _err("INVALID_TRANSITION", f"Illegal status transition {old_status} -> {status}.")
                tpl["status"] = status
                if tpl["status"] == "scheduled" and tpl.get("scheduled_for") is None:
                    _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "scheduled_for must be set when status='scheduled'."})
                    _save_rows("workspaces.json", workspaces, workspaces_wrapper)
                    return _err("VALIDATION_ERROR", "scheduled_for must be set when status='scheduled'.")
        if name is not None:
            tpl["name"] = name
        if subject is not None:
            tpl["subject"] = subject
        if from_email is not None:
            tpl["from_email"] = from_email
        if from_name is not None:
            tpl["from_name"] = from_name
        if payload is not None:
            tpl["payload"] = payload
        if tracking is not None:
            tpl["tracking"] = tracking
        if scheduled_for is not None:
            sdt = _parse_dt(scheduled_for)
            if not sdt:
                _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "scheduled_for must be ISO 8601."})
                _save_rows("workspaces.json", workspaces, workspaces_wrapper)
                return _err("VALIDATION_ERROR", "scheduled_for must be ISO 8601.")
            tpl["scheduled_for"] = sdt.isoformat().replace("+00:00", "Z")
        tpl["updated_at"] = _now_iso()
        _save_rows("messaging_objects.json", messaging, messaging_wrapper)
        _log_call(ws, principal.get("id"), 200, extra={"action": "update_template", "template_id": template_id})
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)
        return {"template": tpl}

    if action == "get_template":
        if template_id is None:
            _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "template_id is required for get_template."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("VALIDATION_ERROR", "template_id is required for get_template.")
        tpl = _find_msg(template_id)
        if not tpl or tpl.get("object_type") != "email_template":
            _log_call(ws, principal.get("id"), 404, error={"code": "NOT_FOUND", "message": "Email template not found."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("NOT_FOUND", "Email template not found.")
        _log_call(ws, principal.get("id"), 200, extra={"action": "get_template", "template_id": template_id})
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)
        return {"template": tpl}

    if action == "list_templates":
        lim = limit or 50
        sb = sort_by or "updated_at"
        so = sort_order or "desc"

        rows = [m for m in messaging if isinstance(m, dict) and m.get("workspace_id") == workspace_id and m.get("object_type") == "email_template"]
        if status is not None:
            rows = [m for m in rows if m.get("status") == status]

        def _key(m):
            v = m.get(sb)
            return "" if v is None else v

        rows.sort(key=_key, reverse=(so == "desc"))

        start = 0
        if cursor:
            try:
                start = int(cursor)
                if start < 0:
                    start = 0
            except ValueError:
                _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "Invalid cursor."})
                _save_rows("workspaces.json", workspaces, workspaces_wrapper)
                return _err("VALIDATION_ERROR", "Invalid cursor.")
        page = rows[start:start + lim]
        next_cursor = str(start + lim) if start + lim < len(rows) else None
        _log_call(ws, principal.get("id"), 200, extra={"action": "list_templates", "returned": len(page)})
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)
        return {"templates": page, "total": len(rows), "has_more": next_cursor is not None, "next_cursor": next_cursor}

    if action == "track_event":
        # record an event against a message/template
        target_id = message_id or template_id
        if target_id is None:
            _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "message_id or template_id is required for track_event."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("VALIDATION_ERROR", "message_id or template_id is required for track_event.")
        target = _find_msg(target_id)
        if not target:
            _log_call(ws, principal.get("id"), 404, error={"code": "NOT_FOUND", "message": "Target messaging object not found."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("NOT_FOUND", "Target messaging object not found.")
        if event_type is None:
            _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "event_type is required for track_event."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("VALIDATION_ERROR", "event_type is required for track_event.")

        ev_id = _gen_id("brv_msg_")
        now = _now_iso()
        ev_at = (event_dt or _now_dt()).isoformat().replace("+00:00", "Z")
        ev_row = {
            "id": ev_id,
            "workspace_id": workspace_id,
            "object_type": "email_event",
            "status": "processed",
            "name": name,
            "channel": "email",
            "subject": target.get("subject"),
            "from_email": target.get("from_email"),
            "from_name": target.get("from_name"),
            "to_contact_id": target.get("to_contact_id"),
            "to_address": target.get("to_address"),
            "template_id": target.get("template_id") if target.get("object_type") != "email_template" else target.get("id"),
            "payload": payload or {},
            "scheduled_for": None,
            "send_provider_message_id": send_provider_message_id or target.get("send_provider_message_id"),
            "tracking": target.get("tracking") if isinstance(target.get("tracking"), dict) else {},
            "event_type": event_type,
            "event_at": ev_at,
            "webhook_url": None,
            "webhook_secret": None,
            "enabled_events": None,
            "retry_policy": None,
            "conversation_thread_id": None,
            "inbound_message_id": None,
            "attachments": [],
            "crm_link": {},
            "ecommerce_link": {},
            "created_by_principal_id": principal.get("id"),
            "created_at": now,
            "updated_at": now,
        }
        messaging.append(ev_row)
        _save_rows("messaging_objects.json", messaging, messaging_wrapper)
        _log_call(ws, principal.get("id"), 200, extra={"action": "track_event", "event_id": ev_id, "target_id": target_id})
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)
        return {"event": ev_row}

    if action == "list_events":
        lim = limit or 50
        sb = sort_by or "event_at"
        so = sort_order or "desc"

        rows = [m for m in messaging if isinstance(m, dict) and m.get("workspace_id") == workspace_id and m.get("object_type") == "email_event"]
        if event_type is not None:
            rows = [m for m in rows if m.get("event_type") == event_type]
        if message_id is not None:
            # by provider correlation: match send_provider_message_id or template_id; best-effort
            target = _find_msg(message_id)
            if target:
                spmid = target.get("send_provider_message_id")
                if spmid:
                    rows = [m for m in rows if m.get("send_provider_message_id") == spmid]
                else:
                    rows = [m for m in rows if m.get("to_contact_id") == target.get("to_contact_id") and m.get("subject") == target.get("subject")]
            else:
                # if message_id doesn't exist, return empty set (read filter matches nothing)
                rows = []
        if template_id is not None:
            rows = [m for m in rows if m.get("template_id") == template_id]

        def _key(m):
            v = m.get(sb)
            return "" if v is None else v

        rows.sort(key=_key, reverse=(so == "desc"))

        start = 0
        if cursor:
            try:
                start = int(cursor)
                if start < 0:
                    start = 0
            except ValueError:
                _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "Invalid cursor."})
                _save_rows("workspaces.json", workspaces, workspaces_wrapper)
                return _err("VALIDATION_ERROR", "Invalid cursor.")
        page = rows[start:start + lim]
        next_cursor = str(start + lim) if start + lim < len(rows) else None
        _log_call(ws, principal.get("id"), 200, extra={"action": "list_events", "returned": len(page)})
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)
        return {"events": page, "total": len(rows), "has_more": next_cursor is not None, "next_cursor": next_cursor}

    _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "Unhandled action."})
    _save_rows("workspaces.json", workspaces, workspaces_wrapper)
    return _err("VALIDATION_ERROR", "Unhandled action.")

def campaigns(action, workspace_id, campaign_id=None, name=None, channel=None, subject=None, from_email=None, from_name=None, template_id=None, payload=None, scheduled_for=None, status=None, created_by_principal_id=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0080000" if __import__("os").path.isdir("./environment_mix/0080000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    wsp_pat = re.compile(r"^brv_wsp_[0-9A-Z]{18,}$")
    msg_pat = re.compile(r"^brv_msg_[0-9A-Z]{18,}$")
    prn_pat = re.compile(r"^brv_prn_[0-9A-Z]{18,}$")

    def _gen_id(prefix):
        return prefix + hashlib.sha1((prefix + now + str(time.time())).encode("utf-8")).hexdigest()[:20].upper()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _ensure_usage_today(ws):
        if not isinstance(ws.get("usage_today"), dict):
            ws["usage_today"] = {}
        ut = ws["usage_today"]
        for k in ("emails_sent", "sms_sent", "whatsapp_sent", "events_ingested", "api_calls"):
            if not isinstance(ut.get(k), int) or ut.get(k) < 0:
                ut[k] = 0

    def _log_call(resolved_ws_id, status_code, credential=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "brv_req_" + hashlib.sha1((now + str(time.time())).encode("utf-8")).hexdigest()[:20].upper(),
            "endpoint": "campaigns",
            "action": action,
            "workspace_id": resolved_ws_id,
            "credential": credential,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        if extra is not None:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limit_check(ws):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-5000:]:
            if r.get("workspace_id") != ws["id"]:
                continue
            ts = r.get("timestamp")
            if isinstance(ts, str):
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    cnt += 1
        if cnt >= 240:
            return _err("RATE_LIMIT", "Rate limit exceeded. Try again later.", limit_per_minute=240)
        return None

    def _workspace_and_principal(workspaces, principals, wsid, principal_id, needs_mutation=False):
        ws = next((w for w in workspaces if w.get("id") == wsid), None)
        if not ws:
            return None, None, _err("NOT_FOUND", "Workspace not found.", workspace_id=wsid)
        if ws.get("status") != "active":
            return ws, None, _err("UNAUTHORIZED", "Workspace is not active.", workspace_status=ws.get("status"))
        if principal_id is None:
            candidates = [p for p in principals if p.get("workspace_id") == wsid and p.get("status") == "active"]
            if not candidates:
                return ws, None, _err("UNAUTHORIZED", "No active principal available for this workspace.")
            for p in candidates:
                if needs_mutation and p.get("role") == "read_only":
                    continue
                if action in ("send", "schedule") and p.get("role") in ("read_only", "analyst"):
                    continue
                return ws, p, None
            return ws, None, _err("UNAUTHORIZED", "No authorized principal available for this action.")
        else:
            if not isinstance(principal_id, str) or not prn_pat.match(principal_id):
                return ws, None, _err("VALIDATION_ERROR", "Invalid principal id.", field="created_by_principal_id")
            p = next((x for x in principals if x.get("id") == principal_id and x.get("workspace_id") == wsid), None)
            if not p:
                return ws, None, _err("NOT_FOUND", "Principal not found in workspace.", principal_id=principal_id)
            if p.get("status") != "active":
                return ws, None, _err("UNAUTHORIZED", "Principal is not active.", principal_status=p.get("status"))
            if needs_mutation and p.get("role") == "read_only":
                return ws, None, _err("UNAUTHORIZED", "Principal role is read-only and cannot mutate.")
            if action in ("send", "schedule") and p.get("role") in ("read_only", "analyst"):
                return ws, None, _err("UNAUTHORIZED", "Principal role is not permitted to send messages.")
            return ws, p, None

    def _transition(obj, to_status):
        transitions = {
            "draft": {"active", "scheduled", "deleted"},
            "active": {"scheduled", "paused", "disabled", "deleted"},
            "scheduled": {"sending", "paused", "disabled", "deleted"},
            "sending": {"sent", "failed"},
            "sent": {"archived"},
            "delivered": {"opened", "clicked", "archived"},
            "opened": {"clicked", "archived"},
            "clicked": {"archived"},
            "bounced": {"archived"},
            "failed": {"archived"},
            "paused": {"active", "disabled", "deleted"},
            "disabled": {"active", "deleted"},
            "received": {"processed", "failed"},
            "processed": {"archived"},
            "archived": set(),
            "deleted": set(),
        }
        cur = obj.get("status")
        if cur == to_status:
            return None
        if to_status not in transitions.get(cur, set()):
            return _err("INVALID_TRANSITION", "Illegal campaign status transition.", from_status=cur, to_status=to_status)
        obj["status"] = to_status
        obj["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        return None

    # ---- validate ----
    if action not in ("list", "get", "create", "update", "schedule", "send", "pause", "archive"):
        return _err("VALIDATION_ERROR", "Invalid action.", field="action")
    if not isinstance(workspace_id, str) or not wsp_pat.match(workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.", field="workspace_id")

    workspaces = _load("workspaces.json")
    principals = _load("principals.json")
    msg_rows = _load("messaging_objects.json")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        _log_call(workspace_id, "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    _ensure_usage_today(ws)
    rl = _rate_limit_check(ws)
    if rl:
        _log_call(workspace_id, "RATE_LIMIT")
        return rl

    ws["usage_today"]["api_calls"] += 1
    ws["updated_at"] = now
    _save("workspaces.json", workspaces)

    if action == "list":
        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            _log_call(workspace_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200.", field="limit")
        if cursor is not None and not isinstance(cursor, str):
            _log_call(workspace_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
        if sort_by is None:
            sort_by = "updated_at"
        if sort_by not in ("created_at", "updated_at", "scheduled_for", "name"):
            _log_call(workspace_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid sort_by.", field="sort_by")
        if sort_order is None:
            sort_order = "desc"
        if sort_order not in ("asc", "desc"):
            _log_call(workspace_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid sort_order.", field="sort_order")

        rows = [m for m in msg_rows if m.get("workspace_id") == workspace_id and m.get("object_type") == "campaign"]
        if status is not None:
            if status not in ("draft", "active", "scheduled", "sending", "sent", "delivered", "opened", "clicked", "bounced", "failed", "paused", "disabled", "received", "processed", "archived", "deleted"):
                _log_call(workspace_id, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid status filter.", field="status")
            rows = [m for m in rows if m.get("status") == status]
        if channel is not None:
            if channel not in ("email", "sms", "whatsapp", "chat", "webhook", "inbound"):
                _log_call(workspace_id, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid channel filter.", field="channel")
            rows = [m for m in rows if m.get("channel") == channel]

        def _key(m):
            v = m.get(sort_by)
            return "" if v is None else v
        rows.sort(key=_key, reverse=(sort_order == "desc"))

        offset = 0
        if cursor:
            try:
                offset = int(base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8"))
                if offset < 0:
                    raise ValueError()
            except Exception:
                _log_call(workspace_id, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        total = len(rows)
        page = rows[offset:offset + limit]
        next_off = offset + len(page)
        has_more = next_off < total
        next_cursor = base64.urlsafe_b64encode(str(next_off).encode("utf-8")).decode("utf-8") if has_more else None
        _log_call(workspace_id, "OK", extra={"returned": len(page), "total": total})
        return {"data": page, "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor}}

    if action == "get":
        if not isinstance(campaign_id, str) or not msg_pat.match(campaign_id):
            _log_call(workspace_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "campaign_id is required.", field="campaign_id")
        camp = next((m for m in msg_rows if m.get("id") == campaign_id and m.get("workspace_id") == workspace_id and m.get("object_type") == "campaign"), None)
        if not camp:
            _log_call(workspace_id, "NOT_FOUND")
            return _err("NOT_FOUND", "Campaign not found.", campaign_id=campaign_id)
        _log_call(workspace_id, "OK")
        return {"data": camp}

    if action in ("create", "update", "schedule", "send", "pause", "archive"):
        ws2, p, e = _workspace_and_principal(workspaces, principals, workspace_id, created_by_principal_id, needs_mutation=True)
        if e:
            _log_call(workspace_id, e["error"]["code"])
            return e

    if action == "create":
        if channel is None or channel not in ("email", "sms", "whatsapp"):
            _log_call(workspace_id, "VALIDATION_ERROR", credential=p.get("id"))
            return _err("VALIDATION_ERROR", "channel is required and must be one of email/sms/whatsapp.", field="channel")
        if payload is not None and not isinstance(payload, dict):
            _log_call(workspace_id, "VALIDATION_ERROR", credential=p.get("id"))
            return _err("VALIDATION_ERROR", "payload must be an object.", field="payload")
        if template_id is not None:
            if not isinstance(template_id, str) or not msg_pat.match(template_id):
                _log_call(workspace_id, "VALIDATION_ERROR", credential=p.get("id"))
                return _err("VALIDATION_ERROR", "Invalid template_id.", field="template_id")
            tpl = next((m for m in msg_rows if m.get("id") == template_id and m.get("workspace_id") == workspace_id and m.get("object_type") in ("email_template", "whatsapp_template")), None)
            if not tpl:
                _log_call(workspace_id, "NOT_FOUND", credential=p.get("id"))
                return _err("NOT_FOUND", "Template not found.", template_id=template_id)

        mid = _gen_id("brv_msg_")
        camp = {
            "id": mid,
            "workspace_id": workspace_id,
            "object_type": "campaign",
            "status": "draft",
            "name": name,
            "channel": channel,
            "subject": subject if channel == "email" else None,
            "from_email": from_email if channel == "email" else None,
            "from_name": from_name if channel == "email" else None,
            "to_contact_id": None,
            "to_address": None,
            "template_id": template_id,
            "payload": payload if isinstance(payload, dict) else {},
            "scheduled_for": None,
            "send_provider_message_id": None,
            "tracking": {},
            "event_type": None,
            "event_at": None,
            "webhook_url": None,
            "webhook_secret": None,
            "enabled_events": None,
            "retry_policy": None,
            "conversation_thread_id": None,
            "inbound_message_id": None,
            "attachments": [],
            "crm_link": {},
            "ecommerce_link": {},
            "created_by_principal_id": p.get("id"),
            "created_at": now,
            "updated_at": now,
        }
        msg_rows.append(camp)
        _save("messaging_objects.json", msg_rows)
        _log_call(workspace_id, "OK", credential=p.get("id"))
        return {"data": camp}

    # all remaining actions require campaign_id
    if not isinstance(campaign_id, str) or not msg_pat.match(campaign_id):
        _log_call(workspace_id, "VALIDATION_ERROR", credential=p.get("id") if 'p' in locals() and p else None)
        return _err("VALIDATION_ERROR", "campaign_id is required.", field="campaign_id")
    camp = next((m for m in msg_rows if m.get("id") == campaign_id and m.get("workspace_id") == workspace_id and m.get("object_type") == "campaign"), None)
    if not camp:
        _log_call(workspace_id, "NOT_FOUND", credential=p.get("id"))
        return _err("NOT_FOUND", "Campaign not found.", campaign_id=campaign_id)

    if action == "update":
        # only allow updating while draft/active/paused
        if camp.get("status") not in ("draft", "active", "paused"):
            _log_call(workspace_id, "INVALID_TRANSITION", credential=p.get("id"))
            return _err("INVALID_TRANSITION", "Campaign can only be updated in draft/active/paused.", status=camp.get("status"))
        if channel is not None:
            if channel not in ("email", "sms", "whatsapp"):
                _log_call(workspace_id, "VALIDATION_ERROR", credential=p.get("id"))
                return _err("VALIDATION_ERROR", "Invalid channel.", field="channel")
            camp["channel"] = channel
        if name is not None:
            camp["name"] = name
        if payload is not None:
            if not isinstance(payload, dict):
                _log_call(workspace_id, "VALIDATION_ERROR", credential=p.get("id"))
                return _err("VALIDATION_ERROR", "payload must be an object.", field="payload")
            camp["payload"] = payload
        if template_id is not None:
            if not isinstance(template_id, str) or not msg_pat.match(template_id):
                _log_call(workspace_id, "VALIDATION_ERROR", credential=p.get("id"))
                return _err("VALIDATION_ERROR", "Invalid template_id.", field="template_id")
            tpl = next((m for m in msg_rows if m.get("id") == template_id and m.get("workspace_id") == workspace_id and m.get("object_type") in ("email_template", "whatsapp_template")), None)
            if not tpl:
                _log_call(workspace_id, "NOT_FOUND", credential=p.get("id"))
                return _err("NOT_FOUND", "Template not found.", template_id=template_id)
            camp["template_id"] = template_id
        if subject is not None:
            camp["subject"] = subject
        if from_email is not None:
            camp["from_email"] = from_email
        if from_name is not None:
            camp["from_name"] = from_name

        if status is not None:
            te = _transition(camp, status)
            if te:
                _log_call(workspace_id, te["error"]["code"], credential=p.get("id"))
                return te

        camp["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("messaging_objects.json", msg_rows)
        _log_call(workspace_id, "OK", credential=p.get("id"))
        return {"data": camp}

    if action == "schedule":
        if scheduled_for is None or _parse_dt(scheduled_for) is None:
            _log_call(workspace_id, "VALIDATION_ERROR", credential=p.get("id"))
            return _err("VALIDATION_ERROR", "scheduled_for is required and must be ISO 8601 date-time.", field="scheduled_for")
        camp["scheduled_for"] = scheduled_for
        # campaign must start as draft, may move to scheduled
        if camp.get("status") == "draft":
            # allow draft -> scheduled
            te = _transition(camp, "scheduled")
            if te:
                _log_call(workspace_id, te["error"]["code"], credential=p.get("id"))
                return te
        else:
            # allow active/paused -> scheduled per transitions
            te = _transition(camp, "scheduled")
            if te:
                _log_call(workspace_id, te["error"]["code"], credential=p.get("id"))
                return te
        _save("messaging_objects.json", msg_rows)
        _log_call(workspace_id, "OK", credential=p.get("id"))
        return {"data": camp}

    if action == "send":
        # If scheduled, can send at/after scheduled_for.
        if camp.get("status") == "scheduled":
            sf = _parse_dt(camp.get("scheduled_for"))
            if sf is None:
                _log_call(workspace_id, "VALIDATION_ERROR", credential=p.get("id"))
                return _err("VALIDATION_ERROR", "scheduled_for must be set when campaign is scheduled.")
            if datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) < sf:
                _log_call(workspace_id, "INVALID_TRANSITION", credential=p.get("id"))
                return _err("INVALID_TRANSITION", "Cannot send before scheduled_for.", scheduled_for=camp.get("scheduled_for"))
        # move to sending
        te = _transition(camp, "sending")
        if te:
            _log_call(workspace_id, te["error"]["code"], credential=p.get("id"))
            return te
        # then to sent
        te2 = _transition(camp, "sent")
        if te2:
            _log_call(workspace_id, te2["error"]["code"], credential=p.get("id"))
            return te2
        _save("messaging_objects.json", msg_rows)
        _log_call(workspace_id, "OK", credential=p.get("id"))
        return {"data": camp}

    if action == "pause":
        te = _transition(camp, "paused")
        if te:
            _log_call(workspace_id, te["error"]["code"], credential=p.get("id"))
            return te
        _save("messaging_objects.json", msg_rows)
        _log_call(workspace_id, "OK", credential=p.get("id"))
        return {"data": camp}

    if action == "archive":
        te = _transition(camp, "archived")
        if te:
            _log_call(workspace_id, te["error"]["code"], credential=p.get("id"))
            return te
        _save("messaging_objects.json", msg_rows)
        _log_call(workspace_id, "OK", credential=p.get("id"))
        return {"data": camp}

    _log_call(workspace_id, "VALIDATION_ERROR", credential=p.get("id"))
    return _err("VALIDATION_ERROR", "Unhandled action.")

def sms(action, workspace_id, message_id=None, name=None, to_contact_id=None, to_address=None, payload=None, scheduled_for=None, send_provider_message_id=None, event_type=None, event_at=None, created_by_principal_id=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0080000" if __import__("os").path.isdir("./environment_mix/0080000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "sms"

    wsp_pat = re.compile(r"^brv_wsp_[0-9A-Z]{18,}$")
    msg_pat = re.compile(r"^brv_msg_[0-9A-Z]{18,}$")
    cnt_pat = re.compile(r"^brv_cnt_[0-9A-Z]{18,}$")
    prn_pat = re.compile(r"^brv_prn_[0-9A-Z]{18,}$")

    allowed_actions = {"send", "track_event", "list_events"}
    allowed_event_types = {"delivered", "opened", "clicked", "bounced", "spam", "unsubscribed", "reply", "complaint", "custom", "inbound_received"}
    allowed_sort_by = {"created_at", "updated_at", "event_at"}
    allowed_sort_order = {"asc", "desc"}

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0)

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        rnd = random.SystemRandom()
        return prefix + "".join(rnd.choice(alphabet) for _ in range(20))

    def _ensure_usage_today(ws):
        if not isinstance(ws.get("usage_today"), dict):
            ws["usage_today"] = {}
        ut = ws["usage_today"]
        for k in ("emails_sent", "sms_sent", "whatsapp_sent", "events_ingested", "api_calls"):
            if not isinstance(ut.get(k), int) or ut.get(k) is None or ut[k] < 0:
                ut[k] = 0

    def _load_rows(filename):
        d = _load(filename)
        if isinstance(d, dict) and isinstance(d.get("rows"), list):
            return d["rows"], d
        if isinstance(d, list):
            return d, None
        return [], None

    def _save_rows(filename, rows, wrapper):
        if wrapper is None:
            _save(filename, rows)
        else:
            wrapper["rows"] = rows
            _save(filename, wrapper)

    def _log_call(ws_row, principal_id, status_code, error=None, extra=None):
        logs, logs_wrapper = _load_rows("request_logs.json")
        _ensure_usage_today(ws_row)
        ws_row["usage_today"]["api_calls"] += 1
        entry = {
            "id": _gen_id("brv_req_"),
            "ts": _now_iso(),
            "endpoint": endpoint,
            "workspace_id": ws_row.get("id"),
            "principal_id": principal_id,
            "status": int(status_code),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if extra:
            entry["meta"] = extra
        if error:
            entry["error"] = error
        logs.append(entry)
        _save_rows("request_logs.json", logs, logs_wrapper)

    # validate base
    if not isinstance(action, str) or action not in allowed_actions:
        return _err("VALIDATION_ERROR", "Invalid action.", allowed=sorted(allowed_actions))
    if not isinstance(workspace_id, str) or not wsp_pat.match(workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id format.")
    if message_id is not None and (not isinstance(message_id, str) or not msg_pat.match(message_id)):
        return _err("VALIDATION_ERROR", "Invalid message_id format.")
    if to_contact_id is not None and (not isinstance(to_contact_id, str) or not cnt_pat.match(to_contact_id)):
        return _err("VALIDATION_ERROR", "Invalid to_contact_id format.")
    if created_by_principal_id is not None and (not isinstance(created_by_principal_id, str) or not prn_pat.match(created_by_principal_id)):
        return _err("VALIDATION_ERROR", "Invalid created_by_principal_id format.")
    if event_type is not None and (not isinstance(event_type, str) or event_type not in allowed_event_types):
        return _err("VALIDATION_ERROR", "Invalid event_type.", allowed=sorted(allowed_event_types))
    if limit is not None and (not isinstance(limit, int) or limit < 1 or limit > 500):
        return _err("VALIDATION_ERROR", "limit must be 1..500.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if sort_by is not None and (not isinstance(sort_by, str) or sort_by not in allowed_sort_by):
        return _err("VALIDATION_ERROR", "Invalid sort_by.", allowed=sorted(allowed_sort_by))
    if sort_order is not None and (not isinstance(sort_order, str) or sort_order not in allowed_sort_order):
        return _err("VALIDATION_ERROR", "Invalid sort_order.", allowed=sorted(allowed_sort_order))
    if payload is not None and not isinstance(payload, dict):
        return _err("VALIDATION_ERROR", "payload must be an object.")

    scheduled_dt = _parse_dt(scheduled_for) if scheduled_for is not None else None
    if scheduled_for is not None and scheduled_dt is None:
        return _err("VALIDATION_ERROR", "scheduled_for must be an ISO 8601 datetime string.")
    event_dt = _parse_dt(event_at) if event_at is not None else None
    if event_at is not None and event_dt is None:
        return _err("VALIDATION_ERROR", "event_at must be an ISO 8601 datetime string.")

    workspaces, workspaces_wrapper = _load_rows("workspaces.json")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.")
    _ensure_usage_today(ws)

    principals, principals_wrapper = _load_rows("principals.json")
    def _resolve_principal():
        if created_by_principal_id:
            return next((p for p in principals if isinstance(p, dict) and p.get("id") == created_by_principal_id and p.get("workspace_id") == workspace_id), None)
        return next((p for p in principals if isinstance(p, dict) and p.get("workspace_id") == workspace_id and p.get("status") == "active"), None)

    principal = _resolve_principal()
    if not principal or principal.get("status") != "active":
        _log_call(ws, created_by_principal_id, 401, error={"code": "UNAUTHORIZED", "message": "No active principal available for this workspace."})
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)
        return _err("UNAUTHORIZED", "No active principal available for this workspace.")
    role = principal.get("role")
    if action in {"send", "track_event"}:
        if role == "read_only":
            _log_call(ws, principal.get("id"), 401, error={"code": "UNAUTHORIZED", "message": "read_only principals cannot mutate."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("UNAUTHORIZED", "read_only principals cannot mutate.")
        if action == "send" and role == "analyst":
            _log_call(ws, principal.get("id"), 401, error={"code": "UNAUTHORIZED", "message": "analyst principals cannot send messages."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("UNAUTHORIZED", "analyst principals cannot send messages.")
    if action == "send" and ws.get("status") != "active":
        _log_call(ws, principal.get("id"), 409, error={"code": "CONFLICT", "message": "Workspace must be active for sending."})
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)
        return _err("CONFLICT", "Workspace must be active for sending.")

    contacts, contacts_wrapper = _load_rows("contacts.json")
    messaging, messaging_wrapper = _load_rows("messaging_objects.json")

    def _find_contact(cid):
        return next((c for c in contacts if isinstance(c, dict) and c.get("id") == cid and c.get("workspace_id") == workspace_id), None)

    def _find_msg(mid):
        return next((m for m in messaging if isinstance(m, dict) and m.get("id") == mid and m.get("workspace_id") == workspace_id), None)

    if action == "send":
        if to_contact_id is None and (to_address is None or not isinstance(to_address, str) or not to_address.strip()):
            _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "Either to_contact_id or to_address is required."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("VALIDATION_ERROR", "Either to_contact_id or to_address is required.")

        contact = None
        resolved_to = None
        consent = None
        if to_contact_id is not None:
            contact = _find_contact(to_contact_id)
            if not contact:
                _log_call(ws, principal.get("id"), 404, error={"code": "NOT_FOUND", "message": "Recipient contact not found in workspace."})
                _save_rows("workspaces.json", workspaces, workspaces_wrapper)
                return _err("NOT_FOUND", "Recipient contact not found in workspace.")
            if isinstance(contact.get("phone_e164"), str) and contact.get("phone_e164").strip():
                resolved_to = contact.get("phone_e164").strip()
            elif isinstance(to_address, str) and to_address.strip():
                resolved_to = to_address.strip()
            else:
                _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "Contact has no phone_e164; provide to_address."})
                _save_rows("workspaces.json", workspaces, workspaces_wrapper)
                return _err("VALIDATION_ERROR", "Contact has no phone_e164; provide to_address.")
            consent = contact.get("consent") if isinstance(contact.get("consent"), dict) else {}
        else:
            resolved_to = to_address.strip()
            consent = {}

        # enforce sms_opt_in when present, unless override flag exists in payload
        override = False
        if isinstance(payload, dict):
            override = bool(payload.get("override_opt_in")) or bool(payload.get("ignore_opt_in"))
        sms_opt_in = consent.get("sms_opt_in")
        if sms_opt_in is False and not override:
            _log_call(ws, principal.get("id"), 409, error={"code": "CONFLICT", "message": "Contact has sms_opt_in=false; provide payload.override_opt_in=true to override."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("CONFLICT", "Contact has sms_opt_in=false; provide payload.override_opt_in=true to override.")

        # quota
        if not isinstance(ws.get("quota_daily_sms"), int) or ws.get("quota_daily_sms") < 0:
            ws["quota_daily_sms"] = 0
        if ws["usage_today"]["sms_sent"] >= ws["quota_daily_sms"]:
            _log_call(ws, principal.get("id"), 429, error={"code": "QUOTA_EXCEEDED", "message": "Daily SMS quota exceeded."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("QUOTA_EXCEEDED", "Daily SMS quota exceeded.", quota=ws["quota_daily_sms"], used=ws["usage_today"]["sms_sent"])

        # idempotency behavior with message_id
        if message_id is not None:
            existing = _find_msg(message_id)
            if not existing:
                _log_call(ws, principal.get("id"), 404, error={"code": "NOT_FOUND", "message": "message_id not found for idempotent send lookup."})
                _save_rows("workspaces.json", workspaces, workspaces_wrapper)
                return _err("NOT_FOUND", "message_id not found for idempotent send lookup.")
            _log_call(ws, principal.get("id"), 200, extra={"idempotent": True, "message_id": message_id})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return {"message": existing}

        now = _now_iso()
        send_id = _gen_id("brv_msg_")
        send_row = {
            "id": send_id,
            "workspace_id": workspace_id,
            "object_type": "sms_transactional_send",
            "status": "sending",
            "name": name,
            "channel": "sms",
            "subject": None,
            "from_email": None,
            "from_name": None,
            "to_contact_id": to_contact_id,
            "to_address": resolved_to,
            "template_id": None,
            "payload": payload or {},
            "scheduled_for": scheduled_dt.isoformat().replace("+00:00", "Z") if scheduled_dt else None,
            "send_provider_message_id": send_provider_message_id,
            "tracking": {},
            "event_type": None,
            "event_at": None,
            "webhook_url": None,
            "webhook_secret": None,
            "enabled_events": None,
            "retry_policy": None,
            "conversation_thread_id": None,
            "inbound_message_id": None,
            "attachments": [],
            "crm_link": {},
            "ecommerce_link": {},
            "created_by_principal_id": principal.get("id"),
            "created_at": now,
            "updated_at": now,
        }
        if scheduled_dt is not None:
            send_row["status"] = "scheduled"
        messaging.append(send_row)

        if scheduled_dt is None:
            will_fail = bool((payload or {}).get("force_fail")) or bool((payload or {}).get("simulate_fail"))
            if will_fail:
                send_row["status"] = "failed"
            else:
                send_row["status"] = "sent"
                ws["usage_today"]["sms_sent"] += 1
            send_row["updated_at"] = _now_iso()

        _save_rows("messaging_objects.json", messaging, messaging_wrapper)
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)
        _log_call(ws, principal.get("id"), 200, extra={"action": "send", "message_id": send_id, "status": send_row["status"]})
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)
        return {"message": send_row}

    if action == "track_event":
        if message_id is None:
            _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "message_id is required for track_event."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("VALIDATION_ERROR", "message_id is required for track_event.")
        msg = _find_msg(message_id)
        if not msg or msg.get("object_type") != "sms_transactional_send":
            _log_call(ws, principal.get("id"), 404, error={"code": "NOT_FOUND", "message": "SMS message not found."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("NOT_FOUND", "SMS message not found.")
        if event_type is None:
            _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "event_type is required."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("VALIDATION_ERROR", "event_type is required.")
        ev_id = _gen_id("brv_msg_")
        now = _now_iso()
        ev_at = (event_dt or _now_dt()).isoformat().replace("+00:00", "Z")
        ev_row = {
            "id": ev_id,
            "workspace_id": workspace_id,
            "object_type": "custom_event",  # reuse polymorphic event row for sms event stream
            "status": "processed",
            "name": name,
            "channel": "sms",
            "subject": None,
            "from_email": None,
            "from_name": None,
            "to_contact_id": msg.get("to_contact_id"),
            "to_address": msg.get("to_address"),
            "template_id": None,
            "payload": payload or {},
            "scheduled_for": None,
            "send_provider_message_id": send_provider_message_id or msg.get("send_provider_message_id"),
            "tracking": {},
            "event_type": event_type,
            "event_at": ev_at,
            "webhook_url": None,
            "webhook_secret": None,
            "enabled_events": None,
            "retry_policy": None,
            "conversation_thread_id": None,
            "inbound_message_id": None,
            "attachments": [],
            "crm_link": {},
            "ecommerce_link": {},
            "created_by_principal_id": principal.get("id"),
            "created_at": now,
            "updated_at": now,
        }
        messaging.append(ev_row)
        _save_rows("messaging_objects.json", messaging, messaging_wrapper)
        _log_call(ws, principal.get("id"), 200, extra={"action": "track_event", "event_id": ev_id, "message_id": message_id})
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)
        return {"event": ev_row}

    if action == "list_events":
        lim = limit or 50
        sb = sort_by or "event_at"
        so = sort_order or "desc"

        rows = [m for m in messaging if isinstance(m, dict) and m.get("workspace_id") == workspace_id and m.get("channel") == "sms" and m.get("event_type") is not None and m.get("event_at") is not None]
        if event_type is not None:
            rows = [m for m in rows if m.get("event_type") == event_type]
        if message_id is not None:
            msg = _find_msg(message_id)
            if msg and msg.get("send_provider_message_id"):
                rows = [m for m in rows if m.get("send_provider_message_id") == msg.get("send_provider_message_id")]
            elif msg:
                rows = [m for m in rows if m.get("to_address") == msg.get("to_address")]
            else:
                rows = []

        def _key(m):
            v = m.get(sb)
            return "" if v is None else v

        rows.sort(key=_key, reverse=(so == "desc"))
        start = 0
        if cursor:
            try:
                start = int(cursor)
                if start < 0:
                    start = 0
            except ValueError:
                _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "Invalid cursor."})
                _save_rows("workspaces.json", workspaces, workspaces_wrapper)
                return _err("VALIDATION_ERROR", "Invalid cursor.")

        page = rows[start:start + lim]
        next_cursor = str(start + lim) if start + lim < len(rows) else None
        _log_call(ws, principal.get("id"), 200, extra={"action": "list_events", "returned": len(page)})
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)
        return {"events": page, "total": len(rows), "has_more": next_cursor is not None, "next_cursor": next_cursor}

    _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "Unhandled action."})
    _save_rows("workspaces.json", workspaces, workspaces_wrapper)
    return _err("VALIDATION_ERROR", "Unhandled action.")

def conversations(action, workspace_id, thread_id=None, message_id=None, to_contact_id=None, name=None, payload=None, attachments=None, status=None, inbound_message_id=None, crm_link=None, ecommerce_link=None, created_by_principal_id=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0080000" if __import__("os").path.isdir("./environment_mix/0080000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "conversations"
    used_principal_id = created_by_principal_id

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, error=None, extra=None):
        try:
            wss = _load("workspaces.json")
            ws = next((w for w in wss if w.get("id") == workspace_id), None)
            # bump api_calls if possible
            if ws is not None:
                ut = ws.get("usage_today") if isinstance(ws.get("usage_today"), dict) else {}
                ut["api_calls"] = int(ut.get("api_calls", 0) or 0) + 1
                ws["usage_today"] = ut
                ws["updated_at"] = _now()
                _save("workspaces.json", wss)
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            row = {
                "id": "brv_req_" + base64.b32encode(os.urandom(12)).decode("ascii").rstrip("="),
                "timestamp": _now(),
                "endpoint": endpoint,
                "action": action,
                "workspace_id": workspace_id,
                "principal_id": used_principal_id,
                "status": status_code,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            if error is not None:
                row["error"] = error
            if isinstance(extra, dict):
                row.update(extra)
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            # Logging must not break the call.
            pass

    def _validate_regex(val, pat):
        return isinstance(val, str) and re.match(pat, val) is not None

    def _decode_cursor(cur):
        if not cur:
            return 0
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if s.startswith("off:"):
                return max(0, int(s.split(":", 1)[1]))
        except Exception:
            return None
        return None

    def _encode_cursor(off):
        return base64.urlsafe_b64encode(f"off:{off}".encode("utf-8")).decode("utf-8").rstrip("=")

    def _check_principal_can_mutate(principals, wsid, pid, allow_send=True):
        # Ambient auth: if pid omitted, accept as system actor when workspace exists.
        if pid is None:
            return True, None
        pr = next((p for p in principals if p.get("id") == pid and p.get("workspace_id") == wsid), None)
        if pr is None:
            return False, _err("NOT_FOUND", "Principal not found", principal_id=pid)
        if pr.get("status") != "active":
            return False, _err("UNAUTHORIZED", "Principal is not active", principal_id=pid, status=pr.get("status"))
        role = pr.get("role")
        if role == "read_only":
            return False, _err("UNAUTHORIZED", "Principal role cannot perform mutations", role=role)
        if (not allow_send) and role == "analyst":
            return False, _err("UNAUTHORIZED", "Analyst role cannot send messages", role=role)
        return True, pr

    try:
        # Basic validations
        if action not in {"list_threads", "get_thread", "create_thread", "list_messages", "send_message", "track_inbound"}:
            _log(400, {"code": "VALIDATION_ERROR", "message": "Invalid action"})
            return _err("VALIDATION_ERROR", "Invalid action", field="action")
        if not _validate_regex(workspace_id, r"^brv_wsp_[0-9A-Z]{18,}$"):
            _log(400, {"code": "VALIDATION_ERROR", "message": "Invalid workspace_id"})
            return _err("VALIDATION_ERROR", "Invalid workspace_id", field="workspace_id")
        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            _log(400, {"code": "VALIDATION_ERROR", "message": "Invalid limit"})
            return _err("VALIDATION_ERROR", "Invalid limit", field="limit", minimum=1, maximum=200)
        if sort_by is None:
            sort_by = "updated_at"
        if sort_by not in {"created_at", "updated_at"}:
            _log(400, {"code": "VALIDATION_ERROR", "message": "Invalid sort_by"})
            return _err("VALIDATION_ERROR", "Invalid sort_by", field="sort_by")
        if sort_order is None:
            sort_order = "desc"
        if sort_order not in {"asc", "desc"}:
            _log(400, {"code": "VALIDATION_ERROR", "message": "Invalid sort_order"})
            return _err("VALIDATION_ERROR", "Invalid sort_order", field="sort_order")
        if status is not None and status not in {"draft","active","scheduled","sending","sent","delivered","opened","clicked","bounced","failed","paused","disabled","received","processed","archived","deleted"}:
            _log(400, {"code": "VALIDATION_ERROR", "message": "Invalid status"})
            return _err("VALIDATION_ERROR", "Invalid status", field="status")

        wss = _load("workspaces.json")
        ws = next((w for w in wss if w.get("id") == workspace_id), None)
        if ws is None:
            _log(404, {"code": "NOT_FOUND", "message": "Workspace not found"})
            return _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)

        principals = _load("principals.json")
        contacts = _load("contacts.json")
        msgs = _load("messaging_objects.json")

        def _new_id(prefix):
            return prefix + base64.b32encode(os.urandom(12)).decode("ascii").rstrip("=")

        def _find_msg(mid):
            return next((m for m in msgs if m.get("id") == mid and m.get("workspace_id") == workspace_id), None)

        def _transition(obj, to_status):
            transitions = {
                "draft": ["active", "scheduled", "deleted"],
                "active": ["scheduled", "paused", "disabled", "deleted"],
                "scheduled": ["sending", "paused", "disabled", "deleted"],
                "sending": ["sent", "failed"],
                "sent": ["archived"],
                "delivered": ["opened", "clicked", "archived"],
                "opened": ["clicked", "archived"],
                "clicked": ["archived"],
                "bounced": ["archived"],
                "failed": ["archived"],
                "paused": ["active", "disabled", "deleted"],
                "disabled": ["active", "deleted"],
                "received": ["processed", "failed"],
                "processed": ["archived"],
                "archived": [],
                "deleted": [],
            }
            cur = obj.get("status")
            if cur == to_status:
                return True, None
            allowed = transitions.get(cur, [])
            if to_status not in allowed:
                return False, _err("INVALID_TRANSITION", "Illegal status transition", from_status=cur, to_status=to_status)
            obj["status"] = to_status
            obj["updated_at"] = _now()
            return True, None

        if action == "list_threads":
            rows = [m for m in msgs if m.get("workspace_id") == workspace_id and m.get("object_type") == "conversation_thread"]
            if status is not None:
                rows = [r for r in rows if r.get("status") == status]
            # sort
            rev = (sort_order == "desc")
            rows.sort(key=lambda r: (r.get(sort_by) or ""), reverse=rev)
            off = _decode_cursor(cursor)
            if off is None:
                _log(400, {"code": "VALIDATION_ERROR", "message": "Invalid cursor"})
                return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
            total = len(rows)
            page = rows[off:off + limit]
            next_off = off + len(page)
            has_more = next_off < total
            res = {"threads": page, "total": total, "has_more": has_more, "next_cursor": _encode_cursor(next_off) if has_more else None}
            _log(200)
            return res

        if action == "get_thread":
            if not thread_id or not _validate_regex(thread_id, r"^brv_msg_[0-9A-Z]{18,}$"):
                _log(400, {"code": "VALIDATION_ERROR", "message": "Invalid thread_id"})
                return _err("VALIDATION_ERROR", "Invalid thread_id", field="thread_id")
            th = _find_msg(thread_id)
            if th is None or th.get("object_type") != "conversation_thread":
                _log(404, {"code": "NOT_FOUND", "message": "Thread not found"})
                return _err("NOT_FOUND", "Thread not found", thread_id=thread_id)
            _log(200)
            return {"thread": th}

        if action == "create_thread":
            ok, perr = _check_principal_can_mutate(principals, workspace_id, created_by_principal_id, allow_send=True)
            if not ok:
                _log(401, perr["error"])
                return perr
            if ws.get("status") != "active":
                _log(409, {"code": "CONFLICT", "message": "Workspace is not active"})
                return _err("CONFLICT", "Workspace is not active", status=ws.get("status"))
            if to_contact_id is not None and not _validate_regex(to_contact_id, r"^brv_cnt_[0-9A-Z]{18,}$"):
                _log(400, {"code": "VALIDATION_ERROR", "message": "Invalid to_contact_id"})
                return _err("VALIDATION_ERROR", "Invalid to_contact_id", field="to_contact_id")
            if to_contact_id is not None:
                c = next((c for c in contacts if c.get("id") == to_contact_id and c.get("workspace_id") == workspace_id), None)
                if c is None:
                    _log(404, {"code": "NOT_FOUND", "message": "Contact not found"})
                    return _err("NOT_FOUND", "Contact not found", to_contact_id=to_contact_id)

            mid = _new_id("brv_msg_")
            now = _now()
            row = {
                "id": mid,
                "workspace_id": workspace_id,
                "object_type": "conversation_thread",
                "status": "active" if status is None else status,
                "name": name,
                "channel": "chat",
                "subject": None,
                "from_email": None,
                "from_name": None,
                "to_contact_id": to_contact_id,
                "to_address": None,
                "template_id": None,
                "payload": payload if isinstance(payload, dict) else {},
                "scheduled_for": None,
                "send_provider_message_id": None,
                "tracking": {},
                "event_type": None,
                "event_at": None,
                "webhook_url": None,
                "webhook_secret": None,
                "enabled_events": None,
                "retry_policy": None,
                "conversation_thread_id": None,
                "inbound_message_id": None,
                "attachments": [],
                "crm_link": crm_link if isinstance(crm_link, dict) else {},
                "ecommerce_link": ecommerce_link if isinstance(ecommerce_link, dict) else {},
                "created_by_principal_id": created_by_principal_id,
                "created_at": now,
                "updated_at": now,
            }
            # validate status for thread (must be allowed enum; already) and transitions: treat creation as draft->status if not draft
            if row["status"] not in {"draft","active","archived","deleted","paused","disabled","received","processed","scheduled","sending","sent","delivered","opened","clicked","bounced","failed"}:
                _log(400, {"code":"VALIDATION_ERROR","message":"Invalid status"})
                return _err("VALIDATION_ERROR", "Invalid status", field="status")
            msgs.append(row)
            _save("messaging_objects.json", msgs)
            _log(201)
            return {"thread": row}

        if action == "list_messages":
            if not thread_id or not _validate_regex(thread_id, r"^brv_msg_[0-9A-Z]{18,}$"):
                _log(400, {"code": "VALIDATION_ERROR", "message": "Invalid thread_id"})
                return _err("VALIDATION_ERROR", "Invalid thread_id", field="thread_id")
            th = _find_msg(thread_id)
            if th is None or th.get("object_type") != "conversation_thread":
                _log(404, {"code": "NOT_FOUND", "message": "Thread not found"})
                return _err("NOT_FOUND", "Thread not found", thread_id=thread_id)
            rows = [m for m in msgs if m.get("workspace_id") == workspace_id and m.get("object_type") == "conversation_message" and m.get("conversation_thread_id") == thread_id]
            if status is not None:
                rows = [r for r in rows if r.get("status") == status]
            rev = (sort_order == "desc")
            rows.sort(key=lambda r: (r.get(sort_by) or ""), reverse=rev)
            off = _decode_cursor(cursor)
            if off is None:
                _log(400, {"code": "VALIDATION_ERROR", "message": "Invalid cursor"})
                return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
            total = len(rows)
            page = rows[off:off + limit]
            next_off = off + len(page)
            has_more = next_off < total
            _log(200)
            return {"messages": page, "total": total, "has_more": has_more, "next_cursor": _encode_cursor(next_off) if has_more else None}

        if action == "send_message":
            ok, perr = _check_principal_can_mutate(principals, workspace_id, created_by_principal_id, allow_send=True)
            if not ok:
                _log(401, perr["error"])
                return perr
            if ws.get("status") != "active":
                _log(409, {"code": "CONFLICT", "message": "Workspace is not active"})
                return _err("CONFLICT", "Workspace is not active", status=ws.get("status"))
            if not thread_id or not _validate_regex(thread_id, r"^brv_msg_[0-9A-Z]{18,}$"):
                _log(400, {"code": "VALIDATION_ERROR", "message": "Invalid thread_id"})
                return _err("VALIDATION_ERROR", "Invalid thread_id", field="thread_id")
            th = _find_msg(thread_id)
            if th is None or th.get("object_type") != "conversation_thread":
                _log(404, {"code": "NOT_FOUND", "message": "Thread not found"})
                return _err("NOT_FOUND", "Thread not found", thread_id=thread_id)
            if th.get("status") in {"deleted"}:
                _log(409, {"code":"CONFLICT","message":"Cannot send message to deleted thread"})
                return _err("CONFLICT", "Cannot send message to deleted thread", thread_status=th.get("status"))

            if payload is None or not isinstance(payload, dict):
                _log(400, {"code":"VALIDATION_ERROR","message":"payload must be an object"})
                return _err("VALIDATION_ERROR", "payload must be an object", field="payload")
            if attachments is None:
                attachments = []
            if not isinstance(attachments, list):
                _log(400, {"code":"VALIDATION_ERROR","message":"attachments must be an array"})
                return _err("VALIDATION_ERROR", "attachments must be an array", field="attachments")

            mid = _new_id("brv_msg_")
            now = _now()
            row = {
                "id": mid,
                "workspace_id": workspace_id,
                "object_type": "conversation_message",
                "status": "sent" if status is None else status,
                "name": None,
                "channel": "chat",
                "subject": None,
                "from_email": None,
                "from_name": None,
                "to_contact_id": to_contact_id if to_contact_id else th.get("to_contact_id"),
                "to_address": None,
                "template_id": None,
                "payload": payload,
                "scheduled_for": None,
                "send_provider_message_id": None,
                "tracking": {},
                "event_type": None,
                "event_at": None,
                "webhook_url": None,
                "webhook_secret": None,
                "enabled_events": None,
                "retry_policy": None,
                "conversation_thread_id": thread_id,
                "inbound_message_id": None,
                "attachments": attachments,
                "crm_link": crm_link if isinstance(crm_link, dict) else {},
                "ecommerce_link": ecommerce_link if isinstance(ecommerce_link, dict) else {},
                "created_by_principal_id": created_by_principal_id,
                "created_at": now,
                "updated_at": now,
            }
            msgs.append(row)
            # Touch thread updated_at
            th["updated_at"] = now
            _save("messaging_objects.json", msgs)
            _log(201)
            return {"message": row, "thread": th}

        if action == "track_inbound":
            # record inbound message as conversation_message with status received -> processed
            if not thread_id or not _validate_regex(thread_id, r"^brv_msg_[0-9A-Z]{18,}$"):
                _log(400, {"code": "VALIDATION_ERROR", "message": "Invalid thread_id"})
                return _err("VALIDATION_ERROR", "Invalid thread_id", field="thread_id")
            th = _find_msg(thread_id)
            if th is None or th.get("object_type") != "conversation_thread":
                _log(404, {"code": "NOT_FOUND", "message": "Thread not found"})
                return _err("NOT_FOUND", "Thread not found", thread_id=thread_id)
            if not inbound_message_id or not isinstance(inbound_message_id, str):
                _log(400, {"code":"VALIDATION_ERROR","message":"inbound_message_id is required"})
                return _err("VALIDATION_ERROR", "inbound_message_id is required", field="inbound_message_id")
            if payload is None or not isinstance(payload, dict):
                _log(400, {"code":"VALIDATION_ERROR","message":"payload must be an object"})
                return _err("VALIDATION_ERROR", "payload must be an object", field="payload")
            if attachments is None:
                attachments = []
            if not isinstance(attachments, list):
                _log(400, {"code":"VALIDATION_ERROR","message":"attachments must be an array"})
                return _err("VALIDATION_ERROR", "attachments must be an array", field="attachments")

            # idempotency by inbound_message_id within thread
            existing = next((m for m in msgs if m.get("workspace_id") == workspace_id and m.get("object_type") == "conversation_message"
                             and m.get("conversation_thread_id") == thread_id and m.get("inbound_message_id") == inbound_message_id), None)
            if existing is not None:
                _log(200)
                return {"message": existing, "idempotent": True}

            mid = _new_id("brv_msg_")
            now = _now()
            row = {
                "id": mid,
                "workspace_id": workspace_id,
                "object_type": "conversation_message",
                "status": "received",
                "name": None,
                "channel": "chat",
                "subject": None,
                "from_email": None,
                "from_name": None,
                "to_contact_id": to_contact_id if to_contact_id else th.get("to_contact_id"),
                "to_address": None,
                "template_id": None,
                "payload": payload,
                "scheduled_for": None,
                "send_provider_message_id": None,
                "tracking": {},
                "event_type": "inbound_received",
                "event_at": now,
                "webhook_url": None,
                "webhook_secret": None,
                "enabled_events": None,
                "retry_policy": None,
                "conversation_thread_id": thread_id,
                "inbound_message_id": inbound_message_id,
                "attachments": attachments,
                "crm_link": crm_link if isinstance(crm_link, dict) else {},
                "ecommerce_link": ecommerce_link if isinstance(ecommerce_link, dict) else {},
                "created_by_principal_id": created_by_principal_id,
                "created_at": now,
                "updated_at": now,
            }
            # Immediately process (received -> processed) as ingestion confirmation
            ok, terr = _transition(row, "processed")
            if not ok:
                _log(409, terr["error"])
                return terr

            msgs.append(row)
