            _save("messaging_objects.json", msgs)
            _log(201)
            return {"message": row, "thread": th}

        _log(400, {"code":"VALIDATION_ERROR","message":"Unsupported action"})
        return _err("VALIDATION_ERROR", "Unsupported action", action=action)
    except Exception as e:
        _log(500, {"code": "INTERNAL", "message": str(e)})
