    def _validate_regex(val, pat):
        return isinstance(val, str) and re.match(pat, val) is not None

    def _decode_cursor(cur):
        if not cur:
            return 0
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if s.startswith("off:"):
                return max(0, int(s.split(":", 1)[1]))
        except Exception:
            return None
        return None

    def _encode_cursor(off):
        return base64.urlsafe_b64encode(f"off:{off}".encode("utf-8")).decode("utf-8").rstrip("=")

    def _new_id(prefix):
        return prefix + base64.b32encode(os.urandom(12)).decode("ascii").rstrip("=")

    def _encrypt_secret(secret, wsid):
        # Store "encrypted" at rest: deterministic reversible is not required here; use one-way envelope.
        # Keep ciphertext format explicit; include per-workspace salt.
        salt = ("ws:" + wsid).encode("utf-8")
        digest = hashlib.sha256(salt + secret.encode("utf-8")).hexdigest()
        return "enc_sha256:" + digest

    try:
        if action not in {"list", "get", "create", "update", "delete"}:
            _log(400, {"code":"VALIDATION_ERROR","message":"Invalid action"})
            return _err("VALIDATION_ERROR", "Invalid action", field="action")
        if not _validate_regex(workspace_id, r"^brv_wsp_[0-9A-Z]{18,}$"):
            _log(400, {"code":"VALIDATION_ERROR","message":"Invalid workspace_id"})
            return _err("VALIDATION_ERROR", "Invalid workspace_id", field="workspace_id")
        if limit is None:
            limit = 100
        if not isinstance(limit, int) or limit < 1 or limit > 500:
            _log(400, {"code":"VALIDATION_ERROR","message":"Invalid limit"})
            return _err("VALIDATION_ERROR", "Invalid limit", field="limit", minimum=1, maximum=500)
        if sort_by is None:
            sort_by = "updated_at"
        if sort_by not in {"created_at", "updated_at", "name"}:
            _log(400, {"code":"VALIDATION_ERROR","message":"Invalid sort_by"})
            return _err("VALIDATION_ERROR", "Invalid sort_by", field="sort_by")
        if sort_order is None:
            sort_order = "desc"
        if sort_order not in {"asc", "desc"}:
            _log(400, {"code":"VALIDATION_ERROR","message":"Invalid sort_order"})
            return _err("VALIDATION_ERROR", "Invalid sort_order", field="sort_order")
        if status is not None and status not in {"draft","active","scheduled","sending","sent","delivered","opened","clicked","bounced","failed","paused","disabled","received","processed","archived","deleted"}:
            _log(400, {"code":"VALIDATION_ERROR","message":"Invalid status"})
            return _err("VALIDATION_ERROR", "Invalid status", field="status")

        wss = _load("workspaces.json")
        ws = next((w for w in wss if w.get("id") == workspace_id), None)
        if ws is None:
            _log(404, {"code":"NOT_FOUND","message":"Workspace not found"})
            return _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)
        if action in {"create", "update", "delete"} and ws.get("status") != "active":
            _log(409, {"code":"CONFLICT","message":"Workspace is not active"})
            return _err("CONFLICT", "Workspace is not active", status=ws.get("status"))

        msgs = _load("messaging_objects.json")

        def _find(wid):
            return next((m for m in msgs if m.get("workspace_id") == workspace_id and m.get("id") == wid and m.get("object_type") == "webhook_subscription"), None)

        if action == "list":
            rows = [m for m in msgs if m.get("workspace_id") == workspace_id and m.get("object_type") == "webhook_subscription"]
            if status is not None:
                rows = [r for r in rows if r.get("status") == status]
            rev = (sort_order == "desc")
            rows.sort(key=lambda r: (r.get(sort_by) or ""), reverse=rev)
            off = _decode_cursor(cursor)
            if off is None:
                _log(400, {"code":"VALIDATION_ERROR","message":"Invalid cursor"})
                return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
            total = len(rows)
            page = rows[off:off + limit]
            next_off = off + len(page)
            has_more = next_off < total
            _log(200)
            return {"webhooks": page, "total": total, "has_more": has_more, "next_cursor": _encode_cursor(next_off) if has_more else None}

        if action == "get":
            if not webhook_id or not _validate_regex(webhook_id, r"^brv_msg_[0-9A-Z]{18,}$"):
                _log(400, {"code":"VALIDATION_ERROR","message":"Invalid webhook_id"})
                return _err("VALIDATION_ERROR", "Invalid webhook_id", field="webhook_id")
            wh = _find(webhook_id)
            if wh is None:
                _log(404, {"code":"NOT_FOUND","message":"Webhook not found"})
                return _err("NOT_FOUND", "Webhook not found", webhook_id=webhook_id)
            _log(200)
            return {"webhook": wh}

        if action == "create":
            if not webhook_url or not isinstance(webhook_url, str):
                _log(400, {"code":"VALIDATION_ERROR","message":"webhook_url is required"})
                return _err("VALIDATION_ERROR", "webhook_url is required", field="webhook_url")
            if enabled_events is None or not isinstance(enabled_events, list) or len(enabled_events) == 0:
                _log(400, {"code":"VALIDATION_ERROR","message":"enabled_events is required"})
                return _err("VALIDATION_ERROR", "enabled_events is required", field="enabled_events")
            if len(enabled_events) > 50:
                _log(400, {"code":"VALIDATION_ERROR","message":"enabled_events too long"})
                return _err("VALIDATION_ERROR", "enabled_events length <= 50", field="enabled_events", maximum=50)
            allowed_events = {"delivered","opened","clicked","bounced","spam","unsubscribed","reply","complaint","custom","inbound_received"}
            for ev in enabled_events:
                if ev not in allowed_events:
                    _log(400, {"code":"VALIDATION_ERROR","message":"Invalid enabled_events item"})
                    return _err("VALIDATION_ERROR", "Invalid enabled_events item", field="enabled_events", value=ev)

            now = _now()
            wid = _new_id("brv_msg_")
            row = {
                "id": wid,
                "workspace_id": workspace_id,
                "object_type": "webhook_subscription",
                "status": "active" if status is None else status,
                "name": name,
                "channel": "webhook",
                "subject": None,
                "from_email": None,
                "from_name": None,
                "to_contact_id": None,
                "to_address": None,
                "template_id": None,
                "payload": {},
                "scheduled_for": None,
                "send_provider_message_id": None,
                "tracking": {},
                "event_type": None,
                "event_at": None,
                "webhook_url": webhook_url,
                "webhook_secret": _encrypt_secret(webhook_secret, workspace_id) if isinstance(webhook_secret, str) and webhook_secret else None,
                "enabled_events": enabled_events,
                "retry_policy": retry_policy if isinstance(retry_policy, dict) else None,
                "conversation_thread_id": None,
                "inbound_message_id": None,
                "attachments": [],
                "crm_link": {},
                "ecommerce_link": {},
                "created_by_principal_id": None,
                "created_at": now,
                "updated_at": now,
            }
            msgs.append(row)
            _save("messaging_objects.json", msgs)
            _log(201)
            return {"webhook": row}

        if action == "update":
            if not webhook_id or not _validate_regex(webhook_id, r"^brv_msg_[0-9A-Z]{18,}$"):
                _log(400, {"code":"VALIDATION_ERROR","message":"Invalid webhook_id"})
                return _err("VALIDATION_ERROR", "Invalid webhook_id", field="webhook_id")
            wh = _find(webhook_id)
            if wh is None:
                _log(404, {"code":"NOT_FOUND","message":"Webhook not found"})
                return _err("NOT_FOUND", "Webhook not found", webhook_id=webhook_id)

            # Apply updates
            if name is not None:
                if not isinstance(name, str):
                    _log(400, {"code":"VALIDATION_ERROR","message":"Invalid name"})
                    return _err("VALIDATION_ERROR", "Invalid name", field="name")
                wh["name"] = name
            if webhook_url is not None:
                if not isinstance(webhook_url, str) or not webhook_url:
                    _log(400, {"code":"VALIDATION_ERROR","message":"Invalid webhook_url"})
                    return _err("VALIDATION_ERROR", "Invalid webhook_url", field="webhook_url")
                wh["webhook_url"] = webhook_url
            if enabled_events is not None:
                if not isinstance(enabled_events, list) or len(enabled_events) == 0:
                    _log(400, {"code":"VALIDATION_ERROR","message":"enabled_events must be a non-empty array"})
                    return _err("VALIDATION_ERROR", "enabled_events must be a non-empty array", field="enabled_events")
                if len(enabled_events) > 50:
                    _log(400, {"code":"VALIDATION_ERROR","message":"enabled_events too long"})
                    return _err("VALIDATION_ERROR", "enabled_events length <= 50", field="enabled_events", maximum=50)
                allowed_events = {"delivered","opened","clicked","bounced","spam","unsubscribed","reply","complaint","custom","inbound_received"}
                for ev in enabled_events:
                    if ev not in allowed_events:
                        _log(400, {"code":"VALIDATION_ERROR","message":"Invalid enabled_events item"})
                        return _err("VALIDATION_ERROR", "Invalid enabled_events item", field="enabled_events", value=ev)
                wh["enabled_events"] = enabled_events
            if retry_policy is not None:
                if not isinstance(retry_policy, dict):
                    _log(400, {"code":"VALIDATION_ERROR","message":"retry_policy must be object"})
                    return _err("VALIDATION_ERROR", "retry_policy must be object", field="retry_policy")
                wh["retry_policy"] = retry_policy
            if webhook_secret is not None:
                if not isinstance(webhook_secret, str) or not webhook_secret:
                    _log(400, {"code":"VALIDATION_ERROR","message":"Invalid webhook_secret"})
                    return _err("VALIDATION_ERROR", "Invalid webhook_secret", field="webhook_secret")
                wh["webhook_secret"] = _encrypt_secret(webhook_secret, workspace_id)

            # status update with business rule: disabling sets status='disabled'
            if status is not None:
                # minimal lifecycle enforcement for relevant transitions
                transitions = {
                    "draft": ["active", "scheduled", "deleted"],
                    "active": ["scheduled", "paused", "disabled", "deleted"],
                    "scheduled": ["sending", "paused", "disabled", "deleted"],
                    "sending": ["sent", "failed"],
                    "sent": ["archived"],
                    "paused": ["active", "disabled", "deleted"],
                    "disabled": ["active", "deleted"],
                    "archived": [],
                    "deleted": [],
                    "received": ["processed", "failed"],
                    "processed": ["archived"],
                    "delivered": ["opened", "clicked", "archived"],
                    "opened": ["clicked", "archived"],
                    "clicked": ["archived"],
                    "bounced": ["archived"],
                    "failed": ["archived"],
                }
                cur = wh.get("status")
                if cur != status:
                    if status not in transitions.get(cur, []):
                        _log(409, {"code":"INVALID_TRANSITION","message":"Illegal status transition"})
                        return _err("INVALID_TRANSITION", "Illegal status transition", from_status=cur, to_status=status)
                    wh["status"] = status

            # Must still satisfy required fields
            if not wh.get("webhook_url"):
                _log(400, {"code":"VALIDATION_ERROR","message":"webhook_url must be non-null for webhook_subscription"})
                return _err("VALIDATION_ERROR", "webhook_url must be non-null for webhook_subscription", field="webhook_url")
            if not wh.get("enabled_events") or not isinstance(wh.get("enabled_events"), list):
                _log(400, {"code":"VALIDATION_ERROR","message":"enabled_events must be non-null for webhook_subscription"})
                return _err("VALIDATION_ERROR", "enabled_events must be non-null for webhook_subscription", field="enabled_events")

            wh["updated_at"] = _now()
            _save("messaging_objects.json", msgs)
            _log(200)
            return {"webhook": wh}

        if action == "delete":
            if not webhook_id or not _validate_regex(webhook_id, r"^brv_msg_[0-9A-Z]{18,}$"):
                _log(400, {"code":"VALIDATION_ERROR","message":"Invalid webhook_id"})
                return _err("VALIDATION_ERROR", "Invalid webhook_id", field="webhook_id")
            wh = _find(webhook_id)
            if wh is None:
                _log(404, {"code":"NOT_FOUND","message":"Webhook not found"})
                return _err("NOT_FOUND", "Webhook not found", webhook_id=webhook_id)
            # transition to deleted if allowed, else if already deleted idempotent
            if wh.get("status") == "deleted":
                _log(200)
                return {"webhook": wh, "idempotent": True}
            transitions = {
                "draft": ["active", "scheduled", "deleted"],
                "active": ["scheduled", "paused", "disabled", "deleted"],
                "scheduled": ["sending", "paused", "disabled", "deleted"],
                "paused": ["active", "disabled", "deleted"],
                "disabled": ["active", "deleted"],
                "sending": ["sent", "failed"],
                "sent": ["archived"],
                "archived": [],
                "deleted": [],
                "received": ["processed", "failed"],
                "processed": ["archived"],
                "delivered": ["opened", "clicked", "archived"],
                "opened": ["clicked", "archived"],
                "clicked": ["archived"],
                "bounced": ["archived"],
                "failed": ["archived"],
            }
            cur = wh.get("status")
            if "deleted" not in transitions.get(cur, []):
                _log(409, {"code":"INVALID_TRANSITION","message":"Cannot delete from current status"})
                return _err("INVALID_TRANSITION", "Cannot delete from current status", from_status=cur, to_status="deleted")
            wh["status"] = "deleted"
            wh["updated_at"] = _now()
            _save("messaging_objects.json", msgs)
            _log(200)
            return {"webhook": wh}

        _log(400, {"code":"VALIDATION_ERROR","message":"Unsupported action"})
        return _err("VALIDATION_ERROR", "Unsupported action", action=action)
    except Exception as e:
        _log(500, {"code":"INTERNAL","message": str(e)})
        return _err("CONFLICT", "Unexpected server error")

def account(action, workspace_id, principal_id=None, brevo_account_id=None, name=None, status=None, default_sender_email=None, default_sender_name=None, verified_domains=None, folders=None, quota_daily_emails=None, quota_daily_sms=None, quota_daily_whatsapp=None, quota_daily_events=None, usage_today=None, brevo_api_key_fingerprint=None, timezone=None, type=None, email=None, display_name=None, role=None, principal_status=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
