        principals = _load("principals.json")

        def _principal(pid):
            return next((p for p in principals if p.get("id") == pid and p.get("workspace_id") == workspace_id), None)

        def _require_active_workspace_for_changes():
            if ws.get("status") != "active":
                return _err("CONFLICT", "Workspace must be active for this operation", status=ws.get("status"))
            return None

        def _enforce_workspace_transition(cur, nxt):
            transitions = {"active":["suspended","closed"], "suspended":["active","closed"], "closed":[]}
            if cur == nxt:
                return None
            if nxt not in transitions.get(cur, []):
                return _err("INVALID_TRANSITION", "Illegal workspace status transition", from_status=cur, to_status=nxt)
