                    _log(400, {"code":"VALIDATION_ERROR","message":"Invalid brevo_account_id"})
                    return _err("VALIDATION_ERROR", "Invalid brevo_account_id", field="brevo_account_id")
                ws["brevo_account_id"] = brevo_account_id
            if default_sender_email is not None:
                if not isinstance(default_sender_email, str):
                    _log(400, {"code":"VALIDATION_ERROR","message":"Invalid default_sender_email"})
                    return _err("VALIDATION_ERROR", "Invalid default_sender_email", field="default_sender_email")
                ws["default_sender_email"] = default_sender_email
            if default_sender_name is not None:
                if not isinstance(default_sender_name, str):
                    _log(400, {"code":"VALIDATION_ERROR","message":"Invalid default_sender_name"})
                    return _err("VALIDATION_ERROR", "Invalid default_sender_name", field="default_sender_name")
                ws["default_sender_name"] = default_sender_name
            if verified_domains is not None:
                if not isinstance(verified_domains, list) or not all(isinstance(x, str) for x in verified_domains):
                    _log(400, {"code":"VALIDATION_ERROR","message":"Invalid verified_domains"})
                    return _err("VALIDATION_ERROR", "Invalid verified_domains", field="verified_domains")
                ws["verified_domains"] = verified_domains
            if folders is not None:
                if not isinstance(folders, list) or not all(isinstance(x, dict) for x in folders):
                    _log(400, {"code":"VALIDATION_ERROR","message":"Invalid folders"})
                    return _err("VALIDATION_ERROR", "Invalid folders", field="folders")
                ws["folders"] = folders
            if timezone is not None:
                if not isinstance(timezone, str):
                    _log(400, {"code":"VALIDATION_ERROR","message":"Invalid timezone"})
                    return _err("VALIDATION_ERROR", "Invalid timezone", field="timezone")
                ws["timezone"] = timezone
            if brevo_api_key_fingerprint is not None:
                if not isinstance(brevo_api_key_fingerprint, str):
                    _log(400, {"code":"VALIDATION_ERROR","message":"Invalid brevo_api_key_fingerprint"})
                    return _err("VALIDATION_ERROR", "Invalid brevo_api_key_fingerprint", field="brevo_api_key_fingerprint")
                ws["brevo_api_key_fingerprint"] = brevo_api_key_fingerprint

            if quota_daily_emails is not None: ws["quota_daily_emails"] = quota_daily_emails
            if quota_daily_sms is not None: ws["quota_daily_sms"] = quota_daily_sms
            if quota_daily_whatsapp is not None: ws["quota_daily_whatsapp"] = quota_daily_whatsapp
            if quota_daily_events is not None: ws["quota_daily_events"] = quota_daily_events

            ws["updated_at"] = _now()
            _save("workspaces.json", wss)
            _log(200)
            return {"workspace": ws}

        if action == "list_principals":
            rows = [p for p in principals if p.get("workspace_id") == workspace_id]
            if principal_status is not None:
                if principal_status not in {"active","invited","disabled"}:
                    _log(400, {"code":"VALIDATION_ERROR","message":"Invalid principal_status"})
                    return _err("VALIDATION_ERROR", "Invalid principal_status", field="principal_status")
                rows = [r for r in rows if r.get("status") == principal_status]
            rev = (sort_order == "desc")
            rows.sort(key=lambda r: (r.get(sort_by) or ""), reverse=rev)
            off = _decode_cursor(cursor)
            if off is None:
                _log(400, {"code":"VALIDATION_ERROR","message":"Invalid cursor"})
                return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
            total = len(rows)
            page = rows[off:off + limit]
            next_off = off + len(page)
            has_more = next_off < total
            _log(200)
            return {"principals": page, "total": total, "has_more": has_more, "next_cursor": _encode_cursor(next_off) if has_more else None}

        if action == "get_principal":
            if not principal_id or not _validate_regex(principal_id, r"^brv_prn_[0-9A-Z]{18,}$"):
                _log(400, {"code":"VALIDATION_ERROR","message":"Invalid principal_id"})
                return _err("VALIDATION_ERROR", "Invalid principal_id", field="principal_id")
            pr = _principal(principal_id)
            if pr is None:
                _log(404, {"code":"NOT_FOUND","message":"Principal not found"})
                return _err("NOT_FOUND", "Principal not found", principal_id=principal_id)
            _log(200)
            return {"principal": pr}

        if action == "create_principal":
            e = _require_active_workspace_for_changes()
            if e:
                _log(409, e["error"])
                return e
            if type not in {"user","service"}:
                _log(400, {"code":"VALIDATION_ERROR","message":"Invalid type"})
                return _err("VALIDATION_ERROR", "Invalid type", field="type")
            if not display_name or not isinstance(display_name, str):
                _log(400, {"code":"VALIDATION_ERROR","message":"display_name is required"})
                return _err("VALIDATION_ERROR", "display_name is required", field="display_name")
            if role is None:
                role = "read_only"
            if role not in {"owner","admin","editor","analyst","support","read_only"}:
                _log(400, {"code":"VALIDATION_ERROR","message":"Invalid role"})
                return _err("VALIDATION_ERROR", "Invalid role", field="role")
            if type == "user":
                if not email or not isinstance(email, str):
                    _log(400, {"code":"VALIDATION_ERROR","message":"email is required for user principals"})
                    return _err("VALIDATION_ERROR", "email is required for user principals", field="email")
                # unique(workspace_id,email)
                if any(p.get("workspace_id") == workspace_id and (p.get("email") or "").lower() == email.lower() for p in principals):
                    _log(409, {"code":"CONFLICT","message":"Principal email must be unique in workspace"})
                    return _err("CONFLICT", "Principal email must be unique in workspace", field="email")
            else:
                if email is not None:
                    _log(400, {"code":"VALIDATION_ERROR","message":"email must be null for service principals"})
                    return _err("VALIDATION_ERROR", "email must be null for service principals", field="email")

            now = _now()
            pid = _new_id("brv_prn_")
            row = {
                "id": pid,
                "workspace_id": workspace_id,
                "type": type,
                "email": email if type == "user" else None,
                "display_name": display_name,
                "role": role,
                "status": principal_status if principal_status else ("invited" if type == "user" else "active"),
                "last_login_at": None,
                "created_at": now,
                "updated_at": now,
            }
            if row["status"] not in {"active","invited","disabled"}:
                _log(400, {"code":"VALIDATION_ERROR","message":"Invalid principal_status"})
                return _err("VALIDATION_ERROR", "Invalid principal_status", field="principal_status")
            principals.append(row)
            _save("principals.json", principals)
            _log(201)
            return {"principal": row}

        if action == "update_principal":
            e = _require_active_workspace_for_changes()
            if e:
                _log(409, e["error"])
                return e
            if not principal_id or not _validate_regex(principal_id, r"^brv_prn_[0-9A-Z]{18,}$"):
                _log(400, {"code":"VALIDATION_ERROR","message":"Invalid principal_id"})
                return _err("VALIDATION_ERROR", "Invalid principal_id", field="principal_id")
            pr = _principal(principal_id)
            if pr is None:
                _log(404, {"code":"NOT_FOUND","message":"Principal not found"})
                return _err("NOT_FOUND", "Principal not found", principal_id=principal_id)

            if display_name is not None:
                if not isinstance(display_name, str) or not display_name:
                    _log(400, {"code":"VALIDATION_ERROR","message":"Invalid display_name"})
                    return _err("VALIDATION_ERROR", "Invalid display_name", field="display_name")
                pr["display_name"] = display_name
            if role is not None:
                if role not in {"owner","admin","editor","analyst","support","read_only"}:
                    _log(400, {"code":"VALIDATION_ERROR","message":"Invalid role"})
                    return _err("VALIDATION_ERROR", "Invalid role", field="role")
                pr["role"] = role
            if principal_status is not None:
                if principal_status not in {"active","invited","disabled"}:
                    _log(400, {"code":"VALIDATION_ERROR","message":"Invalid principal_status"})
                    return _err("VALIDATION_ERROR", "Invalid principal_status", field="principal_status")
                terr = _enforce_principal_transition(pr.get("status"), principal_status)
                if terr:
                    _log(409, terr["error"])
                    return terr
                pr["status"] = principal_status
            if email is not None:
                # allow updating email for user only
                if pr.get("type") != "user":
                    _log(400, {"code":"VALIDATION_ERROR","message":"Only user principals can have email"})
                    return _err("VALIDATION_ERROR", "Only user principals can have email", field="email")
                if not isinstance(email, str) or not email:
                    _log(400, {"code":"VALIDATION_ERROR","message":"Invalid email"})
                    return _err("VALIDATION_ERROR", "Invalid email", field="email")
                if any(p.get("id") != principal_id and p.get("workspace_id") == workspace_id and (p.get("email") or "").lower() == email.lower() for p in principals):
                    _log(409, {"code":"CONFLICT","message":"Principal email must be unique in workspace"})
                    return _err("CONFLICT", "Principal email must be unique in workspace", field="email")
                pr["email"] = email

            pr["updated_at"] = _now()
            _save("principals.json", principals)
            _log(200)
            return {"principal": pr}

        if action == "disable_principal":
            e = _require_active_workspace_for_changes()
            if e:
                _log(409, e["error"])
                return e
            if not principal_id or not _validate_regex(principal_id, r"^brv_prn_[0-9A-Z]{18,}$"):
                _log(400, {"code":"VALIDATION_ERROR","message":"Invalid principal_id"})
                return _err("VALIDATION_ERROR", "Invalid principal_id", field="principal_id")
            pr = _principal(principal_id)
            if pr is None:
                _log(404, {"code":"NOT_FOUND","message":"Principal not found"})
                return _err("NOT_FOUND", "Principal not found", principal_id=principal_id)
            if pr.get("status") == "disabled":
                _log(200)
                return {"principal": pr, "idempotent": True}
            terr = _enforce_principal_transition(pr.get("status"), "disabled")
            if terr:
                _log(409, terr["error"])
                return terr
            pr["status"] = "disabled"
            pr["updated_at"] = _now()
            _save("principals.json", principals)
            _log(200)
            return {"principal": pr}

        _log(400, {"code":"VALIDATION_ERROR","message":"Unsupported action"})
        return _err("VALIDATION_ERROR", "Unsupported action", action=action)
    except Exception as e:
        _log(500, {"code":"INTERNAL","message": str(e)})
        return _err("CONFLICT", "Unexpected server error")

def ecommerce(action, workspace_id, object_id=None, object_type=None, status=None, name=None, description=None, amount=None, currency=None, properties=None, contact_id=None, external_id=None, parent_object_id=None, created_by_principal_id=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0080000" if __import__("os").path.isdir("./environment_mix/0080000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "ecommerce"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, error=None, extra=None):
        try:
            wss = _load("workspaces.json")
            ws = next((w for w in wss if w.get("id") == workspace_id), None)
            if ws is not None:
                ut = ws.get("usage_today") if isinstance(ws.get("usage_today"), dict) else {}
                ut["api_calls"] = int(ut.get("api_calls", 0) or 0) + 1
                ws["usage_today"] = ut
                ws["updated_at"] = _now()
                _save("workspaces.json", wss)
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            row = {
                "id": "brv_req_" + base64.b32encode(os.urandom(12)).decode("ascii").rstrip("="),
                "timestamp": _now(),
                "endpoint": endpoint,
                "action": action,
                "workspace_id": workspace_id,
                "status": status_code,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            if error is not None:
                row["error"] = error
            if isinstance(extra, dict):
                row.update(extra)
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _validate_regex(val, pat):
        return isinstance(val, str) and re.match(pat, val) is not None

    def _decode_cursor(cur):
        if not cur:
            return 0
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if s.startswith("off:"):
                return max(0, int(s.split(":", 1)[1]))
        except Exception:
            return None
        return None

    def _encode_cursor(off):
        return base64.urlsafe_b64encode(f"off:{off}".encode("utf-8")).decode("utf-8").rstrip("=")

    def _new_id(prefix):
        return prefix + base64.b32encode(os.urandom(12)).decode("ascii").rstrip("=")

    try:
        if action not in {"list","get","upsert","delete"}:
            _log(400, {"code":"VALIDATION_ERROR","message":"Invalid action"})
            return _err("VALIDATION_ERROR", "Invalid action", field="action")
        if not _validate_regex(workspace_id, r"^brv_wsp_[0-9A-Z]{18,}$"):
            _log(400, {"code":"VALIDATION_ERROR","message":"Invalid workspace_id"})
            return _err("VALIDATION_ERROR", "Invalid workspace_id", field="workspace_id")
        allowed_types = {"crm_company","crm_deal","crm_task","crm_note","ecom_product","ecom_order","ecom_coupon","ecom_payment"}
        if object_type not in allowed_types:
            _log(400, {"code":"VALIDATION_ERROR","message":"Invalid object_type"})
            return _err("VALIDATION_ERROR", "Invalid object_type", field="object_type")

        if limit is None:
            limit = 100
        if not isinstance(limit, int) or limit < 1 or limit > 500:
            _log(400, {"code":"VALIDATION_ERROR","message":"Invalid limit"})
            return _err("VALIDATION_ERROR", "Invalid limit", field="limit", minimum=1, maximum=500)
        if sort_by is None:
            sort_by = "updated_at"
        if sort_by not in {"created_at","updated_at","name","amount"}:
            _log(400, {"code":"VALIDATION_ERROR","message":"Invalid sort_by"})
            return _err("VALIDATION_ERROR", "Invalid sort_by", field="sort_by")
        if sort_order is None:
            sort_order = "desc"
        if sort_order not in {"asc","desc"}:
            _log(400, {"code":"VALIDATION_ERROR","message":"Invalid sort_order"})
            return _err("VALIDATION_ERROR", "Invalid sort_order", field="sort_order")

        wss = _load("workspaces.json")
        ws = next((w for w in wss if w.get("id") == workspace_id), None)
        if ws is None:
            _log(404, {"code":"NOT_FOUND","message":"Workspace not found"})
            return _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)

        principals = _load("principals.json")
        contacts = _load("contacts.json")
        objs = _load("business_objects.json")

        def _principal_active_ok(pid):
            if pid is None:
                return True, None
            pr = next((p for p in principals if p.get("id") == pid and p.get("workspace_id") == workspace_id), None)
            if pr is None:
                return False, _err("NOT_FOUND", "Principal not found", principal_id=pid)
            if pr.get("status") != "active":
                return False, _err("UNAUTHORIZED", "Principal is not active", principal_id=pid, status=pr.get("status"))
            if pr.get("role") == "read_only":
                return False, _err("UNAUTHORIZED", "Principal role cannot perform mutations", role=pr.get("role"))
            return True, pr

        def _find(oid):
            return next((o for o in objs if o.get("id") == oid and o.get("workspace_id") == workspace_id and o.get("object_type") == object_type), None)

        def _currency_ok(cur):
            return isinstance(cur, str) and re.match(r"^[A-Z]{3}$", cur) is not None

        def _creates_cycle(child_id, new_parent_id):
            # detect cycles by walking parent chain starting at new_parent_id
            if not new_parent_id:
                return False
            seen = set([child_id])
            cur = new_parent_id
            while cur:
                if cur in seen:
                    return True
                seen.add(cur)
                pobj = next((o for o in objs if o.get("id") == cur and o.get("workspace_id") == workspace_id), None)
                if pobj is None:
                    return False
                cur = pobj.get("parent_object_id")
            return False

        if action == "list":
            rows = [o for o in objs if o.get("workspace_id") == workspace_id and o.get("object_type") == object_type]
            if status is not None:
                allowed_status = {"active","inactive","open","won","lost","pending","paid","refunded","cancelled","archived","deleted"}
                if status not in allowed_status:
                    _log(400, {"code":"VALIDATION_ERROR","message":"Invalid status"})
                    return _err("VALIDATION_ERROR", "Invalid status", field="status")
                rows = [r for r in rows if r.get("status") == status]
            rev = (sort_order == "desc")
            rows.sort(key=lambda r: (r.get(sort_by) if r.get(sort_by) is not None else ""), reverse=rev)
            off = _decode_cursor(cursor)
            if off is None:
                _log(400, {"code":"VALIDATION_ERROR","message":"Invalid cursor"})
                return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
            total = len(rows)
            page = rows[off:off + limit]
            next_off = off + len(page)
            has_more = next_off < total
            _log(200)
            return {"objects": page, "total": total, "has_more": has_more, "next_cursor": _encode_cursor(next_off) if has_more else None}

        if action == "get":
            if not object_id or not _validate_regex(object_id, r"^brv_obj_[0-9A-Z]{18,}$"):
                _log(400, {"code":"VALIDATION_ERROR","message":"Invalid object_id"})
                return _err("VALIDATION_ERROR", "Invalid object_id", field="object_id")
            obj = _find(object_id)
            if obj is None:
                _log(404, {"code":"NOT_FOUND","message":"Object not found"})
                return _err("NOT_FOUND", "Object not found", object_id=object_id, object_type=object_type)
            _log(200)
            return {"object": obj}

        if action == "upsert":
            ok, perr = _principal_active_ok(created_by_principal_id)
            if not ok:
                _log(401 if perr["error"]["code"] == "UNAUTHORIZED" else 404, perr["error"])
                return perr

            if amount is not None:
                if not isinstance(amount, (int, float)) or amount < 0:
                    _log(400, {"code":"VALIDATION_ERROR","message":"Invalid amount"})
                    return _err("VALIDATION_ERROR", "amount must be >= 0", field="amount")
            if currency is not None and not _currency_ok(currency):
                _log(400, {"code":"VALIDATION_ERROR","message":"Invalid currency"})
                return _err("VALIDATION_ERROR", "currency must be 3 uppercase letters", field="currency")
            if properties is not None and not isinstance(properties, dict):
                _log(400, {"code":"VALIDATION_ERROR","message":"Invalid properties"})
                return _err("VALIDATION_ERROR", "properties must be an object", field="properties")
            if contact_id is not None:
                if not _validate_regex(contact_id, r"^brv_cnt_[0-9A-Z]{18,}$"):
                    _log(400, {"code":"VALIDATION_ERROR","message":"Invalid contact_id"})
                    return _err("VALIDATION_ERROR", "Invalid contact_id", field="contact_id")
                c = next((c for c in contacts if c.get("id") == contact_id and c.get("workspace_id") == workspace_id), None)
                if c is None:
                    _log(404, {"code":"NOT_FOUND","message":"Contact not found"})
                    return _err("NOT_FOUND", "Contact not found", contact_id=contact_id)

            if parent_object_id is not None:
                if not _validate_regex(parent_object_id, r"^brv_obj_[0-9A-Z]{18,}$"):
                    _log(400, {"code":"VALIDATION_ERROR","message":"Invalid parent_object_id"})
                    return _err("VALIDATION_ERROR", "Invalid parent_object_id", field="parent_object_id")
                pobj = next((o for o in objs if o.get("id") == parent_object_id and o.get("workspace_id") == workspace_id), None)
                if pobj is None:
                    _log(404, {"code":"NOT_FOUND","message":"Parent object not found"})
                    return _err("NOT_FOUND", "Parent object not found", parent_object_id=parent_object_id)

            # payments must have parent ecom_order
            if object_type == "ecom_payment":
                if not parent_object_id:
                    _log(400, {"code":"VALIDATION_ERROR","message":"ecom_payment requires parent_object_id"})
                    return _err("VALIDATION_ERROR", "ecom_payment requires parent_object_id referencing an ecom_order", field="parent_object_id")
                pobj = next((o for o in objs if o.get("id") == parent_object_id and o.get("workspace_id") == workspace_id), None)
                if pobj is None or pobj.get("object_type") != "ecom_order":
                    _log(409, {"code":"CONFLICT","message":"Payment parent must be an ecom_order"})
                    return _err("CONFLICT", "Payment parent must be an ecom_order", parent_object_id=parent_object_id)

            # resolve existing by object_id or by unique external_id if provided
            target = None
            if object_id is not None:
                if not _validate_regex(object_id, r"^brv_obj_[0-9A-Z]{18,}$"):
                    _log(400, {"code":"VALIDATION_ERROR","message":"Invalid object_id"})
                    return _err("VALIDATION_ERROR", "Invalid object_id", field="object_id")
                target = _find(object_id)
                if target is None:
                    # treat as create with specified id not allowed; must not claim success without effect
                    _log(404, {"code":"NOT_FOUND","message":"Object not found for upsert by object_id"})
                    return _err("NOT_FOUND", "Object not found", object_id=object_id, object_type=object_type)
            elif external_id is not None:
                if not isinstance(external_id, str) or not external_id:
                    _log(400, {"code":"VALIDATION_ERROR","message":"Invalid external_id"})
                    return _err("VALIDATION_ERROR", "Invalid external_id", field="external_id")
                target = next((o for o in objs if o.get("workspace_id") == workspace_id and o.get("object_type") == object_type and o.get("external_id") == external_id), None)

            # uniqueness constraint on (workspace_id, object_type, external_id) when external_id provided
            if external_id is not None:
                if target is None:
                    if any(o.get("workspace_id") == workspace_id and o.get("object_type") == object_type and o.get("external_id") == external_id for o in objs):
                        _log(409, {"code":"CONFLICT","message":"external_id must be unique"})
                        return _err("CONFLICT", "external_id must be unique for this object_type within workspace", external_id=external_id)

            now = _now()
            if target is None:
                oid = _new_id("brv_obj_")
                # default status if not set
                if status is None:
                    status = "active" if object_type in {"crm_company","ecom_product","ecom_coupon"} else ("open" if object_type in {"crm_deal","crm_task","crm_note"} else "pending")
                allowed_status = {"active","inactive","open","won","lost","pending","paid","refunded","cancelled","archived","deleted"}
                if status not in allowed_status:
                    _log(400, {"code":"VALIDATION_ERROR","message":"Invalid status"})
                    return _err("VALIDATION_ERROR", "Invalid status", field="status")

                if parent_object_id is not None and _creates_cycle(oid, parent_object_id):
                    _log(409, {"code":"CONFLICT","message":"parent_object_id cannot create cycles"})
                    return _err("CONFLICT", "parent_object_id cannot create cycles", parent_object_id=parent_object_id)

                row = {
                    "id": oid,
                    "workspace_id": workspace_id,
                    "object_type": object_type,
                    "status": status,
                    "name": name,
                    "description": description,
                    "amount": amount,
                    "currency": currency,
                    "properties": properties if isinstance(properties, dict) else {},
                    "contact_id": contact_id,
                    "external_id": external_id,
                    "parent_object_id": parent_object_id,
                    "created_by_principal_id": created_by_principal_id,
                    "created_at": now,
                    "updated_at": now,
                }
                objs.append(row)
                _save("business_objects.json", objs)
                _log(201)
                return {"object": row, "created": True}

            # update existing
            if external_id is not None and target.get("external_id") != external_id:
                if any(o.get("id") != target.get("id") and o.get("workspace_id") == workspace_id and o.get("object_type") == object_type and o.get("external_id") == external_id for o in objs):
                    _log(409, {"code":"CONFLICT","message":"external_id must be unique"})
                    return _err("CONFLICT", "external_id must be unique for this object_type within workspace", external_id=external_id)

            if parent_object_id is not None:
                if _creates_cycle(target.get("id"), parent_object_id):
                    _log(409, {"code":"CONFLICT","message":"parent_object_id cannot create cycles"})
                    return _err("CONFLICT", "parent_object_id cannot create cycles", parent_object_id=parent_object_id)
                target["parent_object_id"] = parent_object_id

            if status is not None:
                transitions = {
                    "active": ["inactive", "archived", "deleted"],
                    "inactive": ["active", "archived", "deleted"],
                    "open": ["won", "lost", "archived", "deleted"],
                    "pending": ["paid", "cancelled", "refunded", "archived", "deleted"],
                    "paid": ["refunded", "archived"],
                    "refunded": ["archived"],
                    "won": ["archived"],
                    "lost": ["archived"],
                    "cancelled": ["archived"],
                    "archived": [],
                    "deleted": [],
                }
                cur = target.get("status")
                if cur != status:
                    if status not in transitions.get(cur, []):
                        _log(409, {"code":"INVALID_TRANSITION","message":"Illegal status transition"})
                        return _err("INVALID_TRANSITION", "Illegal status transition", from_status=cur, to_status=status)
                    target["status"] = status

            if name is not None: target["name"] = name
            if description is not None: target["description"] = description
            if amount is not None: target["amount"] = amount
            if currency is not None: target["currency"] = currency
            if properties is not None: target["properties"] = properties
            if contact_id is not None: target["contact_id"] = contact_id
            if external_id is not None: target["external_id"] = external_id
            target["updated_at"] = now

            _save("business_objects.json", objs)
            _log(200)
            return {"object": target, "created": False}

        if action == "delete":
            ok, perr = _principal_active_ok(created_by_principal_id)
            if not ok:
                _log(401 if perr["error"]["code"] == "UNAUTHORIZED" else 404, perr["error"])
                return perr
            if not object_id or not _validate_regex(object_id, r"^brv_obj_[0-9A-Z]{18,}$"):
                _log(400, {"code":"VALIDATION_ERROR","message":"Invalid object_id"})
                return _err("VALIDATION_ERROR", "Invalid object_id", field="object_id")
            obj = _find(object_id)
            if obj is None:
                _log(404, {"code":"NOT_FOUND","message":"Object not found"})
                return _err("NOT_FOUND", "Object not found", object_id=object_id, object_type=object_type)
            if obj.get("status") == "deleted":
                _log(200)
                return {"object": obj, "idempotent": True}
            # lifecycle to deleted
            transitions = {
                "active": ["inactive", "archived", "deleted"],
                "inactive": ["active", "archived", "deleted"],
                "open": ["won", "lost", "archived", "deleted"],
                "pending": ["paid", "cancelled", "refunded", "archived", "deleted"],
                "paid": ["refunded", "archived"],
                "refunded": ["archived"],
                "won": ["archived"],
                "lost": ["archived"],
                "cancelled": ["archived"],
                "archived": [],
                "deleted": [],
            }
            cur = obj.get("status")
            if "deleted" not in transitions.get(cur, []):
                _log(409, {"code":"INVALID_TRANSITION","message":"Cannot delete from current status"})
                return _err("INVALID_TRANSITION", "Cannot delete from current status", from_status=cur, to_status="deleted")
            obj["status"] = "deleted"
            obj["updated_at"] = _now()
            _save("business_objects.json", objs)
            _log(200)
            return {"object": obj}

        _log(400, {"code":"VALIDATION_ERROR","message":"Unsupported action"})
        return _err("VALIDATION_ERROR", "Unsupported action", action=action)
    except Exception as e:
        _log(500, {"code":"INTERNAL","message": str(e)})
        return _err("CONFLICT", "Unexpected server error")

def crm(action, workspace_id, object_type, id=None, external_id=None, contact_id=None, parent_object_id=None, status=None, limit=None, cursor=None, sort=None, order=None, body=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0080000" if __import__("os").path.isdir("./environment_mix/0080000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "crm"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _match(pat, s):
        return isinstance(s, str) and re.match(pat, s or "") is not None

    def _b64u(i):
        return base64.urlsafe_b64encode(str(i).encode("utf-8")).decode("utf-8").rstrip("=")

    def _b64u_dec(s):
        try:
            pad = "=" * (-len(s) % 4)
            return int(base64.urlsafe_b64decode((s + pad).encode("utf-8")).decode("utf-8"))
        except Exception:
            return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        rnd = random.SystemRandom()
        return f"{prefix}_" + "".join(rnd.choice(alphabet) for _ in range(20))

    def _is_iso_currency(x):
        return isinstance(x, str) and re.fullmatch(r"[A-Z]{3}", x) is not None

    def _principal_can_mutate(principal_row):
        if not principal_row:
            return True
        if principal_row.get("status") != "active":
            return False
        if principal_row.get("role") == "read_only":
            return False
        return True

    def _resolve_principal(workspace_row):
        principals = _load("principals.json")
        cands = [p for p in principals if p.get("workspace_id") == workspace_row.get("id") and p.get("status") == "active"]
        if not cands:
            return None
        # Prefer owner/admin/editor; analyst/support ok for CRM mutation (no special restriction in rules)
        pref = ["owner", "admin", "editor", "analyst", "support", "read_only"]
        cands.sort(key=lambda p: pref.index(p.get("role")) if p.get("role") in pref else 999)
        return cands[0]

    def _log(status_code, credential_fp, latency_ms):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _gen_id("brv_req"),
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "credential_fingerprint": credential_fp,
            "status": status_code,
            "latency_ms": latency_ms,
            "created_at": _now()
        })
        _save("request_logs.json", logs)

    def _enforce_and_count_api_call(workspace_row):
        # Enforce a simple rate limit: 120 calls / rolling minute / workspace
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now_dt = datetime.datetime.utcnow()
        window_start = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if r.get("workspace_id") != workspace_row.get("id"):
                continue
            ts = r.get("created_at")
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= window_start:
                cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded")

        # daily api_calls counter
        usage = workspace_row.get("usage_today")
        if not isinstance(usage, dict):
            usage = {}
        usage["api_calls"] = int(usage.get("api_calls") or 0) + 1
        workspace_row["usage_today"] = usage
        return None

    # Basic validation
    actions = {"list", "get", "create", "update", "delete"}
    obj_types = {"crm_company", "crm_deal", "crm_task", "crm_note"}

    if action not in actions:
        return _err("VALIDATION_ERROR", "Invalid action", field="action")
    if not _match(r"^brv_wsp_[0-9A-Z]{18,}$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id", field="workspace_id")
    if object_type not in obj_types:
        return _err("VALIDATION_ERROR", "Invalid object_type", field="object_type")

    if id is not None and not _match(r"^brv_obj_[0-9A-Z]{18,}$", id):
        return _err("VALIDATION_ERROR", "Invalid id", field="id")
    if contact_id is not None and not _match(r"^brv_cnt_[0-9A-Z]{18,}$", contact_id):
        return _err("VALIDATION_ERROR", "Invalid contact_id", field="contact_id")
    if parent_object_id is not None and not _match(r"^brv_obj_[0-9A-Z]{18,}$", parent_object_id):
        return _err("VALIDATION_ERROR", "Invalid parent_object_id", field="parent_object_id")

    if status is not None:
        valid_status = {"active","inactive","open","won","lost","pending","paid","refunded","cancelled","archived","deleted"}
        if status not in valid_status:
            return _err("VALIDATION_ERROR", "Invalid status", field="status")
    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            return _err("VALIDATION_ERROR", "Invalid limit", field="limit")
    if sort is not None and sort not in {"created_at", "updated_at", "amount", "name", "status"}:
        return _err("VALIDATION_ERROR", "Invalid sort", field="sort")
    if order is not None and order not in {"asc", "desc"}:
        return _err("VALIDATION_ERROR", "Invalid order", field="order")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
    if body is not None and not isinstance(body, dict):
        return _err("VALIDATION_ERROR", "Invalid body", field="body")

    # Resolve workspace (ambient auth: any workable workspace counts as authorized)
    workspaces = _load("workspaces.json")
    wsp = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not wsp:
        return _err("NOT_FOUND", "Workspace not found", workspace_id=workspace_id)

    credential_fp = wsp.get("brevo_api_key_fingerprint") or None

    # rate limit + api call usage
    rl_err = _enforce_and_count_api_call(wsp)
    if rl_err:
        latency_ms = int((time.time() - t0) * 1000)
        _log("RATE_LIMIT", credential_fp, latency_ms)
        return rl_err

    # Persist api_calls increment
    wsp["updated_at"] = _now()
    _save("workspaces.json", workspaces)

    principal = _resolve_principal(wsp)
    if action in {"create", "update", "delete"} and not _principal_can_mutate(principal):
        latency_ms = int((time.time() - t0) * 1000)
        _log("UNAUTHORIZED", credential_fp, latency_ms)
        return _err("UNAUTHORIZED", "Principal not allowed to mutate CRM objects")

    business = _load("business_objects.json")
    contacts = _load("contacts.json")

    def _find_contact(cid):
        if cid is None:
            return None
        return next((c for c in contacts if c.get("id") == cid and c.get("workspace_id") == workspace_id), None)

    def _find_obj(oid):
        return next((o for o in business if o.get("id") == oid and o.get("workspace_id") == workspace_id and o.get("object_type") == object_type), None)

    def _find_by_external(xid):
        return next((o for o in business if o.get("workspace_id") == workspace_id and o.get("object_type") == object_type and o.get("external_id") == xid), None)

    def _creates_cycle(candidate_id, parent_id):
        if not parent_id:
            return False
        # Walk up parents
        seen = set([candidate_id])
        cur = parent_id
        while cur:
            if cur in seen:
                return True
            seen.add(cur)
            row = next((o for o in business if o.get("id") == cur and o.get("workspace_id") == workspace_id), None)
            if not row:
                return False
            cur = row.get("parent_object_id")
        return False

    valid_status = ["active","inactive","open","won","lost","pending","paid","refunded","cancelled","archived","deleted"]
    transitions = {
        "active": ["inactive", "archived", "deleted"],
        "inactive": ["active", "archived", "deleted"],
        "open": ["won", "lost", "archived", "deleted"],
        "pending": ["paid", "cancelled", "refunded", "archived", "deleted"],
        "paid": ["refunded", "archived"],
        "refunded": ["archived"],
        "won": ["archived"],
        "lost": ["archived"],
        "cancelled": ["archived"],
        "archived": [],
        "deleted": [],
    }

    def _apply_body(row, b, is_create=False):
        if not isinstance(b, dict):
            return _err("VALIDATION_ERROR", "body is required", field="body") if is_create else None

        allowed = {"name","description","amount","currency","properties","status","contact_id","external_id","parent_object_id"}
        for k in b.keys():
            if k not in allowed:
                return _err("VALIDATION_ERROR", "Unknown field in body", field=k)

        if "amount" in b and b["amount"] is not None:
            if not isinstance(b["amount"], (int, float)) or b["amount"] < 0:
                return _err("VALIDATION_ERROR", "amount must be a non-negative number", field="amount")
        if "currency" in b and b["currency"] is not None:
            if not _is_iso_currency(b["currency"]):
                return _err("VALIDATION_ERROR", "currency must be 3 uppercase letters", field="currency")
        if "properties" in b and b["properties"] is not None and not isinstance(b["properties"], dict):
            return _err("VALIDATION_ERROR", "properties must be an object", field="properties")
        if "status" in b and b["status"] is not None and b["status"] not in valid_status:
            return _err("VALIDATION_ERROR", "Invalid status", field="status")
        if "contact_id" in b and b["contact_id"] is not None:
            if not _match(r"^brv_cnt_[0-9A-Z]{18,}$", b["contact_id"]):
                return _err("VALIDATION_ERROR", "Invalid contact_id", field="contact_id")
            if not _find_contact(b["contact_id"]):
                return _err("NOT_FOUND", "Contact not found", contact_id=b["contact_id"])
        if "parent_object_id" in b and b["parent_object_id"] is not None:
            if not _match(r"^brv_obj_[0-9A-Z]{18,}$", b["parent_object_id"]):
                return _err("VALIDATION_ERROR", "Invalid parent_object_id", field="parent_object_id")
            parent = next((o for o in business if o.get("id") == b["parent_object_id"] and o.get("workspace_id") == workspace_id), None)
            if not parent:
                return _err("NOT_FOUND", "Parent object not found", parent_object_id=b["parent_object_id"])
            if _creates_cycle(row.get("id"), b["parent_object_id"]):
                return _err("CONFLICT", "parent_object_id cannot create cycles")

        # Apply with status transition enforcement
        if "status" in b and b["status"] is not None:
            old = row.get("status")
            new = b["status"]
            if old is None:
                row["status"] = new
            elif new != old:
                if old not in transitions or new not in transitions.get(old, []):
                    return _err("INVALID_TRANSITION", "Illegal status transition", from_status=old, to_status=new)
                row["status"] = new

        for k in ["name","description","amount","currency","properties","contact_id","external_id","parent_object_id"]:
            if k in b:
                if k == "properties" and b[k] is None:
                    row[k] = {}
                else:
                    row[k] = b[k]
        return None

    try:
        if action == "list":
            rows = [o for o in business if o.get("workspace_id") == workspace_id and o.get("object_type") == object_type]
            if external_id is not None:
                rows = [o for o in rows if o.get("external_id") == external_id]
            if contact_id is not None:
                rows = [o for o in rows if o.get("contact_id") == contact_id]
            if parent_object_id is not None:
                rows = [o for o in rows if o.get("parent_object_id") == parent_object_id]
            if status is not None:
                rows = [o for o in rows if o.get("status") == status]

            sfield = sort or "updated_at"
            rev = (order or "desc") == "desc"

            def _key(r):
                v = r.get(sfield)
                if sfield in {"created_at","updated_at"}:
                    try:
                        return datetime.datetime.fromisoformat(str(v).replace("Z","+00:00")).timestamp()
                    except Exception:
                        return 0
                if sfield == "amount":
                    return float(v) if isinstance(v, (int,float)) else -1.0
                return (v or "")
            rows.sort(key=_key, reverse=rev)

            start = 0
            if cursor:
                off = _b64u_dec(cursor)
                if off is None or off < 0:
                    latency_ms = int((time.time() - t0) * 1000)
                    _log("VALIDATION_ERROR", credential_fp, latency_ms)
                    return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
                start = off

            lim = limit or 50
            page = rows[start:start+lim]
            next_off = start + lim
            has_more = next_off < len(rows)
            out = {
                "object_type": object_type,
                "data": page,
                "meta": {
                    "total": len(rows),
                    "limit": lim,
                    "cursor": cursor,
                    "next_cursor": _b64u(next_off) if has_more else None,
                    "has_more": has_more,
                    "sort": sfield,
                    "order": order or "desc"
                }
            }
            latency_ms = int((time.time() - t0) * 1000)
            _log("OK", credential_fp, latency_ms)
            return out

        if action == "get":
            row = None
            if id:
                row = _find_obj(id)
            elif external_id:
                row = _find_by_external(external_id)
            else:
                latency_ms = int((time.time() - t0) * 1000)
                _log("VALIDATION_ERROR", credential_fp, latency_ms)
                return _err("VALIDATION_ERROR", "id or external_id is required for get")
            if not row:
                latency_ms = int((time.time() - t0) * 1000)
                _log("NOT_FOUND", credential_fp, latency_ms)
                return _err("NOT_FOUND", "CRM object not found")
            latency_ms = int((time.time() - t0) * 1000)
            _log("OK", credential_fp, latency_ms)
            return {"object_type": object_type, "data": row}

        if action == "create":
            # Upsert behavior when external_id provided: enforce unique(workspace_id, object_type, external_id)
            if body is None or not isinstance(body, dict):
                latency_ms = int((time.time() - t0) * 1000)
                _log("VALIDATION_ERROR", credential_fp, latency_ms)
                return _err("VALIDATION_ERROR", "body is required", field="body")

            xid = body.get("external_id", None)
            if xid is not None:
                existing = _find_by_external(xid)
                if existing:
                    # idempotent update existing with same external_id
                    err = _apply_body(existing, body, is_create=False)
                    if err:
                        latency_ms = int((time.time() - t0) * 1000)
                        _log(err["error"]["code"], credential_fp, latency_ms)
                        return err
                    existing["updated_at"] = _now()
                    if principal:
                        existing["created_by_principal_id"] = existing.get("created_by_principal_id") or principal.get("id")
                    _save("business_objects.json", business)
                    latency_ms = int((time.time() - t0) * 1000)
                    _log("OK", credential_fp, latency_ms)
                    return {"object_type": object_type, "data": existing, "meta": {"idempotent": True}}

            # create new
            new_id = _gen_id("brv_obj")
            row = {
                "id": new_id,
                "workspace_id": workspace_id,
                "object_type": object_type,
                "status": "active" if object_type in {"crm_company"} else "open" if object_type in {"crm_deal","crm_task"} else "active",
                "name": None,
                "description": None,
                "amount": None,
                "currency": None,
                "properties": {},
                "contact_id": None,
                "external_id": None,
                "parent_object_id": None,
                "created_by_principal_id": principal.get("id") if principal else None,
                "created_at": _now(),
                "updated_at": _now()
            }

            err = _apply_body(row, body, is_create=True)
            if err:
                latency_ms = int((time.time() - t0) * 1000)
                _log(err["error"]["code"], credential_fp, latency_ms)
                return err

            # uniqueness for external_id (if set in body)
            if row.get("external_id") is not None:
                if _find_by_external(row["external_id"]):
                    latency_ms = int((time.time() - t0) * 1000)
                    _log("CONFLICT", credential_fp, latency_ms)
                    return _err("CONFLICT", "external_id already exists for this object_type in workspace", external_id=row["external_id"])

            business.append(row)
            _save("business_objects.json", business)
            latency_ms = int((time.time() - t0) * 1000)
            _log("OK", credential_fp, latency_ms)
            return {"object_type": object_type, "data": row}

        if action == "update":
            row = None
            if id:
                row = _find_obj(id)
            elif external_id:
                row = _find_by_external(external_id)
            else:
                latency_ms = int((time.time() - t0) * 1000)
                _log("VALIDATION_ERROR", credential_fp, latency_ms)
                return _err("VALIDATION_ERROR", "id or external_id is required for update")

            if not row:
                latency_ms = int((time.time() - t0) * 1000)
                _log("NOT_FOUND", credential_fp, latency_ms)
                return _err("NOT_FOUND", "CRM object not found")

            if body is None or not isinstance(body, dict):
                latency_ms = int((time.time() - t0) * 1000)
                _log("VALIDATION_ERROR", credential_fp, latency_ms)
                return _err("VALIDATION_ERROR", "body is required", field="body")

            # If changing external_id, enforce uniqueness
            if "external_id" in body and body.get("external_id") is not None and body.get("external_id") != row.get("external_id"):
                if _find_by_external(body["external_id"]):
                    latency_ms = int((time.time() - t0) * 1000)
                    _log("CONFLICT", credential_fp, latency_ms)
                    return _err("CONFLICT", "external_id already exists for this object_type in workspace", external_id=body["external_id"])

            err = _apply_body(row, body, is_create=False)
            if err:
                latency_ms = int((time.time() - t0) * 1000)
                _log(err["error"]["code"], credential_fp, latency_ms)
                return err

            row["updated_at"] = _now()
            _save("business_objects.json", business)
            latency_ms = int((time.time() - t0) * 1000)
            _log("OK", credential_fp, latency_ms)
            return {"object_type": object_type, "data": row}

        if action == "delete":
            row = None
            if id:
                row = _find_obj(id)
            elif external_id:
                row = _find_by_external(external_id)
            else:
                latency_ms = int((time.time() - t0) * 1000)
                _log("VALIDATION_ERROR", credential_fp, latency_ms)
                return _err("VALIDATION_ERROR", "id or external_id is required for delete")

            if not row:
                latency_ms = int((time.time() - t0) * 1000)
                _log("NOT_FOUND", credential_fp, latency_ms)
                return _err("NOT_FOUND", "CRM object not found")

            old = row.get("status")
            if old != "deleted":
                if "deleted" not in transitions.get(old, []):
                    latency_ms = int((time.time() - t0) * 1000)
                    _log("INVALID_TRANSITION", credential_fp, latency_ms)
                    return _err("INVALID_TRANSITION", "Illegal status transition", from_status=old, to_status="deleted")
                row["status"] = "deleted"
                row["updated_at"] = _now()
                _save("business_objects.json", business)

            latency_ms = int((time.time() - t0) * 1000)
            _log("OK", credential_fp, latency_ms)
            return {"object_type": object_type, "data": row, "meta": {"deleted": True}}

    except Exception as e:
        latency_ms = int((time.time() - t0) * 1000)
        _log("VALIDATION_ERROR", credential_fp, latency_ms)
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

def whatsapp(action, workspace_id, id=None, limit=None, cursor=None, status=None, body=None, **_extra):
    import json, os, datetime, re, time, random, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0080000" if __import__("os").path.isdir("./environment_mix/0080000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "whatsapp"

    wsp_pat = re.compile(r"^brv_wsp_[0-9A-Z]{18,}$")
    msg_pat = re.compile(r"^brv_msg_[0-9A-Z]{18,}$")
    cnt_pat = re.compile(r"^brv_cnt_[0-9A-Z]{18,}$")

    allowed_actions = {"send", "create_template", "update_template", "list_templates", "create_campaign", "schedule_campaign", "pause_campaign", "get"}
    allowed_status = {"draft", "active", "scheduled", "sending", "sent", "delivered", "opened", "clicked", "bounced", "failed", "paused", "disabled", "received", "processed", "archived", "deleted"}

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0)

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        rnd = random.SystemRandom()
        return prefix + "".join(rnd.choice(alphabet) for _ in range(20))

    def _ensure_usage_today(ws):
        if not isinstance(ws.get("usage_today"), dict):
            ws["usage_today"] = {}
        ut = ws["usage_today"]
        for k in ("emails_sent", "sms_sent", "whatsapp_sent", "events_ingested", "api_calls"):
            if not isinstance(ut.get(k), int) or ut.get(k) is None or ut[k] < 0:
                ut[k] = 0

    def _load_rows(filename):
        d = _load(filename)
        if isinstance(d, dict) and isinstance(d.get("rows"), list):
            return d["rows"], d
        if isinstance(d, list):
            return d, None
        return [], None

    def _save_rows(filename, rows, wrapper):
        if wrapper is None:
            _save(filename, rows)
        else:
            wrapper["rows"] = rows
            _save(filename, wrapper)

    def _log_call(ws_row, principal_id, status_code, error=None, extra=None):
        logs, logs_wrapper = _load_rows("request_logs.json")
        _ensure_usage_today(ws_row)
        ws_row["usage_today"]["api_calls"] += 1
        entry = {
            "id": _gen_id("brv_req_"),
            "ts": _now_iso(),
            "endpoint": endpoint,
            "workspace_id": ws_row.get("id"),
            "principal_id": principal_id,
            "status": int(status_code),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if extra:
            entry["meta"] = extra
        if error:
            entry["error"] = error
        logs.append(entry)
        _save_rows("request_logs.json", logs, logs_wrapper)

    if not isinstance(action, str) or action not in allowed_actions:
        return _err("VALIDATION_ERROR", "Invalid action.", allowed=sorted(allowed_actions))
    if not isinstance(workspace_id, str) or not wsp_pat.match(workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id format.")
    if id is not None and (not isinstance(id, str) or not msg_pat.match(id)):
        return _err("VALIDATION_ERROR", "Invalid id format.")
    if limit is not None and (not isinstance(limit, int) or limit < 1 or limit > 200):
        return _err("VALIDATION_ERROR", "limit must be 1..200.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        return _err("VALIDATION_ERROR", "Invalid status.", allowed=sorted(allowed_status))
    if body is not None and not isinstance(body, dict):
        return _err("VALIDATION_ERROR", "body must be an object.")

    workspaces, workspaces_wrapper = _load_rows("workspaces.json")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.")
    _ensure_usage_today(ws)

    principals, principals_wrapper = _load_rows("principals.json")
    principal = next((p for p in principals if isinstance(p, dict) and p.get("workspace_id") == workspace_id and p.get("status") == "active"), None)
    if not principal:
        _log_call(ws, None, 401, error={"code": "UNAUTHORIZED", "message": "No active principal available for this workspace."})
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)
        return _err("UNAUTHORIZED", "No active principal available for this workspace.")
    role = principal.get("role")
    if action in {"send", "create_template", "update_template", "create_campaign", "schedule_campaign", "pause_campaign"}:
        if role == "read_only":
            _log_call(ws, principal.get("id"), 401, error={"code": "UNAUTHORIZED", "message": "read_only principals cannot mutate."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("UNAUTHORIZED", "read_only principals cannot mutate.")
        if action == "send" and role == "analyst":
            _log_call(ws, principal.get("id"), 401, error={"code": "UNAUTHORIZED", "message": "analyst principals cannot send messages."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("UNAUTHORIZED", "analyst principals cannot send messages.")
    if action in {"send", "create_template", "update_template", "create_campaign", "schedule_campaign", "pause_campaign"} and ws.get("status") != "active":
        _log_call(ws, principal.get("id"), 409, error={"code": "CONFLICT", "message": "Workspace must be active for this operation."})
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)
        return _err("CONFLICT", "Workspace must be active for this operation.")

    contacts, contacts_wrapper = _load_rows("contacts.json")
    messaging, messaging_wrapper = _load_rows("messaging_objects.json")

    def _find_contact(cid):
        return next((c for c in contacts if isinstance(c, dict) and c.get("id") == cid and c.get("workspace_id") == workspace_id), None)

    def _find_msg(mid):
        return next((m for m in messaging if isinstance(m, dict) and m.get("id") == mid and m.get("workspace_id") == workspace_id), None)

    transitions = {
        "draft": {"active", "scheduled", "deleted"},
        "active": {"scheduled", "paused", "disabled", "deleted"},
        "scheduled": {"sending", "paused", "disabled", "deleted"},
        "sending": {"sent", "failed"},
        "sent": {"archived"},
        "delivered": {"opened", "clicked", "archived"},
        "opened": {"clicked", "archived"},
        "clicked": {"archived"},
        "bounced": {"archived"},
        "failed": {"archived"},
        "paused": {"active", "disabled", "deleted"},
        "disabled": {"active", "deleted"},
        "received": {"processed", "failed"},
        "processed": {"archived"},
        "archived": set(),
        "deleted": set(),
    }

    def _encrypt_secret(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        # simple reversible envelope using base64 (simulating at-rest encryption)
        return "enc:" + base64.b64encode(s.encode("utf-8")).decode("ascii")

    if action == "get":
        if id is None:
            _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "id is required for get."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("VALIDATION_ERROR", "id is required for get.")
        obj = _find_msg(id)
        if not obj:
            _log_call(ws, principal.get("id"), 404, error={"code": "NOT_FOUND", "message": "Messaging object not found."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("NOT_FOUND", "Messaging object not found.")
        _log_call(ws, principal.get("id"), 200, extra={"action": "get", "id": id})
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)
        return {"object": obj}

    if action == "list_templates":
        lim = limit or 50
        start = 0
        if cursor:
            try:
                start = max(0, int(cursor))
            except ValueError:
                _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "Invalid cursor."})
                _save_rows("workspaces.json", workspaces, workspaces_wrapper)
                return _err("VALIDATION_ERROR", "Invalid cursor.")
        rows = [m for m in messaging if isinstance(m, dict) and m.get("workspace_id") == workspace_id and m.get("object_type") == "whatsapp_template"]
        if status is not None:
            rows = [m for m in rows if m.get("status") == status]
        rows.sort(key=lambda m: (m.get("updated_at") or ""), reverse=True)
        page = rows[start:start + lim]
        next_cursor = str(start + lim) if start + lim < len(rows) else None
        _log_call(ws, principal.get("id"), 200, extra={"action": "list_templates", "returned": len(page)})
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)
        return {"templates": page, "total": len(rows), "has_more": next_cursor is not None, "next_cursor": next_cursor}

    if action == "create_template":
        if body is None:
            _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "body is required."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("VALIDATION_ERROR", "body is required.")
        now = _now_iso()
        tpl_id = _gen_id("brv_msg_")
        tpl = {
            "id": tpl_id,
            "workspace_id": workspace_id,
            "object_type": "whatsapp_template",
            "status": "draft",
            "name": body.get("name"),
            "channel": "whatsapp",
            "subject": None,
            "from_email": None,
            "from_name": None,
            "to_contact_id": None,
            "to_address": None,
            "template_id": None,
            "payload": body.get("payload") if isinstance(body.get("payload"), dict) else {},
            "scheduled_for": None,
            "send_provider_message_id": None,
            "tracking": body.get("tracking") if isinstance(body.get("tracking"), dict) else {},
            "event_type": None,
            "event_at": None,
            "webhook_url": None,
            "webhook_secret": None,
            "enabled_events": None,
            "retry_policy": None,
            "conversation_thread_id": None,
            "inbound_message_id": None,
            "attachments": [],
            "crm_link": {},
            "ecommerce_link": {},
            "created_by_principal_id": principal.get("id"),
            "created_at": now,
            "updated_at": now,
        }
        messaging.append(tpl)
        _save_rows("messaging_objects.json", messaging, messaging_wrapper)
        _log_call(ws, principal.get("id"), 200, extra={"action": "create_template", "id": tpl_id})
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)
        return {"template": tpl}

    if action == "update_template":
        if id is None:
            _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "id is required for update_template."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("VALIDATION_ERROR", "id is required for update_template.")
        if body is None:
            _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "body is required for update_template."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("VALIDATION_ERROR", "body is required for update_template.")
        tpl = _find_msg(id)
        if not tpl or tpl.get("object_type") != "whatsapp_template":
            _log_call(ws, principal.get("id"), 404, error={"code": "NOT_FOUND", "message": "WhatsApp template not found."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("NOT_FOUND", "WhatsApp template not found.")
        if "name" in body:
            tpl["name"] = body.get("name")
        if "payload" in body:
            if body.get("payload") is not None and not isinstance(body.get("payload"), dict):
                _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "body.payload must be an object."})
                _save_rows("workspaces.json", workspaces, workspaces_wrapper)
                return _err("VALIDATION_ERROR", "body.payload must be an object.")
            tpl["payload"] = body.get("payload") or {}
        if "tracking" in body:
            if body.get("tracking") is not None and not isinstance(body.get("tracking"), dict):
                _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "body.tracking must be an object."})
                _save_rows("workspaces.json", workspaces, workspaces_wrapper)
                return _err("VALIDATION_ERROR", "body.tracking must be an object.")
            tpl["tracking"] = body.get("tracking") or {}
        tpl["updated_at"] = _now_iso()
        _save_rows("messaging_objects.json", messaging, messaging_wrapper)
        _log_call(ws, principal.get("id"), 200, extra={"action": "update_template", "id": id})
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)
        return {"template": tpl}

    if action == "send":
        if body is None:
            _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "body is required for send."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("VALIDATION_ERROR", "body is required for send.")
        to_contact_id = body.get("to_contact_id")
        to_address = body.get("to_address")
        template_id = body.get("template_id")
        payload = body.get("payload") if isinstance(body.get("payload"), dict) else {}
        tracking = body.get("tracking") if isinstance(body.get("tracking"), dict) else {}
        scheduled_for = body.get("scheduled_for")
        scheduled_dt = _parse_dt(scheduled_for) if scheduled_for is not None else None
        if scheduled_for is not None and scheduled_dt is None:
            _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "body.scheduled_for must be ISO 8601."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("VALIDATION_ERROR", "body.scheduled_for must be ISO 8601.")

        contact = None
        resolved_to = None
        if to_contact_id is not None:
            if not isinstance(to_contact_id, str) or not cnt_pat.match(to_contact_id):
                _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "Invalid body.to_contact_id."})
                _save_rows("workspaces.json", workspaces, workspaces_wrapper)
                return _err("VALIDATION_ERROR", "Invalid body.to_contact_id.")
            contact = _find_contact(to_contact_id)
            if not contact:
                _log_call(ws, principal.get("id"), 404, error={"code": "NOT_FOUND", "message": "Recipient contact not found."})
                _save_rows("workspaces.json", workspaces, workspaces_wrapper)
                return _err("NOT_FOUND", "Recipient contact not found.")
            if isinstance(contact.get("whatsapp_e164"), str) and contact.get("whatsapp_e164").strip():
                resolved_to = contact.get("whatsapp_e164").strip()
            elif isinstance(to_address, str) and to_address.strip():
                resolved_to = to_address.strip()
            else:
                _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "WhatsApp send requires whatsapp_e164 on contact or body.to_address."})
                _save_rows("workspaces.json", workspaces, workspaces_wrapper)
                return _err("VALIDATION_ERROR", "WhatsApp send requires whatsapp_e164 on contact or body.to_address.")
        else:
            if not isinstance(to_address, str) or not to_address.strip():
                _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "WhatsApp send requires body.to_address when not using a contact."})
                _save_rows("workspaces.json", workspaces, workspaces_wrapper)
                return _err("VALIDATION_ERROR", "WhatsApp send requires body.to_address when not using a contact.")
            resolved_to = to_address.strip()

        # template validation if provided
        if template_id is not None:
            if not isinstance(template_id, str) or not msg_pat.match(template_id):
                _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "Invalid body.template_id."})
                _save_rows("workspaces.json", workspaces, workspaces_wrapper)
                return _err("VALIDATION_ERROR", "Invalid body.template_id.")
            tpl = _find_msg(template_id)
            if not tpl:
                _log_call(ws, principal.get("id"), 404, error={"code": "NOT_FOUND", "message": "Template not found."})
                _save_rows("workspaces.json", workspaces, workspaces_wrapper)
                return _err("NOT_FOUND", "Template not found.")
            if tpl.get("object_type") != "whatsapp_template":
                _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "template_id must reference a whatsapp_template."})
                _save_rows("workspaces.json", workspaces, workspaces_wrapper)
                return _err("VALIDATION_ERROR", "template_id must reference a whatsapp_template.")

        # quota
        if not isinstance(ws.get("quota_daily_whatsapp"), int) or ws.get("quota_daily_whatsapp") < 0:
            ws["quota_daily_whatsapp"] = 0
        if ws["usage_today"]["whatsapp_sent"] >= ws["quota_daily_whatsapp"]:
            _log_call(ws, principal.get("id"), 429, error={"code": "QUOTA_EXCEEDED", "message": "Daily WhatsApp quota exceeded."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("QUOTA_EXCEEDED", "Daily WhatsApp quota exceeded.", quota=ws["quota_daily_whatsapp"], used=ws["usage_today"]["whatsapp_sent"])

        now = _now_iso()
        send_id = _gen_id("brv_msg_")
        send_row = {
            "id": send_id,
            "workspace_id": workspace_id,
            "object_type": "whatsapp_send",
            "status": "sending",
            "name": body.get("name"),
            "channel": "whatsapp",
            "subject": None,
            "from_email": None,
            "from_name": None,
            "to_contact_id": to_contact_id,
            "to_address": resolved_to,
            "template_id": template_id,
            "payload": payload,
            "scheduled_for": scheduled_dt.isoformat().replace("+00:00", "Z") if scheduled_dt else None,
            "send_provider_message_id": None,
            "tracking": tracking,
            "event_type": None,
            "event_at": None,
            "webhook_url": None,
            "webhook_secret": None,
            "enabled_events": None,
            "retry_policy": None,
            "conversation_thread_id": None,
            "inbound_message_id": None,
            "attachments": [],
            "crm_link": {},
            "ecommerce_link": {},
            "created_by_principal_id": principal.get("id"),
            "created_at": now,
            "updated_at": now,
        }
        if scheduled_dt is not None:
            send_row["status"] = "scheduled"
        messaging.append(send_row)

        if scheduled_dt is None:
            will_fail = bool(payload.get("force_fail")) or bool(payload.get("simulate_fail"))
            if will_fail:
                send_row["status"] = "failed"
            else:
                send_row["status"] = "sent"
                ws["usage_today"]["whatsapp_sent"] += 1
            send_row["updated_at"] = _now_iso()

        _save_rows("messaging_objects.json", messaging, messaging_wrapper)
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)
        _log_call(ws, principal.get("id"), 200, extra={"action": "send", "message_id": send_id, "status": send_row["status"]})
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)
        return {"message": send_row}

    if action == "create_campaign":
        if body is None or not isinstance(body, dict):
            _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "body is required."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("VALIDATION_ERROR", "body is required.")
        now = _now_iso()
        camp_id = _gen_id("brv_msg_")
        camp = {
            "id": camp_id,
            "workspace_id": workspace_id,
            "object_type": "campaign",
            "status": "draft",
            "name": body.get("name"),
            "channel": "whatsapp",
            "subject": None,
            "from_email": None,
            "from_name": None,
            "to_contact_id": None,
            "to_address": None,
            "template_id": body.get("template_id"),
            "payload": body.get("payload") if isinstance(body.get("payload"), dict) else {},
            "scheduled_for": None,
            "send_provider_message_id": None,
            "tracking": body.get("tracking") if isinstance(body.get("tracking"), dict) else {},
            "event_type": None,
            "event_at": None,
            "webhook_url": None,
            "webhook_secret": None,
            "enabled_events": None,
            "retry_policy": None,
            "conversation_thread_id": None,
            "inbound_message_id": None,
            "attachments": [],
            "crm_link": {},
            "ecommerce_link": {},
            "created_by_principal_id": principal.get("id"),
            "created_at": now,
            "updated_at": now,
        }
        messaging.append(camp)
        _save_rows("messaging_objects.json", messaging, messaging_wrapper)
        _log_call(ws, principal.get("id"), 200, extra={"action": "create_campaign", "id": camp_id})
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)
        return {"campaign": camp}

    if action == "schedule_campaign":
        if id is None:
            _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "id is required."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("VALIDATION_ERROR", "id is required.")
        if body is None or not isinstance(body, dict) or body.get("scheduled_for") is None:
            _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "body.scheduled_for is required."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("VALIDATION_ERROR", "body.scheduled_for is required.")
        camp = _find_msg(id)
        if not camp or camp.get("object_type") != "campaign" or camp.get("channel") != "whatsapp":
            _log_call(ws, principal.get("id"), 404, error={"code": "NOT_FOUND", "message": "WhatsApp campaign not found."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("NOT_FOUND", "WhatsApp campaign not found.")
        sdt = _parse_dt(body.get("scheduled_for"))
        if not sdt:
            _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "scheduled_for must be ISO 8601."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("VALIDATION_ERROR", "scheduled_for must be ISO 8601.")
        old = camp.get("status")
        new = "scheduled"
        if new not in transitions.get(old, set()):
            _log_call(ws, principal.get("id"), 409, error={"code": "INVALID_TRANSITION", "message": f"Illegal status transition {old} -> {new}."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("INVALID_TRANSITION", f"Illegal status transition {old} -> {new}.")
        camp["status"] = "scheduled"
        camp["scheduled_for"] = sdt.isoformat().replace("+00:00", "Z")
        camp["updated_at"] = _now_iso()
        _save_rows("messaging_objects.json", messaging, messaging_wrapper)
        _log_call(ws, principal.get("id"), 200, extra={"action": "schedule_campaign", "id": id})
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)
        return {"campaign": camp}

    if action == "pause_campaign":
        if id is None:
            _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "id is required."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("VALIDATION_ERROR", "id is required.")
        camp = _find_msg(id)
        if not camp or camp.get("object_type") != "campaign" or camp.get("channel") != "whatsapp":
            _log_call(ws, principal.get("id"), 404, error={"code": "NOT_FOUND", "message": "WhatsApp campaign not found."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("NOT_FOUND", "WhatsApp campaign not found.")
        old = camp.get("status")
        new = "paused"
        if new not in transitions.get(old, set()):
            _log_call(ws, principal.get("id"), 409, error={"code": "INVALID_TRANSITION", "message": f"Illegal status transition {old} -> {new}."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("INVALID_TRANSITION", f"Illegal status transition {old} -> {new}.")
        camp["status"] = "paused"
        camp["updated_at"] = _now_iso()
        _save_rows("messaging_objects.json", messaging, messaging_wrapper)
        _log_call(ws, principal.get("id"), 200, extra={"action": "pause_campaign", "id": id})
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)
        return {"campaign": camp}

    _log_call(ws, principal.get("id"), 400, error={"code": "VALIDATION_ERROR", "message": "Unhandled action."})
    _save_rows("workspaces.json", workspaces, workspaces_wrapper)
    return _err("VALIDATION_ERROR", "Unhandled action.")

def events(action, workspace_id, id=None, event_type=None, to_contact_id=None, event_at=None, limit=None, cursor=None, sort=None, order=None, body=None, **_extra):
    import json, os, datetime, re, time, base64, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0080000" if __import__("os").path.isdir("./environment_mix/0080000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "events"

    wsp_pat = re.compile(r"^brv_wsp_[0-9A-Z]{18,}$")
    msg_pat = re.compile(r"^brv_msg_[0-9A-Z]{18,}$")
    cnt_pat = re.compile(r"^brv_cnt_[0-9A-Z]{18,}$")

    allowed_actions = {"track", "list", "get"}
    allowed_event_types = {"delivered", "opened", "clicked", "bounced", "spam", "unsubscribed", "reply", "complaint", "custom", "inbound_received"}
    allowed_sort = {"event_at", "created_at", "updated_at"}
    allowed_order = {"asc", "desc"}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        rnd = random.SystemRandom()
        return prefix + "".join(rnd.choice(alphabet) for _ in range(20))

    def _log(status_code, message=None, **meta):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _gen_id("brv_req_"),
            "endpoint": endpoint,
            "action": action,
            "workspace_id": workspace_id,
            "status": status_code,
            "message": message,
            "meta": meta or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _now_iso(),
        })
        _save("request_logs.json", logs)

    if action not in allowed_actions:
        _log("VALIDATION_ERROR", "Invalid action")
        return _err("VALIDATION_ERROR", "action must be one of: track, list, get.")
    if not isinstance(workspace_id, str) or not wsp_pat.match(workspace_id):
        _log("VALIDATION_ERROR", "Invalid workspace_id")
        return _err("VALIDATION_ERROR", "workspace_id must match expected format.")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1 or limit > 500:
        _log("VALIDATION_ERROR", "Invalid limit")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500.")
    if cursor is not None and not isinstance(cursor, str):
        _log("VALIDATION_ERROR", "Invalid cursor")
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if sort is None:
        sort = "event_at"
    if sort not in allowed_sort:
        _log("VALIDATION_ERROR", "Invalid sort")
        return _err("VALIDATION_ERROR", "sort must be one of: event_at, created_at, updated_at.")
    if order is None:
        order = "desc"
    if order not in allowed_order:
        _log("VALIDATION_ERROR", "Invalid order")
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc.")
    if event_type is not None and event_type not in allowed_event_types:
        _log("VALIDATION_ERROR", "Invalid event_type")
        return _err("VALIDATION_ERROR", "event_type must be a valid event type.")
    if to_contact_id is not None and (not isinstance(to_contact_id, str) or not cnt_pat.match(to_contact_id)):
        _log("VALIDATION_ERROR", "Invalid to_contact_id")
        return _err("VALIDATION_ERROR", "to_contact_id must match expected format.")

    workspaces = _load("workspaces.json")
    msgs = _load("messaging_objects.json")
    contacts = _load("contacts.json")
    if not isinstance(workspaces, list): workspaces = []
    if not isinstance(msgs, list): msgs = []
    if not isinstance(contacts, list): contacts = []

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _log("NOT_FOUND", "Workspace not found")
        return _err("NOT_FOUND", "workspace not found.")

    # Increment api_calls and enforce daily events quota only for track
    if not isinstance(ws.get("usage_today"), dict):
        ws["usage_today"] = {}
    for k in ("emails_sent", "sms_sent", "whatsapp_sent", "events_ingested", "api_calls"):
        if not isinstance(ws["usage_today"].get(k), int) or ws["usage_today"].get(k) < 0:
            ws["usage_today"][k] = 0
    ws["usage_today"]["api_calls"] += 1
    ws["updated_at"] = _now_iso()
    _save("workspaces.json", workspaces)

    def _decode_cursor(cur):
        if not cur:
            return 0
        try:
            pad = "=" * (-len(cur) % 4)
            val = base64.urlsafe_b64decode((cur + pad).encode("utf-8")).decode("utf-8")
            return int(val)
        except Exception:
            return None

    def _encode_cursor(i):
        return base64.urlsafe_b64encode(str(i).encode("utf-8")).decode("utf-8").rstrip("=")

    def _sort_key(row):
        v = row.get(sort)
        if sort in ("created_at", "updated_at", "event_at"):
            dt = _parse_dt(v) if isinstance(v, str) else None
            return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return v or ""

    try:
        if action == "get":
            if not isinstance(id, str) or not msg_pat.match(id):
                _log("VALIDATION_ERROR", "Invalid id")
                return _err("VALIDATION_ERROR", "id must be provided and match expected format.")
            row = next((m for m in msgs if isinstance(m, dict) and m.get("id") == id and m.get("workspace_id") == workspace_id and m.get("object_type") == "custom_event"), None)
            if not row:
                _log("NOT_FOUND", "Event not found")
                return _err("NOT_FOUND", "event not found.")
            _log("OK")
            return {"data": row}

        if action == "list":
            rows = [m for m in msgs if isinstance(m, dict) and m.get("workspace_id") == workspace_id and m.get("object_type") in ("custom_event", "email_event")]
            if event_type is not None:
                rows = [r for r in rows if r.get("event_type") == event_type]
            if to_contact_id is not None:
                rows = [r for r in rows if r.get("to_contact_id") == to_contact_id]
            rows.sort(key=_sort_key, reverse=(order == "desc"))
            off = _decode_cursor(cursor)
            if off is None or off < 0:
                _log("VALIDATION_ERROR", "Invalid cursor")
                return _err("VALIDATION_ERROR", "cursor is invalid.")
            page = rows[off: off + limit]
            next_off = off + len(page)
            has_more = next_off < len(rows)
            _log("OK", total=len(rows), returned=len(page), has_more=has_more)
            return {"data": page, "meta": {"total": len(rows), "has_more": has_more, "next_cursor": _encode_cursor(next_off) if has_more else None}}

        if action == "track":
            b = body if isinstance(body, dict) else {}
            et = b.get("event_type") or event_type or "custom"
            if et != "custom":
                _log("VALIDATION_ERROR", "Only custom events supported by track")
                return _err("VALIDATION_ERROR", "events.track only supports event_type='custom'.")
            tc = b.get("to_contact_id") or to_contact_id
            if tc is not None:
                if not isinstance(tc, str) or not cnt_pat.match(tc):
                    _log("VALIDATION_ERROR", "Invalid to_contact_id")
                    return _err("VALIDATION_ERROR", "to_contact_id must match expected format.")
                c = next((c for c in contacts if isinstance(c, dict) and c.get("id") == tc and c.get("workspace_id") == workspace_id), None)
                if not c:
                    _log("NOT_FOUND", "Contact not found")
                    return _err("NOT_FOUND", "contact not found.")

            dt = _parse_dt(b.get("event_at") or event_at) or datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
            quota = ws.get("quota_daily_events")
            if not isinstance(quota, int) or quota < 0:
                quota = 0
            ing = ws["usage_today"].get("events_ingested", 0)
            if ing + 1 > quota:
                _log("QUOTA_EXCEEDED", "Daily events quota exceeded", events_ingested=ing, quota_daily_events=quota)
                return _err("QUOTA_EXCEEDED", "Daily events quota exceeded.", quota_daily_events=quota, events_ingested=ing)

            row = {
                "id": _gen_id("brv_msg_"),
                "workspace_id": workspace_id,
                "object_type": "custom_event",
                "status": "processed",
                "name": b.get("name"),
                "channel": None,
                "subject": None,
                "from_email": None,
                "from_name": None,
                "to_contact_id": tc,
                "to_address": None,
                "template_id": None,
                "payload": b.get("payload") if isinstance(b.get("payload"), dict) else {},
                "scheduled_for": None,
                "send_provider_message_id": None,
                "tracking": b.get("tracking") if isinstance(b.get("tracking"), dict) else {},
                "event_type": "custom",
                "event_at": dt.replace(microsecond=0).isoformat().replace("+00:00", "Z"),
                "webhook_url": None,
                "webhook_secret": None,
                "enabled_events": None,
                "retry_policy": None,
                "conversation_thread_id": None,
                "inbound_message_id": None,
                "attachments": [],
                "crm_link": {},
                "ecommerce_link": {},
                "created_by_principal_id": None,
                "created_at": _now_iso(),
                "updated_at": _now_iso(),
            }
            msgs.append(row)
            ws["usage_today"]["events_ingested"] = ing + 1
            ws["updated_at"] = _now_iso()
            _save("messaging_objects.json", msgs)
            _save("workspaces.json", workspaces)
            _log("OK", id=row["id"])
            return {"data": row}

        _log("VALIDATION_ERROR", "Unhandled action")
        return _err("VALIDATION_ERROR", "Unhandled action.")
    except Exception as e:
        _log("VALIDATION_ERROR", "Unexpected error", detail=str(e))
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def inbound(action, workspace_id, id=None, status=None, limit=None, cursor=None, sort=None, order=None, body=None, **_extra):
