    allowed_actions = {"receive", "process", "get", "list"}
    allowed_status = {"received", "processed", "failed", "archived", "deleted", "draft", "active", "scheduled", "sending", "sent", "delivered", "opened", "clicked", "bounced", "paused", "disabled"}
