        return _err("VALIDATION_ERROR", "workspace_id must match expected format.")
    if status is not None and status not in allowed_status:
        _log("VALIDATION_ERROR", "Invalid status")
        return _err("VALIDATION_ERROR", "status must be a valid status.")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1 or limit > 200:
        _log("VALIDATION_ERROR", "Invalid limit")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
