    ws["updated_at"] = _now_iso()
    _save("workspaces.json", workspaces)

    def _decode_cursor(cur):
        if not cur:
            return 0
        try:
            pad = "=" * (-len(cur) % 4)
            val = base64.urlsafe_b64decode((cur + pad).encode("utf-8")).decode("utf-8")
            return int(val)
        except Exception:
            return None

    def _encode_cursor(i):
        return base64.urlsafe_b64encode(str(i).encode("utf-8")).decode("utf-8").rstrip("=")

    transitions = {
        "received": ["processed", "failed"],
        "processed": ["archived"],
        "failed": ["archived"],
        "archived": [],
        "deleted": [],
        "draft": ["active", "scheduled", "deleted"],
        "active": ["scheduled", "paused", "disabled", "deleted"],
        "scheduled": ["sending", "paused", "disabled", "deleted"],
        "sending": ["sent", "failed"],
        "sent": ["archived"],
        "delivered": ["opened", "clicked", "archived"],
        "opened": ["clicked", "archived"],
        "clicked": ["archived"],
        "bounced": ["archived"],
        "paused": ["active", "disabled", "deleted"],
        "disabled": ["active", "deleted"],
    }

    def _sort_key(row):
        v = row.get(sort)
        dt = _parse_dt(v) if isinstance(v, str) else None
        return dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    try:
        if action == "get":
