            has_more = next_off < len(rows)
            _log("OK", total=len(rows), returned=len(page), has_more=has_more)
            return {"data": page, "meta": {"total": len(rows), "has_more": has_more, "next_cursor": _encode_cursor(next_off) if has_more else None}}

        if action == "receive":
