            attachments = b.get("attachments")
            if attachments is None:
                attachments = []
            if not isinstance(attachments, list):
                _log("VALIDATION_ERROR", "attachments must be array")
                return _err("VALIDATION_ERROR", "attachments must be an array.")
            total_size = 0
            norm_attachments = []
            for a in attachments:
                if not isinstance(a, dict):
                    _log("VALIDATION_ERROR", "attachment must be object")
                    return _err("VALIDATION_ERROR", "Each attachment must be an object.")
                if "storage_key" not in a or "size" not in a:
                    _log("VALIDATION_ERROR", "attachment missing storage_key/size")
