                    _log("VALIDATION_ERROR", "attachment size invalid")
                    return _err("VALIDATION_ERROR", "Attachment size must be a non-negative integer.")
                total_size += a.get("size")
                norm_attachments.append(a)
            if total_size > 25000000:
                _log("VALIDATION_ERROR", "total attachment size exceeds limit", total_size=total_size)
                return _err("VALIDATION_ERROR", "Total attachment size must be <= 25,000,000 bytes.", total_size=total_size)

            thread_id = b.get("conversation_thread_id")
