            if status not in transitions.get(cur, []):
                _log("INVALID_TRANSITION", "Invalid transition", from_status=cur, to_status=status)
                return _err("INVALID_TRANSITION", f"Cannot transition status from '{cur}' to '{status}'.", from_status=cur, to_status=status)
            row["status"] = status
            row["updated_at"] = _now_iso()
            _save("messaging_objects.json", msgs)
            _log("OK")
            return {"data": row}

        _log("VALIDATION_ERROR", "Unhandled action")
        return _err("VALIDATION_ERROR", "Unhandled action.")
    except Exception as e:
        _log("VALIDATION_ERROR", "Unexpected error", detail=str(e))
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def enterprise(action, workspace_id=None, principal_id=None, status=None, limit=None, cursor=None, sort=None, order=None, body=None, **_extra):
    import json, os, datetime, time, re, base64, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0080000" if __import__("os").path.isdir("./environment_mix/0080000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "enterprise"

    wsp_pat = re.compile(r"^brv_wsp_[0-9A-Z]{18,}$")
    prn_pat = re.compile(r"^brv_prn_[0-9A-Z]{18,}$")

    allowed_actions = {"create_workspace", "update_workspace", "get_workspace", "list_workspaces", "create_principal", "update_principal", "get_principal", "list_principals", "disable_principal"}
    ws_status = {"active", "suspended", "closed"}
    prn_status = {"active", "invited", "disabled"}
    prn_roles = {"owner", "admin", "editor", "analyst", "support", "read_only"}
    prn_types = {"user", "service"}
    sort_fields = {"created_at", "updated_at", "name", "email", "status"}
    orders = {"asc", "desc"}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        rnd = random.SystemRandom()
        return prefix + "".join(rnd.choice(alphabet) for _ in range(20))

    def _log(status_code, message=None, **meta):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _gen_id("brv_req_"),
            "endpoint": endpoint,
            "action": action,
            "workspace_id": workspace_id,
            "principal_id": principal_id,
            "status": status_code,
            "message": message,
            "meta": meta or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _now_iso(),
        })
        _save("request_logs.json", logs)

    if action not in allowed_actions:
        _log("VALIDATION_ERROR", "Invalid action")
        return _err("VALIDATION_ERROR", "Invalid action.")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1 or limit > 200:
        _log("VALIDATION_ERROR", "Invalid limit")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        _log("VALIDATION_ERROR", "Invalid cursor")
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if sort is None:
        sort = "created_at"
    if sort not in sort_fields:
        _log("VALIDATION_ERROR", "Invalid sort")
        return _err("VALIDATION_ERROR", "sort must be one of: created_at, updated_at, name, email, status.")
    if order is None:
        order = "desc"
    if order not in orders:
        _log("VALIDATION_ERROR", "Invalid order")
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc.")

    workspaces = _load("workspaces.json")
    principals = _load("principals.json")
    if not isinstance(workspaces, list): workspaces = []
    if not isinstance(principals, list): principals = []

    # Ambient enterprise actor: any active owner/admin across the system, else any active principal
    pref = {"owner": 0, "admin": 1, "editor": 2, "support": 3, "analyst": 4, "read_only": 5}
    active_principals = [p for p in principals if isinstance(p, dict) and p.get("status") == "active"]
    active_principals.sort(key=lambda p: pref.get(p.get("role"), 99))
    actor = active_principals[0] if active_principals else None

    def _actor_can_mutate():
        if actor is None:
            return True
        if actor.get("status") != "active":
            return False
        if actor.get("role") == "read_only":
            return False
        return True

    def _can_change_quotas():
        if actor is None:
            return True
        if actor.get("role") == "support":
            return False
        return _actor_can_mutate()

    def _decode_cursor(cur):
        if not cur:
            return 0
        try:
            pad = "=" * (-len(cur) % 4)
            val = base64.urlsafe_b64decode((cur + pad).encode("utf-8")).decode("utf-8")
            return int(val)
        except Exception:
            return None

    def _encode_cursor(i):
        return base64.urlsafe_b64encode(str(i).encode("utf-8")).decode("utf-8").rstrip("=")

    def _sort_key(row):
        v = row.get(sort)
        if sort in ("created_at", "updated_at"):
            try:
                dt = datetime.datetime.fromisoformat(str(v).replace("Z", "+00:00"))
            except Exception:
                dt = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return dt
        if v is None:
            return ""
        return str(v).lower()

    try:
        if action in ("get_workspace", "update_workspace") and workspace_id is not None:
            if not isinstance(workspace_id, str) or not wsp_pat.match(workspace_id):
                _log("VALIDATION_ERROR", "Invalid workspace_id")
                return _err("VALIDATION_ERROR", "workspace_id must match expected format.")
        if action in ("get_principal", "update_principal", "disable_principal") and principal_id is not None:
            if not isinstance(principal_id, str) or not prn_pat.match(principal_id):
                _log("VALIDATION_ERROR", "Invalid principal_id")
                return _err("VALIDATION_ERROR", "principal_id must match expected format.")

        if action == "list_workspaces":
            rows = list(workspaces)
            if status is not None:
                rows = [r for r in rows if isinstance(r, dict) and r.get("status") == status]
            rows = [r for r in rows if isinstance(r, dict)]
            rows.sort(key=_sort_key, reverse=(order == "desc"))
            off = _decode_cursor(cursor)
            if off is None or off < 0:
                _log("VALIDATION_ERROR", "Invalid cursor")
                return _err("VALIDATION_ERROR", "cursor is invalid.")
            page = rows[off: off + limit]
            next_off = off + len(page)
            has_more = next_off < len(rows)
            _log("OK", total=len(rows), returned=len(page), has_more=has_more)
            return {"data": page, "meta": {"total": len(rows), "has_more": has_more, "next_cursor": _encode_cursor(next_off) if has_more else None}}

        if action == "get_workspace":
            if workspace_id is None:
                _log("VALIDATION_ERROR", "workspace_id required")
                return _err("VALIDATION_ERROR", "workspace_id is required.")
            ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
            if not ws:
                _log("NOT_FOUND", "Workspace not found")
                return _err("NOT_FOUND", "workspace not found.")
            _log("OK")
            return {"data": ws}

        if action == "create_workspace":
            if not _actor_can_mutate():
                _log("UNAUTHORIZED", "Actor cannot mutate")
                return _err("UNAUTHORIZED", "Actor role/status forbids mutation.")
            b = body if isinstance(body, dict) else {}
            nm = b.get("name")
            if not isinstance(nm, str) or not nm.strip():
                _log("VALIDATION_ERROR", "name required")
                return _err("VALIDATION_ERROR", "name is required.")
            if any(isinstance(w, dict) and w.get("name") == nm for w in workspaces):
                _log("CONFLICT", "Workspace name must be unique")
                return _err("CONFLICT", "Workspace name must be unique.")
            # quotas validation
            for qk in ("quota_daily_emails", "quota_daily_sms", "quota_daily_whatsapp", "quota_daily_events"):
                if qk in b and (not isinstance(b.get(qk), int) or isinstance(b.get(qk), bool) or b.get(qk) < 0):
                    _log("VALIDATION_ERROR", f"{qk} invalid")
                    return _err("VALIDATION_ERROR", f"{qk} must be a non-negative integer.")
            row = {
                "id": _gen_id("brv_wsp_"),
                "brevo_account_id": b.get("brevo_account_id"),
                "name": nm,
                "status": b.get("status") if b.get("status") in ws_status else "active",
                "default_sender_email": b.get("default_sender_email"),
                "default_sender_name": b.get("default_sender_name"),
                "verified_domains": b.get("verified_domains") if isinstance(b.get("verified_domains"), list) else [],
                "folders": b.get("folders") if isinstance(b.get("folders"), list) else [],
                "quota_daily_emails": int(b.get("quota_daily_emails", 0)),
                "quota_daily_sms": int(b.get("quota_daily_sms", 0)),
                "quota_daily_whatsapp": int(b.get("quota_daily_whatsapp", 0)),
                "quota_daily_events": int(b.get("quota_daily_events", 0)),
                "usage_today": {"emails_sent": 0, "sms_sent": 0, "whatsapp_sent": 0, "events_ingested": 0, "api_calls": 0},
                "brevo_api_key_fingerprint": b.get("brevo_api_key_fingerprint"),
                "timezone": b.get("timezone"),
                "created_at": _now_iso(),
                "updated_at": _now_iso(),
            }
            workspaces.append(row)
            _save("workspaces.json", workspaces)
            _log("OK", id=row["id"])
            return {"data": row}

        if action == "update_workspace":
            if not _actor_can_mutate():
                _log("UNAUTHORIZED", "Actor cannot mutate")
                return _err("UNAUTHORIZED", "Actor role/status forbids mutation.")
            if workspace_id is None:
                _log("VALIDATION_ERROR", "workspace_id required")
                return _err("VALIDATION_ERROR", "workspace_id is required.")
            ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
            if not ws:
                _log("NOT_FOUND", "Workspace not found")
                return _err("NOT_FOUND", "workspace not found.")
            b = body if isinstance(body, dict) else {}
            # account tool rule: sender/domain/folders changes only allowed when workspace active
            changing_sender_domain_folders = any(k in b for k in ("default_sender_email", "default_sender_name", "verified_domains", "folders", "timezone", "brevo_api_key_fingerprint"))
            if changing_sender_domain_folders and ws.get("status") != "active":
                _log("UNAUTHORIZED", "Workspace not active for sender/domain/folders changes")
                return _err("UNAUTHORIZED", "Workspace must be active to change sender/domain/folders/timezone/api credentials.")
            # quotas cannot be reduced below usage_today
            ut = ws.get("usage_today") if isinstance(ws.get("usage_today"), dict) else {}
            for qk, uk in (("quota_daily_emails", "emails_sent"), ("quota_daily_sms", "sms_sent"), ("quota_daily_whatsapp", "whatsapp_sent"), ("quota_daily_events", "events_ingested")):
                if qk in b:
                    if not _can_change_quotas():
                        _log("UNAUTHORIZED", "Support cannot change quotas/credentials")
                        return _err("UNAUTHORIZED", "Support role cannot change quotas or API credentials.")
                    val = b.get(qk)
                    if not isinstance(val, int) or isinstance(val, bool) or val < 0:
                        _log("VALIDATION_ERROR", f"{qk} invalid")
                        return _err("VALIDATION_ERROR", f"{qk} must be a non-negative integer.")
                    used = ut.get(uk, 0) if isinstance(ut.get(uk, 0), int) else 0
                    if val < used:
                        _log("CONFLICT", "Quota cannot be reduced below current usage", quota=qk, used=used, requested=val)
                        return _err("CONFLICT", f"{qk} cannot be reduced below current usage_today.{uk}.", used=used, requested=val)
            # unique name
            if "name" in b and b.get("name") is not None:
                nm = b.get("name")
                if not isinstance(nm, str) or not nm.strip():
                    _log("VALIDATION_ERROR", "name invalid")
                    return _err("VALIDATION_ERROR", "name must be a non-empty string.")
                if any(isinstance(w, dict) and w.get("id") != workspace_id and w.get("name") == nm for w in workspaces):
                    _log("CONFLICT", "Workspace name must be unique")
                    return _err("CONFLICT", "Workspace name must be unique.")
                ws["name"] = nm
            if "status" in b and b.get("status") is not None:
                st = b.get("status")
                if st not in ws_status:
                    _log("VALIDATION_ERROR", "status invalid")
                    return _err("VALIDATION_ERROR", "status must be one of: active, suspended, closed.")
                # enforce workspace lifecycle transitions
                transitions = {"active": ["suspended", "closed"], "suspended": ["active", "closed"], "closed": []}
                cur = ws.get("status")
                if st != cur and st not in transitions.get(cur, []):
                    _log("INVALID_TRANSITION", "Invalid workspace transition", from_status=cur, to_status=st)
                    return _err("INVALID_TRANSITION", f"Cannot transition workspace status from '{cur}' to '{st}'.", from_status=cur, to_status=st)
                ws["status"] = st
            # simple fields
            for k in ("brevo_account_id", "default_sender_email", "default_sender_name", "timezone", "brevo_api_key_fingerprint"):
                if k in b:
                    ws[k] = b.get(k)
            if "verified_domains" in b:
                if b.get("verified_domains") is not None and not isinstance(b.get("verified_domains"), list):
                    _log("VALIDATION_ERROR", "verified_domains must be array")
                    return _err("VALIDATION_ERROR", "verified_domains must be an array of strings.")
                ws["verified_domains"] = b.get("verified_domains") if isinstance(b.get("verified_domains"), list) else ws.get("verified_domains", [])
            if "folders" in b:
                if b.get("folders") is not None and not isinstance(b.get("folders"), list):
                    _log("VALIDATION_ERROR", "folders must be array")
                    return _err("VALIDATION_ERROR", "folders must be an array.")
                ws["folders"] = b.get("folders") if isinstance(b.get("folders"), list) else ws.get("folders", [])
            for qk in ("quota_daily_emails", "quota_daily_sms", "quota_daily_whatsapp", "quota_daily_events"):
                if qk in b and isinstance(b.get(qk), int) and not isinstance(b.get(qk), bool):
                    ws[qk] = b.get(qk)
            ws["updated_at"] = _now_iso()
            _save("workspaces.json", workspaces)
            _log("OK")
            return {"data": ws}

        if action == "list_principals":
            rows = [p for p in principals if isinstance(p, dict)]
            if workspace_id is not None:
                if not isinstance(workspace_id, str) or not wsp_pat.match(workspace_id):
                    _log("VALIDATION_ERROR", "Invalid workspace_id")
                    return _err("VALIDATION_ERROR", "workspace_id must match expected format.")
                rows = [r for r in rows if r.get("workspace_id") == workspace_id]
            if status is not None:
                rows = [r for r in rows if r.get("status") == status]
            rows.sort(key=_sort_key, reverse=(order == "desc"))
            off = _decode_cursor(cursor)
            if off is None or off < 0:
                _log("VALIDATION_ERROR", "Invalid cursor")
                return _err("VALIDATION_ERROR", "cursor is invalid.")
            page = rows[off: off + limit]
            next_off = off + len(page)
            has_more = next_off < len(rows)
            _log("OK", total=len(rows), returned=len(page), has_more=has_more)
            return {"data": page, "meta": {"total": len(rows), "has_more": has_more, "next_cursor": _encode_cursor(next_off) if has_more else None}}

        if action == "get_principal":
            if principal_id is None:
                _log("VALIDATION_ERROR", "principal_id required")
                return _err("VALIDATION_ERROR", "principal_id is required.")
            p = next((p for p in principals if isinstance(p, dict) and p.get("id") == principal_id), None)
            if not p:
                _log("NOT_FOUND", "Principal not found")
                return _err("NOT_FOUND", "principal not found.")
            _log("OK")
            return {"data": p}

        if action == "create_principal":
            if not _actor_can_mutate():
                _log("UNAUTHORIZED", "Actor cannot mutate")
                return _err("UNAUTHORIZED", "Actor role/status forbids mutation.")
            b = body if isinstance(body, dict) else {}
            wsid = b.get("workspace_id") or workspace_id
            if not isinstance(wsid, str) or not wsp_pat.match(wsid):
                _log("VALIDATION_ERROR", "workspace_id required/invalid")
                return _err("VALIDATION_ERROR", "workspace_id is required and must match expected format.")
            ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == wsid), None)
            if not ws:
                _log("NOT_FOUND", "Workspace not found")
                return _err("NOT_FOUND", "workspace not found.")
            ptype = b.get("type")
            if ptype not in prn_types:
                _log("VALIDATION_ERROR", "type invalid")
                return _err("VALIDATION_ERROR", "type must be 'user' or 'service'.")
            email_val = b.get("email")
            if ptype == "user" and (not isinstance(email_val, str) or not email_val.strip()):
                _log("VALIDATION_ERROR", "email required for user")
                return _err("VALIDATION_ERROR", "email is required when type='user'.")
            display_name = b.get("display_name") or b.get("name")
            if not isinstance(display_name, str) or not display_name.strip():
                _log("VALIDATION_ERROR", "display_name required")
                return _err("VALIDATION_ERROR", "display_name is required.")
            role = b.get("role")
            if role not in prn_roles:
                _log("VALIDATION_ERROR", "role invalid")
                return _err("VALIDATION_ERROR", "role must be one of: owner, admin, editor, analyst, support, read_only.")
            # unique(workspace_id, email) for user where email non-null
            if email_val is not None:
                if any(isinstance(p, dict) and p.get("workspace_id") == wsid and p.get("email") == email_val for p in principals):
                    _log("CONFLICT", "Principal email must be unique within workspace")
                    return _err("CONFLICT", "Principal email must be unique within workspace.")
            row = {
                "id": _gen_id("brv_prn_"),
                "workspace_id": wsid,
                "type": ptype,
                "email": email_val if ptype == "user" else None,
                "display_name": display_name,
                "role": role,
                "status": b.get("status") if b.get("status") in prn_status else ("invited" if ptype == "user" else "active"),
                "last_login_at": None,
                "created_at": _now_iso(),
                "updated_at": _now_iso(),
            }
            principals.append(row)
            _save("principals.json", principals)
            _log("OK", id=row["id"])
            return {"data": row}

        if action == "update_principal":
            if not _actor_can_mutate():
                _log("UNAUTHORIZED", "Actor cannot mutate")
                return _err("UNAUTHORIZED", "Actor role/status forbids mutation.")
            if principal_id is None:
                _log("VALIDATION_ERROR", "principal_id required")
                return _err("VALIDATION_ERROR", "principal_id is required.")
            p = next((p for p in principals if isinstance(p, dict) and p.get("id") == principal_id), None)
            if not p:
                _log("NOT_FOUND", "Principal not found")
                return _err("NOT_FOUND", "principal not found.")
            b = body if isinstance(body, dict) else {}
            if "role" in b and b.get("role") is not None:
                if b.get("role") not in prn_roles:
                    _log("VALIDATION_ERROR", "role invalid")
                    return _err("VALIDATION_ERROR", "role must be one of: owner, admin, editor, analyst, support, read_only.")
                p["role"] = b.get("role")
            if "display_name" in b and b.get("display_name") is not None:
                if not isinstance(b.get("display_name"), str) or not b.get("display_name").strip():
                    _log("VALIDATION_ERROR", "display_name invalid")
                    return _err("VALIDATION_ERROR", "display_name must be a non-empty string.")
                p["display_name"] = b.get("display_name")
            if "email" in b and b.get("email") is not None:
                # only for user principals
                if p.get("type") != "user":
                    _log("VALIDATION_ERROR", "email only for user principals")
                    return _err("VALIDATION_ERROR", "email can only be set for user principals.")
                em = b.get("email")
                if not isinstance(em, str) or not em.strip():
                    _log("VALIDATION_ERROR", "email invalid")
                    return _err("VALIDATION_ERROR", "email must be a non-empty string.")
                if any(isinstance(pp, dict) and pp.get("id") != principal_id and pp.get("workspace_id") == p.get("workspace_id") and pp.get("email") == em for pp in principals):
                    _log("CONFLICT", "Principal email must be unique within workspace")
                    return _err("CONFLICT", "Principal email must be unique within workspace.")
                p["email"] = em
            if "status" in b and b.get("status") is not None:
                st = b.get("status")
                if st not in prn_status:
                    _log("VALIDATION_ERROR", "status invalid")
                    return _err("VALIDATION_ERROR", "status must be one of: active, invited, disabled.")
                transitions = {"invited": ["active", "disabled"], "active": ["disabled"], "disabled": ["active"]}
                cur = p.get("status")
                if st != cur and st not in transitions.get(cur, []):
                    _log("INVALID_TRANSITION", "Invalid principal transition", from_status=cur, to_status=st)
                    return _err("INVALID_TRANSITION", f"Cannot transition principal status from '{cur}' to '{st}'.", from_status=cur, to_status=st)
                p["status"] = st
            p["updated_at"] = _now_iso()
            _save("principals.json", principals)
            _log("OK")
            return {"data": p}

        if action == "disable_principal":
            if not _actor_can_mutate():
                _log("UNAUTHORIZED", "Actor cannot mutate")
                return _err("UNAUTHORIZED", "Actor role/status forbids mutation.")
            if principal_id is None:
                _log("VALIDATION_ERROR", "principal_id required")
                return _err("VALIDATION_ERROR", "principal_id is required.")
            p = next((p for p in principals if isinstance(p, dict) and p.get("id") == principal_id), None)
            if not p:
                _log("NOT_FOUND", "Principal not found")
                return _err("NOT_FOUND", "principal not found.")
            cur = p.get("status")
            if cur == "disabled":
                _log("OK", "Idempotent")
                return {"data": p}
            transitions = {"invited": ["active", "disabled"], "active": ["disabled"], "disabled": ["active"]}
            if "disabled" not in transitions.get(cur, []):
                _log("INVALID_TRANSITION", "Invalid principal transition", from_status=cur, to_status="disabled")
                return _err("INVALID_TRANSITION", f"Cannot transition principal status from '{cur}' to 'disabled'.", from_status=cur, to_status="disabled")
            p["status"] = "disabled"
            p["updated_at"] = _now_iso()
            _save("principals.json", principals)
            _log("OK")
            return {"data": p}

        _log("VALIDATION_ERROR", "Unhandled action")
        return _err("VALIDATION_ERROR", "Unhandled action.")
    except Exception as e:
        _log("VALIDATION_ERROR", "Unexpected error", detail=str(e))
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def bulk_contact_import(workspace_id, requested_by_principal_id, input_format, raw_input, target_list_ids=None, dedupe_strategy=None, attribute_mapping=None, **_extra):
    import json, os, datetime, time, re, base64, csv, io
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0080000" if __import__("os").path.isdir("./environment_mix/0080000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    endpoint = "bulk_contact_import"
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _log(status_code, message=None, **meta):
        logs = _load("request_logs.json")
        if not isinstance(logs, list): logs = []
        row = {
            "id": "brv_log_" + base64.b32encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "principal_id": requested_by_principal_id,
            "status": status_code,
            "message": message,
            "meta": meta or {},
            "latency_ms": int((time.time() - start) * 1000),
            "ts": _now(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _gen_id(prefix):
        return prefix + base64.b32encode(os.urandom(12)).decode("ascii").rstrip("=")

    def _is_str(x): return isinstance(x, str)
    def _is_int(x): return isinstance(x, int) and not isinstance(x, bool)
    def _is_obj(x): return isinstance(x, dict)
    def _is_list(x): return isinstance(x, list)

    wsp_pat = re.compile(r"^brv_wsp_[0-9A-Z]{18,}$")
    prn_pat = re.compile(r"^brv_prn_[0-9A-Z]{18,}$")

    if not _is_str(workspace_id) or not wsp_pat.match(workspace_id):
        _log("VALIDATION_ERROR", "Invalid workspace_id")
        return _err("VALIDATION_ERROR", "workspace_id must match expected format.")
    if not _is_str(requested_by_principal_id) or not prn_pat.match(requested_by_principal_id):
        _log("VALIDATION_ERROR", "Invalid requested_by_principal_id")
        return _err("VALIDATION_ERROR", "requested_by_principal_id must match expected format.")
    if input_format not in ("pasted_text","csv","json"):
        _log("VALIDATION_ERROR", "Invalid input_format")
        return _err("VALIDATION_ERROR", "input_format must be one of 'pasted_text','csv','json'.")
    if not _is_str(raw_input):
        _log("VALIDATION_ERROR", "raw_input must be string")
        return _err("VALIDATION_ERROR", "raw_input must be a string.")
    if len(raw_input.encode("utf-8")) > 5_000_000:
        _log("VALIDATION_ERROR", "raw_input too large")
        return _err("VALIDATION_ERROR", "raw_input exceeds maximum size of 5_000_000 bytes.")

    if target_list_ids is None:
        target_list_ids = []
    if not _is_list(target_list_ids) or any(not _is_str(x) for x in target_list_ids):
        _log("VALIDATION_ERROR", "target_list_ids invalid")
        return _err("VALIDATION_ERROR", "target_list_ids must be an array of strings.")
    if len(target_list_ids) > 50:
        _log("VALIDATION_ERROR", "target_list_ids too long")
        return _err("VALIDATION_ERROR", "target_list_ids length must be <= 50.")
    if dedupe_strategy is None:
        dedupe_strategy = "skip_duplicates"
    if dedupe_strategy not in ("skip_duplicates","update_existing","create_new"):
        _log("VALIDATION_ERROR", "Invalid dedupe_strategy")
        return _err("VALIDATION_ERROR", "dedupe_strategy must be one of 'skip_duplicates','update_existing','create_new'.")
    if attribute_mapping is not None and not _is_obj(attribute_mapping):
        _log("VALIDATION_ERROR", "attribute_mapping invalid")
        return _err("VALIDATION_ERROR", "attribute_mapping must be an object when provided.")

    workspaces = _load("workspaces.json")
    principals = _load("principals.json")
    contacts = _load("contacts.json")
    jobs = _load("contact_import_jobs.json")
    if not isinstance(workspaces, list): workspaces = []
    if not isinstance(principals, list): principals = []
    if not isinstance(contacts, list): contacts = []
    if not isinstance(jobs, list): jobs = []

    w = next((x for x in workspaces if isinstance(x, dict) and x.get("id") == workspace_id), None)
    if w is None:
        _log("NOT_FOUND", "Workspace not found")
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    actor = next((p for p in principals if isinstance(p, dict) and p.get("id") == requested_by_principal_id), None)
    if actor is None:
        _log("NOT_FOUND", "Principal not found")
        return _err("NOT_FOUND", "Principal not found.", principal_id=requested_by_principal_id)
    if actor.get("workspace_id") != workspace_id:
        _log("UNAUTHORIZED", "Principal not in workspace")
        return _err("UNAUTHORIZED", "Principal does not belong to the workspace.")
    if actor.get("status") != "active":
        _log("UNAUTHORIZED", "Principal not active")
        return _err("UNAUTHORIZED", "Principal must be active to perform imports.")
    if actor.get("role") == "read_only":
        _log("UNAUTHORIZED", "read_only cannot mutate")
        return _err("UNAUTHORIZED", "read_only principals cannot perform imports.")

    # Create job queued
    now = _now()
    job = {
        "id": _gen_id("brv_imp_"),
        "workspace_id": workspace_id,
        "requested_by_principal_id": requested_by_principal_id,
        "status": "queued",
        "input_format": input_format,
        "raw_input": raw_input,
        "detected_schema": None,
        "attribute_mapping": attribute_mapping,
        "target_list_ids": target_list_ids,
        "dedupe_strategy": dedupe_strategy,
        "summary": {"parsed_rows": 0, "valid_rows": 0, "created_contacts": 0, "updated_contacts": 0, "skipped_duplicates": 0, "errors": []},
        "error": None,
        "created_at": now,
        "updated_at": now,
    }
    jobs.append(job)
    _save("contact_import_jobs.json", jobs)

    # Transition: queued -> analyzing
    job["status"] = "analyzing"
    job["updated_at"] = _now()
    _save("contact_import_jobs.json", jobs)

    # Parsing helpers
    def _norm_key(k):
        return (k or "").strip().lower().replace("-", "_").replace(" ", "_")

    # Default field mapping
    default_map = {
        "email": ("email", None),
        "e_mail": ("email", None),
        "phone": ("phone_e164", None),
        "phone_e164": ("phone_e164", None),
        "whatsapp": ("whatsapp_e164", None),
        "whatsapp_e164": ("whatsapp_e164", None),
        "first_name": ("first_name", None),
        "firstname": ("first_name", None),
        "last_name": ("last_name", None),
        "lastname": ("last_name", None),
    }

    def _apply_mapping(row):
        out = {"attributes": {}}
        for k, v in row.items():
            nk = _norm_key(k)
            dest = None
            if attribute_mapping and nk in attribute_mapping:
                dest = attribute_mapping[nk]
            elif nk in default_map:
                dest = default_map[nk][0]
            if dest in ("email","phone_e164","whatsapp_e164","first_name","last_name"):
                out[dest] = (v.strip() if isinstance(v, str) else v)
            else:
                # treat as custom attribute
                if v is None:
                    continue
                out["attributes"][k] = v
        return out

    def _find_existing(email, phone, whatsapp):
        for c in contacts:
            if not isinstance(c, dict) or c.get("workspace_id") != workspace_id:
                continue
            if email and c.get("email") == email:
                return c
            if phone and c.get("phone_e164") == phone:
                return c
            if whatsapp and c.get("whatsapp_e164") == whatsapp:
                return c
        return None

    def _conflicts(existing_id, email, phone, whatsapp):
        # uniqueness within workspace
        for c in contacts:
            if not isinstance(c, dict) or c.get("workspace_id") != workspace_id:
                continue
            if existing_id and c.get("id") == existing_id:
                continue
            if email and c.get("email") == email:
                return ("email", c.get("id"))
            if phone and c.get("phone_e164") == phone:
                return ("phone_e164", c.get("id"))
            if whatsapp and c.get("whatsapp_e164") == whatsapp:
                return ("whatsapp_e164", c.get("id"))
        return None

    # Parse rows
    parsed_rows = []
    parse_error = None
    try:
        if input_format == "json":
            data = json.loads(raw_input)
            if isinstance(data, dict) and "contacts" in data and isinstance(data["contacts"], list):
                data = data["contacts"]
            if not isinstance(data, list):
                raise ValueError("JSON input must be an array of objects (or {contacts:[...]})")
            for i, obj in enumerate(data):
                if not isinstance(obj, dict):
                    parsed_rows.append({"__rownum__": i + 1, "__error__": "Row is not an object"})
                else:
                    parsed_rows.append({"__rownum__": i + 1, **obj})
        elif input_format == "csv":
            reader = csv.DictReader(io.StringIO(raw_input))
            if reader.fieldnames is None:
                raise ValueError("CSV missing header row")
            for i, obj in enumerate(reader):
                parsed_rows.append({"__rownum__": i + 1, **obj})
        else:  # pasted_text
            # detect: if contains commas and first line has letters => treat as CSV-like with header
            lines = [ln for ln in raw_input.splitlines() if ln.strip()]
            if not lines:
                parsed_rows = []
            else:
                if "," in lines[0]:
                    reader = csv.DictReader(io.StringIO("\n".join(lines)))
                    if reader.fieldnames is None:
                        raise ValueError("pasted_text could not detect header")
                    for i, obj in enumerate(reader):
                        parsed_rows.append({"__rownum__": i + 1, **obj})
                else:
                    # one identifier per line; could be email or phone
                    for i, ln in enumerate(lines):
                        v = ln.strip()
                        row = {"__rownum__": i + 1}
                        if "@" in v:
                            row["email"] = v
                        elif v.startswith("+"):
                            row["phone_e164"] = v
                        else:
                            row["email"] = v
                        parsed_rows.append(row)
    except (ValueError, json.JSONDecodeError) as ex:
        parse_error = str(ex)

    job["summary"]["parsed_rows"] = len(parsed_rows)
    if parse_error:
        job["status"] = "failed"
        job["error"] = {"message": "Failed to parse input.", "detail": parse_error}
        job["updated_at"] = _now()
        _save("contact_import_jobs.json", jobs)
        _log("VALIDATION_ERROR", "Parse failed")
        return _err("VALIDATION_ERROR", "Failed to parse input.", detail=parse_error, job=job)

    # Build detected schema (simple)
    schema_counts = {"email": 0, "phone_e164": 0, "whatsapp_e164": 0, "first_name": 0, "last_name": 0}
    for r in parsed_rows:
        for k in list(schema_counts.keys()):
            if k in r and isinstance(r.get(k), str) and r.get(k).strip():
                schema_counts[k] += 1
    detected = {"fields": {k: {"present_rows": v, "confidence": min(1.0, v / max(1, len(parsed_rows)))} for k, v in schema_counts.items()}}
    job["detected_schema"] = detected
    _save("contact_import_jobs.json", jobs)

    # Transition: analyzing -> importing
    job["status"] = "importing"
    job["updated_at"] = _now()
    _save("contact_import_jobs.json", jobs)

    # Dedupe strategy rule: if not create_new, must have at least one unique key per valid row
    errors = []
    created = 0
    updated = 0
    skipped = 0
    valid_rows = 0

    # Prepare list ids validation (no lists collection in schema). Only accept if looks like an id.
    list_pat = re.compile(r"^brv_lst_[0-9A-Z]{18,}$")
    invalid_lists = [x for x in target_list_ids if not list_pat.match(x)]
    if invalid_lists:
        job["status"] = "failed"
        job["error"] = {"message": "Invalid list ids.", "invalid_list_ids": invalid_lists}
        job["updated_at"] = _now()
        _save("contact_import_jobs.json", jobs)
        _log("VALIDATION_ERROR", "Invalid list ids")
        return _err("VALIDATION_ERROR", "One or more list_ids are invalid.", invalid_list_ids=invalid_lists, job=job)

    def _new_contact(mapped, list_ids):
        cid = _gen_id("brv_cnt_")
        now2 = _now()
        consent = mapped.get("consent")
        if consent is None or not isinstance(consent, dict):
            consent = {"email_opt_in": None, "sms_opt_in": None, "whatsapp_opt_in": None, "lawful_basis": None, "consent_updated_at": None}
        ext = mapped.get("external_ids")
        if ext is None or not isinstance(ext, dict):
            ext = {}
        attrs = mapped.get("attributes")
        if attrs is None or not isinstance(attrs, dict):
            attrs = {}
        return {
            "id": cid,
            "workspace_id": workspace_id,
            "email": mapped.get("email"),
            "phone_e164": mapped.get("phone_e164"),
            "whatsapp_e164": mapped.get("whatsapp_e164"),
            "first_name": mapped.get("first_name"),
            "last_name": mapped.get("last_name"),
            "attributes": attrs,
            "list_ids": list_ids,
            "consent": consent,
            "status": "active",
            "source": "import",
            "external_ids": ext,
            "created_by_principal_id": requested_by_principal_id,
            "updated_by_principal_id": requested_by_principal_id,
            "created_at": now2,
            "updated_at": now2,
        }

    for r in parsed_rows:
        rownum = r.get("__rownum__")
        if not isinstance(rownum, int):
            rownum = None
        if "__error__" in r:
            errors.append({"row": rownum, "message": r.get("__error__")})
            continue

        mapped = _apply_mapping({k: v for k, v in r.items() if not str(k).startswith("__")})
        email = mapped.get("email")
        phone = mapped.get("phone_e164")
        whatsapp = mapped.get("whatsapp_e164")

        # require at least one identifier
        if not (isinstance(email, str) and email.strip()) and not (isinstance(phone, str) and phone.strip()) and not (isinstance(whatsapp, str) and whatsapp.strip()):
            errors.append({"row": rownum, "message": "Missing identifiers: at least one of email/phone_e164/whatsapp_e164 is required."})
            continue

        # Normalize strings
        if isinstance(email, str): email = email.strip() or None
        if isinstance(phone, str): phone = phone.strip() or None
        if isinstance(whatsapp, str): whatsapp = whatsapp.strip() or None
        mapped["email"], mapped["phone_e164"], mapped["whatsapp_e164"] = email, phone, whatsapp

        if dedupe_strategy != "create_new" and not (email or phone or whatsapp):
            errors.append({"row": rownum, "message": "Dedupe strategy requires a unique key (email/phone/whatsapp) per row."})
            continue

        valid_rows += 1

        existing = None
        if dedupe_strategy != "create_new":
            existing = _find_existing(email, phone, whatsapp)

        if existing is None:
            # Create new (always allowed)
            conf = _conflicts(None, email, phone, whatsapp)
            if conf:
                # conflict means this is actually duplicate; handle per strategy
                if dedupe_strategy == "skip_duplicates":
                    skipped += 1
                    continue
                elif dedupe_strategy == "update_existing":
                    # update the one we conflict with
                    field, cid = conf
                    existing = next((c for c in contacts if isinstance(c, dict) and c.get("id") == cid), None)
                    if existing is None:
                        errors.append({"row": rownum, "message": "Conflict target not found unexpectedly."})
                        continue
                else:
                    errors.append({"row": rownum, "message": f"Uniqueness conflict on {conf[0]} with existing contact {conf[1]}."})
                    continue

            if existing is None:
                cnew = _new_contact(mapped, list(target_list_ids))
                contacts.append(cnew)
                created += 1
                continue

        # Update existing
        if existing is not None:
            # uniqueness conflicts if changing identifiers
            conf = _conflicts(existing.get("id"), email, phone, whatsapp)
            if conf:
                if dedupe_strategy == "skip_duplicates":
                    skipped += 1
                    continue
                errors.append({"row": rownum, "message": f"Uniqueness conflict on {conf[0]} with existing contact {conf[1]}."})
                continue

            if dedupe_strategy == "skip_duplicates":
                skipped += 1
                continue

            # update fields
            for k in ("email","phone_e164","whatsapp_e164","first_name","last_name"):
                if mapped.get(k) is not None:
                    existing[k] = mapped.get(k)
            # merge attributes
            if isinstance(existing.get("attributes"), dict) and isinstance(mapped.get("attributes"), dict):
                existing["attributes"].update(mapped["attributes"])
            elif isinstance(mapped.get("attributes"), dict):
                existing["attributes"] = dict(mapped["attributes"])
            # add list ids
            if not isinstance(existing.get("list_ids"), list):
                existing["list_ids"] = []
            for lid in target_list_ids:
                if lid not in existing["list_ids"]:
                    existing["list_ids"].append(lid)
            existing["updated_by_principal_id"] = requested_by_principal_id
            existing["updated_at"] = _now()
            updated += 1
            continue

    job["summary"]["valid_rows"] = valid_rows
    job["summary"]["created_contacts"] = created
    job["summary"]["updated_contacts"] = updated
    job["summary"]["skipped_duplicates"] = skipped
    job["summary"]["errors"] = errors

    # Persist contacts and job
    _save("contacts.json", contacts)

    # Complete job
    job["status"] = "completed" if not errors else "completed"
    job["updated_at"] = _now()
    _save("contact_import_jobs.json", jobs)

    _log("OK", created=created, updated=updated, skipped=skipped, errors=len(errors))
    return {"job": job, "summary": job["summary"]}

def contact_with_list(workspace_id, created_by_principal_id, list_ids, email=None, phone_e164=None, whatsapp_e164=None, first_name=None, last_name=None, attributes=None, consent=None, source=None, external_ids=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0080000" if __import__("os").path.isdir("./environment_mix/0080000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "contact_with_list"

    wsp_pat = re.compile(r"^brv_wsp_[0-9A-Z]{18,}$")
    prn_pat = re.compile(r"^brv_prn_[0-9A-Z]{18,}$")

    allowed_source = {"api", "import", "ecommerce", "crm", "conversation", "unknown"}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        rnd = random.SystemRandom()
        return prefix + "".join(rnd.choice(alphabet) for _ in range(20))

    def _log(status_code, message=None, **meta):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _gen_id("brv_req_"),
            "endpoint": endpoint,
            "workspace_id": workspace_id,
            "principal_id": created_by_principal_id,
            "status": status_code,
            "message": message,
            "meta": meta or {},
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": _now_iso(),
        })
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(workspace_id, str) or not wsp_pat.match(workspace_id):
        _log("VALIDATION_ERROR", "Invalid workspace_id")
        return _err("VALIDATION_ERROR", "workspace_id must match expected format.")
    if not isinstance(created_by_principal_id, str) or not prn_pat.match(created_by_principal_id):
        _log("VALIDATION_ERROR", "Invalid created_by_principal_id")
        return _err("VALIDATION_ERROR", "created_by_principal_id must match expected format.")
    if not isinstance(list_ids, list):
        _log("VALIDATION_ERROR", "Invalid list_ids")
        return _err("VALIDATION_ERROR", "list_ids must be an array.")
    # normalize list ids to strings (tool schema says items are strings; audit shows ints may be sent)
    norm_list_ids = []
    for x in list_ids:
        if isinstance(x, (str, int)):
            s = str(x)
            if s.strip() == "":
                _log("VALIDATION_ERROR", "Empty list_id")
                return _err("VALIDATION_ERROR", "list_ids entries must be non-empty.")
            norm_list_ids.append(s)
        else:
            _log("VALIDATION_ERROR", "Invalid list_id type")
            return _err("VALIDATION_ERROR", "list_ids entries must be strings (or numbers convertible to strings).")
    if source is not None and source not in allowed_source:
        _log("VALIDATION_ERROR", "Invalid source")
        return _err("VALIDATION_ERROR", "source is invalid.")
    if attributes is not None and not isinstance(attributes, dict):
        _log("VALIDATION_ERROR", "Invalid attributes")
        return _err("VALIDATION_ERROR", "attributes must be an object.")
    if consent is not None and not isinstance(consent, dict):
        _log("VALIDATION_ERROR", "Invalid consent")
        return _err("VALIDATION_ERROR", "consent must be an object.")
    if external_ids is not None and not isinstance(external_ids, dict):
        _log("VALIDATION_ERROR", "Invalid external_ids")
        return _err("VALIDATION_ERROR", "external_ids must be an object.")

    if email is None and phone_e164 is None and whatsapp_e164 is None:
        _log("VALIDATION_ERROR", "No identifier")
        return _err("VALIDATION_ERROR", "At least one of email, phone_e164, or whatsapp_e164 must be provided.")

    # Load workspace
    wss = _load("workspaces.json")
    if isinstance(wss, dict) and "rows" in wss and isinstance(wss["rows"], list):
        wss = wss["rows"]
    if not isinstance(wss, list):
        wss = []
    ws = next((w for w in wss if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _log("NOT_FOUND", "Workspace not found")
        return _err("NOT_FOUND", "Workspace not found.")

    # Role/principal
    principals = _load("principals.json")
    if isinstance(principals, dict) and "rows" in principals and isinstance(principals["rows"], list):
        principals = principals["rows"]
    if not isinstance(principals, list):
        principals = []
    principal = next((p for p in principals if isinstance(p, dict) and p.get("id") == created_by_principal_id), None)
    if not principal:
        _log("NOT_FOUND", "Principal not found")
        return _err("NOT_FOUND", "Principal not found.")
    if principal.get("status") != "active":
        _log("UNAUTHORIZED", "Principal not active")
        return _err("UNAUTHORIZED", "Principal is not active.")
    if principal.get("role") == "read_only":
        _log("UNAUTHORIZED", "read_only cannot mutate")
        return _err("UNAUTHORIZED", "Principal role read_only cannot create/update contacts.")

    # observable dynamics: api_calls increment on workspace
    if not isinstance(ws.get("usage_today"), dict):
        ws["usage_today"] = {}
    for k in ("emails_sent", "sms_sent", "whatsapp_sent", "events_ingested", "api_calls"):
        if not isinstance(ws["usage_today"].get(k), int) or ws["usage_today"][k] < 0:
            ws["usage_today"][k] = 0
    ws["usage_today"]["api_calls"] += 1
    ws["updated_at"] = _now_iso()
    _save("workspaces.json", wss)

    # Validate list ids atomically: datastore has no lists collection; accept any non-empty list id.
    # If future "lists.json" exists, enforce membership.
    lists = _load("lists.json")
    valid_set = None
    if isinstance(lists, dict) and "rows" in lists and isinstance(lists["rows"], list):
        lists = lists["rows"]
    if isinstance(lists, list) and len(lists) > 0 and all(isinstance(r, dict) and ("id" in r) for r in lists):
        valid_set = {str(r.get("id")) for r in lists}
    if valid_set is not None:
        bad = [lid for lid in norm_list_ids if lid not in valid_set]
        if bad:
            _log("VALIDATION_ERROR", "Invalid list_ids", invalid_list_ids=bad)
            return _err("VALIDATION_ERROR", "One or more list_ids are invalid.", invalid_list_ids=bad)

    contacts = _load("contacts.json")
    if isinstance(contacts, dict) and "rows" in contacts and isinstance(contacts["rows"], list):
        contacts = contacts["rows"]
    if not isinstance(contacts, list):
        contacts = []

    # Find existing contact by identifiers in workspace
    def _matches(c):
        if c.get("workspace_id") != workspace_id:
            return False
        if email is not None and c.get("email") == email:
            return True
        if phone_e164 is not None and c.get("phone_e164") == phone_e164:
            return True
        if whatsapp_e164 is not None and c.get("whatsapp_e164") == whatsapp_e164:
            return True
        return False

    existing = next((c for c in contacts if isinstance(c, dict) and _matches(c)), None)

    # Uniqueness checks for any identifiers being set: within workspace
    def _conflict(field, value, ignore_id=None):
        if value is None:
            return None
        for c in contacts:
            if not isinstance(c, dict):
                continue
            if c.get("workspace_id") != workspace_id:
                continue
            if ignore_id is not None and c.get("id") == ignore_id:
                continue
            if c.get(field) == value:
                return c.get("id")
        return None

    ignore_id = existing.get("id") if existing else None
    for field, value in (("email", email), ("phone_e164", phone_e164), ("whatsapp_e164", whatsapp_e164)):
        cid = _conflict(field, value, ignore_id=ignore_id)
        if cid:
            _log("CONFLICT", "Uniqueness conflict", field=field, value=value, conflict_contact_id=cid)
            return _err("CONFLICT", f"{field} must be unique within the workspace.", field=field, conflict_contact_id=cid)

    now = _now_iso()
    if existing:
        # update existing contact + add list_ids atomically
        new_list_ids = existing.get("list_ids") if isinstance(existing.get("list_ids"), list) else []
        new_set = set(str(x) for x in new_list_ids)
        for lid in norm_list_ids:
            new_set.add(str(lid))
        existing["list_ids"] = list(new_set)
        # update fields if provided
        if email is not None:
            existing["email"] = email
        if phone_e164 is not None:
            existing["phone_e164"] = phone_e164
        if whatsapp_e164 is not None:
            existing["whatsapp_e164"] = whatsapp_e164
        if first_name is not None:
            existing["first_name"] = first_name
        if last_name is not None:
            existing["last_name"] = last_name
        if attributes is not None:
            existing["attributes"] = attributes
        if consent is not None:
            existing["consent"] = consent
        if source is not None:
            existing["source"] = source
        if external_ids is not None:
            existing["external_ids"] = external_ids
        existing["updated_by_principal_id"] = created_by_principal_id
        existing["updated_at"] = now
        _save("contacts.json", contacts)
        _log("OK", None, contact_id=existing["id"], updated=True)
        return {"contact": existing, "created": False, "list_ids": existing.get("list_ids", [])}

    # create new contact
    row = {
        "id": _gen_id("brv_cnt_"),
        "workspace_id": workspace_id,
        "email": email,
        "phone_e164": phone_e164,
        "whatsapp_e164": whatsapp_e164,
        "first_name": first_name,
        "last_name": last_name,
        "attributes": attributes or {},
        "list_ids": list(dict.fromkeys([str(x) for x in norm_list_ids])),
        "consent": consent or {},
        "status": "active",
        "source": source or "api",
        "external_ids": external_ids or {},
        "created_by_principal_id": created_by_principal_id,
        "updated_by_principal_id": created_by_principal_id,
        "created_at": now,
        "updated_at": now,
    }
    contacts.append(row)
    _save("contacts.json", contacts)
    _log("OK", None, contact_id=row["id"], created=True)
    return {"contact": row, "created": True, "list_ids": row["list_ids"]}

def email_with_tracking(workspace_id, created_by_principal_id, subject, name=None, from_email=None, from_name=None, to_contact_id=None, to_address=None, template_id=None, payload=None, scheduled_for=None, tracking=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0080000" if __import__("os").path.isdir("./environment_mix/0080000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "email_with_tracking"

    wsp_pat = re.compile(r"^brv_wsp_[0-9A-Z]{18,}$")
    prn_pat = re.compile(r"^brv_prn_[0-9A-Z]{18,}$")
    cnt_pat = re.compile(r"^brv_cnt_[0-9A-Z]{18,}$")
    msg_pat = re.compile(r"^brv_msg_[0-9A-Z]{18,}$")

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0)

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        rnd = random.SystemRandom()
        return prefix + "".join(rnd.choice(alphabet) for _ in range(20))

    def _ensure_usage_today(ws):
        if not isinstance(ws.get("usage_today"), dict):
            ws["usage_today"] = {}
        ut = ws["usage_today"]
        for k in ("emails_sent", "sms_sent", "whatsapp_sent", "events_ingested", "api_calls"):
            if not isinstance(ut.get(k), int) or ut.get(k) is None or ut[k] < 0:
                ut[k] = 0

    def _load_rows(filename):
        d = _load(filename)
        if isinstance(d, dict) and isinstance(d.get("rows"), list):
            return d["rows"], d
        if isinstance(d, list):
            return d, None
        return [], None

    def _save_rows(filename, rows, wrapper):
        if wrapper is None:
            _save(filename, rows)
        else:
            wrapper["rows"] = rows
            _save(filename, wrapper)

    def _log_call(ws_row, principal_id, status_code, error=None, extra=None):
        logs, logs_wrapper = _load_rows("request_logs.json")
        _ensure_usage_today(ws_row)
        ws_row["usage_today"]["api_calls"] += 1
        entry = {
            "id": _gen_id("brv_req_"),
            "ts": _now_iso(),
            "endpoint": endpoint,
            "workspace_id": ws_row.get("id"),
            "principal_id": principal_id,
            "status": int(status_code),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if extra:
            entry["meta"] = extra
        if error:
            entry["error"] = error
        logs.append(entry)
        _save_rows("request_logs.json", logs, logs_wrapper)

    # validate
    if not isinstance(workspace_id, str) or not wsp_pat.match(workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id format.")
    if not isinstance(created_by_principal_id, str) or not prn_pat.match(created_by_principal_id):
        return _err("VALIDATION_ERROR", "Invalid created_by_principal_id format.")
    if not isinstance(subject, str) or not subject.strip():
        return _err("VALIDATION_ERROR", "subject is required.")
    if to_contact_id is not None and (not isinstance(to_contact_id, str) or not cnt_pat.match(to_contact_id)):
        return _err("VALIDATION_ERROR", "Invalid to_contact_id format.")
    if template_id is not None and (not isinstance(template_id, str) or not msg_pat.match(template_id)):
        return _err("VALIDATION_ERROR", "Invalid template_id format.")
    if payload is not None and not isinstance(payload, dict):
        return _err("VALIDATION_ERROR", "payload must be an object.")
    if tracking is not None and not isinstance(tracking, dict):
        return _err("VALIDATION_ERROR", "tracking must be an object.")
    scheduled_dt = _parse_dt(scheduled_for) if scheduled_for is not None else None
    if scheduled_for is not None and scheduled_dt is None:
        return _err("VALIDATION_ERROR", "scheduled_for must be ISO 8601.")

    # workspace + principal
    workspaces, workspaces_wrapper = _load_rows("workspaces.json")
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.")
    _ensure_usage_today(ws)

    principals, principals_wrapper = _load_rows("principals.json")
    principal = next((p for p in principals if isinstance(p, dict) and p.get("id") == created_by_principal_id and p.get("workspace_id") == workspace_id), None)
    if not principal:
        _log_call(ws, created_by_principal_id, 401, error={"code": "UNAUTHORIZED", "message": "Principal not found in workspace."})
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)
        return _err("UNAUTHORIZED", "Principal not found in workspace.")
    if principal.get("status") != "active":
        _log_call(ws, created_by_principal_id, 401, error={"code": "UNAUTHORIZED", "message": "Principal is not active."})
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)
        return _err("UNAUTHORIZED", "Principal is not active.")
    if principal.get("role") in {"read_only", "analyst"}:
        # analyst cannot send
        _log_call(ws, created_by_principal_id, 401, error={"code": "UNAUTHORIZED", "message": "Principal is not permitted to send email."})
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)
        return _err("UNAUTHORIZED", "Principal is not permitted to send email.")
    if ws.get("status") != "active":
        _log_call(ws, created_by_principal_id, 409, error={"code": "CONFLICT", "message": "Workspace must be active for sending."})
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)
        return _err("CONFLICT", "Workspace must be active for sending.")

    contacts, contacts_wrapper = _load_rows("contacts.json")
    messaging, messaging_wrapper = _load_rows("messaging_objects.json")

    def _find_contact(cid):
        return next((c for c in contacts if isinstance(c, dict) and c.get("id") == cid and c.get("workspace_id") == workspace_id), None)

    def _find_msg(mid):
        return next((m for m in messaging if isinstance(m, dict) and m.get("id") == mid and m.get("workspace_id") == workspace_id), None)

    # recipient
    if to_contact_id is None and (to_address is None or not isinstance(to_address, str) or not to_address.strip()):
        _log_call(ws, created_by_principal_id, 400, error={"code": "VALIDATION_ERROR", "message": "Either to_contact_id or to_address is required."})
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)
        return _err("VALIDATION_ERROR", "Either to_contact_id or to_address is required.")

    contact = None
    resolved_to = None
    if to_contact_id is not None:
        contact = _find_contact(to_contact_id)
        if not contact:
            _log_call(ws, created_by_principal_id, 404, error={"code": "NOT_FOUND", "message": "Recipient contact not found in workspace."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("NOT_FOUND", "Recipient contact not found in workspace.")
        if isinstance(contact.get("email"), str) and contact.get("email").strip():
            resolved_to = contact.get("email").strip()
        elif isinstance(to_address, str) and to_address.strip():
            resolved_to = to_address.strip()
        else:
            _log_call(ws, created_by_principal_id, 400, error={"code": "VALIDATION_ERROR", "message": "Contact has no email; provide to_address."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("VALIDATION_ERROR", "Contact has no email; provide to_address.")
    else:
        resolved_to = to_address.strip()

    # template if present
    if template_id is not None:
        tpl = _find_msg(template_id)
        if not tpl:
            _log_call(ws, created_by_principal_id, 404, error={"code": "NOT_FOUND", "message": "template_id not found in workspace."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("NOT_FOUND", "template_id not found in workspace.")
        if tpl.get("object_type") != "email_template":
            _log_call(ws, created_by_principal_id, 400, error={"code": "VALIDATION_ERROR", "message": "template_id must reference an email_template messaging object."})
            _save_rows("workspaces.json", workspaces, workspaces_wrapper)
            return _err("VALIDATION_ERROR", "template_id must reference an email_template messaging object.")

    # quota
    if not isinstance(ws.get("quota_daily_emails"), int) or ws.get("quota_daily_emails") < 0:
        ws["quota_daily_emails"] = 0
    if ws["usage_today"]["emails_sent"] >= ws["quota_daily_emails"]:
        _log_call(ws, created_by_principal_id, 429, error={"code": "QUOTA_EXCEEDED", "message": "Daily email quota exceeded."})
        _save_rows("workspaces.json", workspaces, workspaces_wrapper)
        return _err("QUOTA_EXCEEDED", "Daily email quota exceeded.", quota=ws["quota_daily_emails"], used=ws["usage_today"]["emails_sent"])

    # create send row, ensure cannot skip sending -> sent/failed
    now = _now_iso()
    send_id = _gen_id("brv_msg_")
    send_row = {
        "id": send_id,
        "workspace_id": workspace_id,
        "object_type": "email_transactional_send",
        "status": "sending",
        "name": name,
        "channel": "email",
        "subject": subject,
        "from_email": from_email or ws.get("default_sender_email"),
        "from_name": from_name or ws.get("default_sender_name"),
        "to_contact_id": to_contact_id,
        "to_address": resolved_to,
        "template_id": template_id,
        "payload": payload or {},
        "scheduled_for": scheduled_dt.isoformat().replace("+00:00", "Z") if scheduled_dt else None,
        "send_provider_message_id": None,
        "tracking": tracking or {},
        "event_type": None,
        "event_at": None,
        "webhook_url": None,
        "webhook_secret": None,
        "enabled_events": None,
        "retry_policy": None,
        "conversation_thread_id": None,
        "inbound_message_id": None,
        "attachments": [],
        "crm_link": {},
        "ecommerce_link": {},
        "created_by_principal_id": created_by_principal_id,
        "created_at": now,
        "updated_at": now,
    }
    if scheduled_dt is not None:
        send_row["status"] = "scheduled"
    messaging.append(send_row)

    # immediate transition only when not scheduled; must go through sending (row created with sending)
    if scheduled_dt is None:
        will_fail = bool((payload or {}).get("force_fail")) or bool((payload or {}).get("simulate_fail"))
        if will_fail:
            send_row["status"] = "failed"
        else:
            send_row["status"] = "sent"
            ws["usage_today"]["emails_sent"] += 1
        send_row["send_provider_message_id"] = "brevo-msg-" + _gen_id("")[0:12].lower()
        send_row["updated_at"] = _now_iso()

    _save_rows("messaging_objects.json", messaging, messaging_wrapper)
    _save_rows("workspaces.json", workspaces, workspaces_wrapper)

    # return tracking fields derived from messaging_objects.tracking plus provider message id
    tracking_out = {}
    if isinstance(send_row.get("tracking"), dict):
        tracking_out.update(send_row["tracking"])
    tracking_out["send_provider_message_id"] = send_row.get("send_provider_message_id")

    _log_call(ws, created_by_principal_id, 200, extra={"action": "send", "message_id": send_id, "status": send_row["status"]})
    _save_rows("workspaces.json", workspaces, workspaces_wrapper)
    return {"message": send_row, "tracking": tracking_out}

def workspaces(action, workspace_id=None, brevo_account_id=None, name=None, status=None, default_sender_email=None, default_sender_name=None, verified_domains=None, folders=None, timezone=None, quota_daily_emails=None, quota_daily_sms=None, quota_daily_whatsapp=None, quota_daily_events=None, brevo_api_key=None, query=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, re, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0080000" if __import__("os").path.isdir("./environment_mix/0080000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "workspaces"
    credential_used = None

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_cursor(c):
        if not c:
            return 0
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict) and isinstance(obj.get("offset"), int) and obj["offset"] >= 0:
                return obj["offset"]
        except Exception:
            return None
        return None

    def _make_cursor(offset):
        payload = json.dumps({"offset": offset}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    def _record(status_code, outcome):
        # status_code: "ok" | error code
        logs = _load("request_logs.json")
        ts = _now()
        latency_ms = int((time.time() - t0) * 1000)
        logs.append({
            "id": f"brv_req_{base64.urlsafe_b64encode(os.urandom(12)).decode('utf-8').rstrip('=')}".upper(),
            "endpoint": endpoint,
            "action": action,
            "workspace_id": workspace_id,
            "credential_used": credential_used,
            "status": status_code,
            "latency_ms": latency_ms,
            "timestamp": ts
        })
        _save("request_logs.json", logs)
        return outcome

    def _today_key():
        return datetime.datetime.now(datetime.timezone.utc).date().isoformat()

    def _maybe_reset_usage(ws):
        # Reset usage_today if day changed (store may not have a date field; embed it if missing).
        ut = ws.get("usage_today")
        if not isinstance(ut, dict):
            ws["usage_today"] = {"date": _today_key(), "emails_sent": 0, "sms_sent": 0, "whatsapp_sent": 0, "events_ingested": 0, "api_calls": 0}
            return
        d = ut.get("date")
        if d != _today_key():
            ws["usage_today"] = {"date": _today_key(), "emails_sent": 0, "sms_sent": 0, "whatsapp_sent": 0, "events_ingested": 0, "api_calls": 0}
            return
        # ensure counters exist
        for k in ("emails_sent", "sms_sent", "whatsapp_sent", "events_ingested", "api_calls"):
            if not isinstance(ut.get(k), int) or ut.get(k) < 0:
                ut[k] = 0

    def _inc_api_calls(ws):
        _maybe_reset_usage(ws)
        ws["usage_today"]["api_calls"] = int(ws["usage_today"].get("api_calls", 0)) + 1

    def _find_any_workspace_for_auth():
        # Ambient auth: if any workspace exists, caller is considered authorized to use it unless request references a specific one that doesn't exist.
        wss = _load("workspaces.json")
        for ws in wss:
            if isinstance(ws, dict) and ws.get("status") in ("active", "suspended", "closed"):
                return ws
        return None

    # Validate action
    if action not in ("list", "get", "create", "update"):
        return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid action.", field="action"))

    # Load data
    wss = _load("workspaces.json")

    # Ambient auth workspace selection for usage/api call accounting: best-effort.
    ws_for_accounting = None
    if workspace_id:
        ws_for_accounting = next((w for w in wss if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws_for_accounting:
        ws_for_accounting = _find_any_workspace_for_auth()
    if not wss and action in ("list", "create"):
        # allowed: empty store
        ws_for_accounting = None

    # Basic rate limiting (observable dynamics): 600 calls/min per datastore (global)
    logs = _load("request_logs.json")
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    one_min_ago = (now_dt - datetime.timedelta(seconds=60)).isoformat()
    recent = 0
    for r in logs[-5000:]:
        if isinstance(r, dict) and r.get("timestamp") and r["timestamp"] >= one_min_ago:
            recent += 1
    if recent >= 600:
        return _record("RATE_LIMIT", _err("RATE_LIMIT", "Rate limit exceeded."))

    # Helper validations
    wsp_pat = re.compile(r"^brv_wsp_[0-9A-Z]{18,}$")
    if workspace_id is not None and (not isinstance(workspace_id, str) or not wsp_pat.match(workspace_id)):
        return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid workspace_id format.", field="workspace_id"))

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid limit.", field="limit"))

    if sort_by is None:
        sort_by = "created_at"
    if sort_by not in ("created_at", "updated_at", "name", "status"):
        return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid sort_by.", field="sort_by"))
    if sort_order is None:
        sort_order = "desc"
    if sort_order not in ("asc", "desc"):
        return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid sort_order.", field="sort_order"))

    if action in ("get", "update") and not workspace_id:
        return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "workspace_id is required for this action.", field="workspace_id"))

    if status is not None and status not in ("active", "suspended", "closed"):
        return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid status.", field="status"))

    # Perform
    if action == "list":
        offset = _parse_cursor(cursor)
        if offset is None:
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor"))

        rows = [w for w in wss if isinstance(w, dict)]
        # filters
        if brevo_account_id is not None:
            if not isinstance(brevo_account_id, str):
                return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "brevo_account_id must be a string.", field="brevo_account_id"))
            rows = [w for w in rows if w.get("brevo_account_id") == brevo_account_id]
        if name is not None:
            if not isinstance(name, str):
                return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "name must be a string.", field="name"))
            rows = [w for w in rows if w.get("name") == name]
        if status is not None:
            rows = [w for w in rows if w.get("status") == status]
        if query is not None:
            if not isinstance(query, str):
                return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "query must be a string.", field="query"))
            q = query.lower().strip()
            if q:
                rows = [w for w in rows if (str(w.get("name") or "").lower().find(q) >= 0) or (str(w.get("brevo_account_id") or "").lower().find(q) >= 0)]

        # sort
        def _key(w):
            v = w.get(sort_by)
            return "" if v is None else v
        rows.sort(key=_key, reverse=(sort_order == "desc"))

        total = len(rows)
        page = rows[offset: offset + limit]
        has_more = offset + limit < total
        next_cursor = _make_cursor(offset + limit) if has_more else None

        # increment api_calls for visible service dynamics: pick an arbitrary workspace for accounting if present
        if ws_for_accounting:
            _maybe_reset_usage(ws_for_accounting)
            _inc_api_calls(ws_for_accounting)
            ws_for_accounting["updated_at"] = _now()
            # persist updated usage
            # update in list by id
            for i, w in enumerate(wss):
                if isinstance(w, dict) and w.get("id") == ws_for_accounting.get("id"):
                    wss[i] = ws_for_accounting
                    _save("workspaces.json", wss)
                    break

        return _record("ok", {"data": page, "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor}})

    if action == "get":
        ws = next((w for w in wss if isinstance(w, dict) and w.get("id") == workspace_id), None)
        if not ws:
            return _record("NOT_FOUND", _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id))

        _maybe_reset_usage(ws)
        _inc_api_calls(ws)
        ws["updated_at"] = _now()
        for i, w in enumerate(wss):
            if isinstance(w, dict) and w.get("id") == ws.get("id"):
                wss[i] = ws
                _save("workspaces.json", wss)
                break

        return _record("ok", {"data": ws})

    if action == "create":
        # validate required fields
        if name is None or not isinstance(name, str) or not name.strip():
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "name is required.", field="name"))
        if brevo_account_id is not None and not isinstance(brevo_account_id, str):
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "brevo_account_id must be a string.", field="brevo_account_id"))
        if default_sender_email is not None and not isinstance(default_sender_email, str):
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "default_sender_email must be a string.", field="default_sender_email"))
        if default_sender_name is not None and not isinstance(default_sender_name, str):
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "default_sender_name must be a string.", field="default_sender_name"))
        if verified_domains is not None and (not isinstance(verified_domains, list) or any(not isinstance(x, str) for x in verified_domains)):
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "verified_domains must be an array of strings.", field="verified_domains"))
        if folders is not None and (not isinstance(folders, list) or any(not isinstance(x, str) for x in folders)):
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "folders must be an array of strings.", field="folders"))
        if timezone is not None and not isinstance(timezone, str):
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "timezone must be a string.", field="timezone"))

        # quotas defaults
        def _qv(v, field):
            if v is None:
                return 0
            if not isinstance(v, int) or v < 0:
                raise ValueError(field)
            return v

        try:
            q_em = _qv(quota_daily_emails, "quota_daily_emails")
            q_sms = _qv(quota_daily_sms, "quota_daily_sms")
            q_wa = _qv(quota_daily_whatsapp, "quota_daily_whatsapp")
            q_ev = _qv(quota_daily_events, "quota_daily_events")
        except ValueError as e:
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Quota must be an integer >= 0.", field=str(e)))

        # unique(name)
        for w in wss:
            if isinstance(w, dict) and w.get("name") == name:
                return _record("CONFLICT", _err("CONFLICT", "Workspace name must be unique.", field="name"))

        st = status or "active"
        if st not in ("active", "suspended", "closed"):
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid status.", field="status"))

        # fingerprint
        fp = None
        if brevo_api_key is not None:
            if not isinstance(brevo_api_key, str) or not brevo_api_key.strip():
                return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "brevo_api_key must be a non-empty string.", field="brevo_api_key"))
            fp = hashlib.sha256(brevo_api_key.encode("utf-8")).hexdigest()[:16]

        new_id = "brv_wsp_" + base64.urlsafe_b64encode(os.urandom(14)).decode("utf-8").rstrip("=").upper()
        now = _now()
        ws = {
            "id": new_id,
            "brevo_account_id": brevo_account_id,
            "name": name,
            "status": st,
            "default_sender_email": default_sender_email,
            "default_sender_name": default_sender_name,
            "verified_domains": verified_domains if verified_domains is not None else [],
            "folders": folders if folders is not None else [],
            "quota_daily_emails": q_em,
            "quota_daily_sms": q_sms,
            "quota_daily_whatsapp": q_wa,
            "quota_daily_events": q_ev,
            "usage_today": {"date": _today_key(), "emails_sent": 0, "sms_sent": 0, "whatsapp_sent": 0, "events_ingested": 0, "api_calls": 0},
            "brevo_api_key_fingerprint": fp,
            "timezone": timezone,
            "created_at": now,
            "updated_at": now,
        }
        # api call count includes this call
        ws["usage_today"]["api_calls"] = 1

        wss.append(ws)
        _save("workspaces.json", wss)
        return _record("ok", {"data": ws})

    if action == "update":
        ws = next((w for w in wss if isinstance(w, dict) and w.get("id") == workspace_id), None)
        if not ws:
            return _record("NOT_FOUND", _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id))

        _maybe_reset_usage(ws)

        # enforce lifecycle transitions
        if status is not None and status != ws.get("status"):
            transitions = {
                "active": ["suspended", "closed"],
                "suspended": ["active", "closed"],
                "closed": []
            }
            cur = ws.get("status")
            if cur not in transitions or status not in transitions[cur]:
                return _record("INVALID_TRANSITION", _err("INVALID_TRANSITION", "Illegal status transition.", from_status=cur, to_status=status))

        # sender/domain/folders changes only when current status is active (account tool rule)
        mutable_requires_active = any(v is not None for v in (default_sender_email, default_sender_name, verified_domains, folders))
        if mutable_requires_active and ws.get("status") != "active":
            return _record("UNAUTHORIZED", _err("UNAUTHORIZED", "Sender/domain/folders changes allowed only when workspace is active."))

        # validate types
        if name is not None:
            if not isinstance(name, str) or not name.strip():
                return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid name.", field="name"))
            # unique(name) excluding self
            for w in wss:
                if isinstance(w, dict) and w.get("id") != ws.get("id") and w.get("name") == name:
                    return _record("CONFLICT", _err("CONFLICT", "Workspace name must be unique.", field="name"))
        if brevo_account_id is not None and not isinstance(brevo_account_id, str):
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "brevo_account_id must be a string.", field="brevo_account_id"))
        if default_sender_email is not None and not isinstance(default_sender_email, str):
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "default_sender_email must be a string.", field="default_sender_email"))
        if default_sender_name is not None and not isinstance(default_sender_name, str):
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "default_sender_name must be a string.", field="default_sender_name"))
        if verified_domains is not None and (not isinstance(verified_domains, list) or any(not isinstance(x, str) for x in verified_domains)):
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "verified_domains must be an array of strings.", field="verified_domains"))
        if folders is not None and (not isinstance(folders, list) or any(not isinstance(x, str) for x in folders)):
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "folders must be an array of strings.", field="folders"))
        if timezone is not None and not isinstance(timezone, str):
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "timezone must be a string.", field="timezone"))

        # quotas cannot reduce below usage
        usage = ws.get("usage_today") if isinstance(ws.get("usage_today"), dict) else {}
        def _enforce_quota(field, newv, usage_field):
            if newv is None:
                return
            if not isinstance(newv, int) or newv < 0:
                raise ValueError(field)
            used = int(usage.get(usage_field, 0) or 0)
            if newv < used:
                raise RuntimeError((field, used))
        try:
            _enforce_quota("quota_daily_emails", quota_daily_emails, "emails_sent")
            _enforce_quota("quota_daily_sms", quota_daily_sms, "sms_sent")
            _enforce_quota("quota_daily_whatsapp", quota_daily_whatsapp, "whatsapp_sent")
            _enforce_quota("quota_daily_events", quota_daily_events, "events_ingested")
        except ValueError as e:
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Quota must be an integer >= 0.", field=str(e)))
        except RuntimeError as e:
            field, used = e.args[0]
            return _record("CONFLICT", _err("CONFLICT", "Quota cannot be reduced below current usage.", field=field, usage_today=used))

        # apply patches
        changed = False
        for k, v in (
            ("brevo_account_id", brevo_account_id),
            ("name", name),
            ("default_sender_email", default_sender_email),
            ("default_sender_name", default_sender_name),
            ("verified_domains", verified_domains),
            ("folders", folders),
            ("timezone", timezone),
            ("quota_daily_emails", quota_daily_emails),
            ("quota_daily_sms", quota_daily_sms),
            ("quota_daily_whatsapp", quota_daily_whatsapp),
            ("quota_daily_events", quota_daily_events),
        ):
            if v is not None and ws.get(k) != v:
                ws[k] = v
                changed = True

        if status is not None and ws.get("status") != status:
            ws["status"] = status
            changed = True

        if brevo_api_key is not None:
            if not isinstance(brevo_api_key, str) or not brevo_api_key.strip():
                return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "brevo_api_key must be a non-empty string.", field="brevo_api_key"))
            fp = hashlib.sha256(brevo_api_key.encode("utf-8")).hexdigest()[:16]
            if ws.get("brevo_api_key_fingerprint") != fp:
                ws["brevo_api_key_fingerprint"] = fp
                changed = True

        _inc_api_calls(ws)
        ws["updated_at"] = _now()

        if not changed:
            # still an effect due to api_calls increment; consider that as effect already persisted
            pass

        # persist
        for i, w in enumerate(wss):
            if isinstance(w, dict) and w.get("id") == ws.get("id"):
                wss[i] = ws
                _save("workspaces.json", wss)
                break

        return _record("ok", {"data": ws})

    return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Unsupported action."))

def principals(action, workspace_id, principal_id=None, type=None, email=None, display_name=None, role=None, status=None, query=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0080000" if __import__("os").path.isdir("./environment_mix/0080000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "principals"
    credential_used = None

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _today_key():
        return datetime.datetime.now(datetime.timezone.utc).date().isoformat()

    def _parse_cursor(c):
        if not c:
            return 0
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict) and isinstance(obj.get("offset"), int) and obj["offset"] >= 0:
                return obj["offset"]
        except Exception:
            return None
        return None

    def _make_cursor(offset):
        payload = json.dumps({"offset": offset}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    def _record(status_code, outcome):
        logs = _load("request_logs.json")
        ts = _now()
        latency_ms = int((time.time() - t0) * 1000)
        logs.append({
            "id": f"brv_req_{base64.urlsafe_b64encode(os.urandom(12)).decode('utf-8').rstrip('=')}".upper(),
            "endpoint": endpoint,
            "action": action,
            "workspace_id": workspace_id,
            "credential_used": credential_used,
            "status": status_code,
            "latency_ms": latency_ms,
            "timestamp": ts
        })
        _save("request_logs.json", logs)
        return outcome

    # global rate limit
    logs = _load("request_logs.json")
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    one_min_ago = (now_dt - datetime.timedelta(seconds=60)).isoformat()
    recent = 0
    for r in logs[-5000:]:
        if isinstance(r, dict) and r.get("timestamp") and r["timestamp"] >= one_min_ago:
            recent += 1
    if recent >= 600:
        return _record("RATE_LIMIT", _err("RATE_LIMIT", "Rate limit exceeded."))

    wsp_pat = re.compile(r"^brv_wsp_[0-9A-Z]{18,}$")
    prn_pat = re.compile(r"^brv_prn_[0-9A-Z]{18,}$")
    if not isinstance(workspace_id, str) or not wsp_pat.match(workspace_id):
        return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid workspace_id format.", field="workspace_id"))
    if principal_id is not None and (not isinstance(principal_id, str) or not prn_pat.match(principal_id)):
        return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid principal_id format.", field="principal_id"))

    if action not in ("list", "get", "create", "update"):
        return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid action.", field="action"))

    wss = _load("workspaces.json")
    ws = next((w for w in wss if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        return _record("NOT_FOUND", _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id))

    # account usage dynamics
    ut = ws.get("usage_today")
    if not isinstance(ut, dict) or ut.get("date") != _today_key():
        ws["usage_today"] = {"date": _today_key(), "emails_sent": 0, "sms_sent": 0, "whatsapp_sent": 0, "events_ingested": 0, "api_calls": 0}
    ws["usage_today"]["api_calls"] = int(ws["usage_today"].get("api_calls", 0)) + 1
    ws["updated_at"] = _now()
    for i, w in enumerate(wss):
        if isinstance(w, dict) and w.get("id") == workspace_id:
            wss[i] = ws
            _save("workspaces.json", wss)
            break

    prs = _load("principals.json")

    # normalize type enum mismatch: tool says service_account, schema says service
    def _norm_type(t):
        if t == "service_account":
            return "service"
        return t

    if type is not None:
        if type not in ("user", "service_account"):
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid type.", field="type"))
        type_norm = _norm_type(type)
    else:
        type_norm = None

    if role is not None and role not in ("owner", "admin", "support", "analyst", "read_only"):
        return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid role.", field="role"))
    if status is not None and status not in ("active", "invited", "disabled"):
        return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid status.", field="status"))

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid limit.", field="limit"))
    if sort_by is None:
        sort_by = "created_at"
    if sort_by not in ("created_at", "updated_at", "email", "last_login_at"):
        return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid sort_by.", field="sort_by"))
    if sort_order is None:
        sort_order = "desc"
    if sort_order not in ("asc", "desc"):
        return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid sort_order.", field="sort_order"))

    def _is_mutation():
        return action in ("create", "update")

    # Enterprise rule: read_only cannot mutate. With ambient auth and no actor param, allow if ANY active non-read_only exists in workspace.
    if _is_mutation():
        any_allowed = False
        for p in prs:
            if isinstance(p, dict) and p.get("workspace_id") == workspace_id and p.get("status") == "active" and p.get("role") in ("owner", "admin", "editor", "support", "analyst"):
                # schema includes editor; tool doesn't, but allow it
                if p.get("role") != "read_only":
                    any_allowed = True
                    break
        if not any_allowed and len([p for p in prs if isinstance(p, dict) and p.get("workspace_id") == workspace_id]) > 0:
            return _record("UNAUTHORIZED", _err("UNAUTHORIZED", "No active principal in workspace is authorized to mutate (read_only principals cannot mutate)."))

    if action == "list":
        offset = _parse_cursor(cursor)
        if offset is None:
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor"))

        rows = [p for p in prs if isinstance(p, dict) and p.get("workspace_id") == workspace_id]

        if type_norm is not None:
            rows = [p for p in rows if p.get("type") == type_norm]
        if email is not None:
            if not isinstance(email, str):
                return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "email must be a string.", field="email"))
            rows = [p for p in rows if (p.get("email") or "") == email]
        if display_name is not None:
            if not isinstance(display_name, str):
                return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "display_name must be a string.", field="display_name"))
            rows = [p for p in rows if (p.get("display_name") or "") == display_name]
        if role is not None:
            rows = [p for p in rows if p.get("role") == role]
        if status is not None:
            rows = [p for p in rows if p.get("status") == status]
        if query is not None:
            if not isinstance(query, str):
                return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "query must be a string.", field="query"))
            q = query.lower().strip()
            if q:
                rows = [p for p in rows if (str(p.get("email") or "").lower().find(q) >= 0) or (str(p.get("display_name") or "").lower().find(q) >= 0)]

        def _key(p):
            v = p.get(sort_by)
            return "" if v is None else v
        rows.sort(key=_key, reverse=(sort_order == "desc"))

        total = len(rows)
        page = rows[offset: offset + limit]
        has_more = offset + limit < total
        next_cursor = _make_cursor(offset + limit) if has_more else None

        return _record("ok", {"data": page, "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor}})

    if action == "get":
        if not principal_id:
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "principal_id is required for get.", field="principal_id"))
        p = next((x for x in prs if isinstance(x, dict) and x.get("id") == principal_id and x.get("workspace_id") == workspace_id), None)
        if not p:
            return _record("NOT_FOUND", _err("NOT_FOUND", "Principal not found.", principal_id=principal_id))
        return _record("ok", {"data": p})

    if action == "create":
        if display_name is None or not isinstance(display_name, str) or not display_name.strip():
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "display_name is required.", field="display_name"))
        if type_norm is None:
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "type is required.", field="type"))
        if type_norm == "user":
            if email is None or not isinstance(email, str) or not email.strip():
                return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "email is required when type='user'.", field="email"))
        else:
            # service
            if email is not None and (not isinstance(email, str)):
                return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "email must be a string.", field="email"))

        if role is None:
            role = "read_only"
        # schema allows editor too; tool doesn't. Accept tool roles only.
        if role not in ("owner", "admin", "support", "analyst", "read_only"):
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid role.", field="role"))

        st = status or "invited"
        if st not in ("active", "invited", "disabled"):
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid status.", field="status"))

        # unique(workspace_id, email)
        if email is not None:
            for p in prs:
                if isinstance(p, dict) and p.get("workspace_id") == workspace_id and (p.get("email") or "").lower() == email.lower():
                    return _record("CONFLICT", _err("CONFLICT", "email must be unique within workspace.", field="email"))

        pid = "brv_prn_" + base64.urlsafe_b64encode(os.urandom(14)).decode("utf-8").rstrip("=").upper()
        now = _now()
        row = {
            "id": pid,
            "workspace_id": workspace_id,
            "type": type_norm,
            "email": email if type_norm == "user" else (email if email else None),
            "display_name": display_name,
            "role": role,
            "status": st,
            "last_login_at": None,
            "created_at": now,
            "updated_at": now
        }
        prs.append(row)
        _save("principals.json", prs)
        return _record("ok", {"data": row})

    if action == "update":
        if not principal_id:
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "principal_id is required for update.", field="principal_id"))
        p = next((x for x in prs if isinstance(x, dict) and x.get("id") == principal_id and x.get("workspace_id") == workspace_id), None)
        if not p:
            return _record("NOT_FOUND", _err("NOT_FOUND", "Principal not found.", principal_id=principal_id))

        # lifecycle transitions
        if status is not None and status != p.get("status"):
            transitions = {
                "invited": ["active", "disabled"],
                "active": ["disabled"],
                "disabled": ["active"]
            }
            cur = p.get("status")
            if cur not in transitions or status not in transitions[cur]:
                return _record("INVALID_TRANSITION", _err("INVALID_TRANSITION", "Illegal status transition.", from_status=cur, to_status=status))

        if display_name is not None and (not isinstance(display_name, str) or not display_name.strip()):
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid display_name.", field="display_name"))

        if role is not None and role not in ("owner", "admin", "support", "analyst", "read_only"):
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid role.", field="role"))

        changed = False
        if display_name is not None and p.get("display_name") != display_name:
            p["display_name"] = display_name
            changed = True
        if role is not None and p.get("role") != role:
            p["role"] = role
            changed = True
        if status is not None and p.get("status") != status:
            p["status"] = status
            changed = True

        if not changed:
            return _record("CONFLICT", _err("CONFLICT", "No changes to apply."))

        p["updated_at"] = _now()
        for i, x in enumerate(prs):
            if isinstance(x, dict) and x.get("id") == principal_id:
                prs[i] = p
                _save("principals.json", prs)
                break
        return _record("ok", {"data": p})

    return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Unsupported action."))

def business_objects(action, workspace_id, business_object_id=None, object_type=None, status=None, name=None, description=None, amount=None, currency=None, properties=None, contact_id=None, external_id=None, parent_object_id=None, created_by_principal_id=None, query=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
