    def _record(status_code, outcome):
        logs = _load("request_logs.json")
        ts = _now()
        latency_ms = int((time.time() - t0) * 1000)
        logs.append({
            "id": f"brv_req_{base64.urlsafe_b64encode(os.urandom(12)).decode('utf-8').rstrip('=')}".upper(),
            "endpoint": endpoint,
            "action": action,
            "workspace_id": workspace_id,
            "credential_used": credential_used,
            "status": status_code,
            "latency_ms": latency_ms,
            "timestamp": ts
        })
        _save("request_logs.json", logs)
        return outcome

    # global rate limit
    logs = _load("request_logs.json")
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    one_min_ago = (now_dt - datetime.timedelta(seconds=60)).isoformat()
    recent = 0
    for r in logs[-5000:]:
        if isinstance(r, dict) and r.get("timestamp") and r["timestamp"] >= one_min_ago:
            recent += 1
    if recent >= 600:
        return _record("RATE_LIMIT", _err("RATE_LIMIT", "Rate limit exceeded."))

    wsp_pat = re.compile(r"^brv_wsp_[0-9A-Z]{18,}$")
    bus_pat = re.compile(r"^brv_bus_[0-9A-Z]{18,}$")
    cnt_pat = re.compile(r"^brv_cnt_[0-9A-Z]{18,}$")
    prn_pat = re.compile(r"^brv_prn_[0-9A-Z]{18,}$")
    if not isinstance(workspace_id, str) or not wsp_pat.match(workspace_id):
        return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid workspace_id format.", field="workspace_id"))
    if business_object_id is not None and (not isinstance(business_object_id, str) or not bus_pat.match(business_object_id)):
        return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid business_object_id format.", field="business_object_id"))
    if contact_id is not None and (not isinstance(contact_id, str) or not cnt_pat.match(contact_id)):
        return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid contact_id format.", field="contact_id"))
    if parent_object_id is not None and (not isinstance(parent_object_id, str) or not bus_pat.match(parent_object_id)):
        return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid parent_object_id format.", field="parent_object_id"))
    if created_by_principal_id is not None and (not isinstance(created_by_principal_id, str) or not prn_pat.match(created_by_principal_id)):
        return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid created_by_principal_id format.", field="created_by_principal_id"))

    if action not in ("list", "get", "create", "update"):
        return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid action.", field="action"))

    # load workspace + increment api_calls
    wss = _load("workspaces.json")
    ws = next((w for w in wss if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        return _record("NOT_FOUND", _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id))
    ut = ws.get("usage_today")
    if not isinstance(ut, dict) or ut.get("date") != _today_key():
        ws["usage_today"] = {"date": _today_key(), "emails_sent": 0, "sms_sent": 0, "whatsapp_sent": 0, "events_ingested": 0, "api_calls": 0}
    ws["usage_today"]["api_calls"] = int(ws["usage_today"].get("api_calls", 0)) + 1
    ws["updated_at"] = _now()
    for i, w in enumerate(wss):
        if isinstance(w, dict) and w.get("id") == workspace_id:
            wss[i] = ws
            _save("workspaces.json", wss)
            break

    bos = _load("business_objects.json")
    contacts = _load("contacts.json")
    principals_rows = _load("principals.json")

    schema_object_types = {"crm_company", "crm_deal", "crm_task", "crm_note", "ecom_product", "ecom_order", "ecom_coupon", "ecom_payment"}
    tool_object_types = {"crm_company", "crm_deal", "crm_ticket", "ecom_customer", "ecom_order", "ecom_product", "ecom_cart", "ecom_payment"}

    # Accept tool types but map unsupported to closest if possible; otherwise validation error.
    type_map = {
        "crm_ticket": "crm_task",
        "ecom_customer": None,
        "ecom_cart": None
    }

    if object_type is not None:
        if object_type not in tool_object_types:
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid object_type.", field="object_type"))
        mapped = type_map.get(object_type, object_type)
        if mapped is None or mapped not in schema_object_types:
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "object_type is not supported by this datastore schema.", field="object_type"))
        object_type_norm = mapped
    else:
        object_type_norm = None

    allowed_status = {"active", "inactive", "open", "won", "lost", "pending", "paid", "refunded", "cancelled", "archived", "deleted"}
    if status is not None and status not in allowed_status:
        return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid status.", field="status"))

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid limit.", field="limit"))
    if sort_by is None:
        sort_by = "created_at"
    if sort_by not in ("created_at", "updated_at", "name", "status", "amount"):
        return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid sort_by.", field="sort_by"))
    if sort_order is None:
        sort_order = "desc"
    if sort_order not in ("asc", "desc"):
        return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid sort_order.", field="sort_order"))

    # enterprise: read_only cannot mutate; with ambient auth, require any active non-read_only principal in workspace for mutations
    if action in ("create", "update"):
        any_allowed = False
        for p in principals_rows:
            if isinstance(p, dict) and p.get("workspace_id") == workspace_id and p.get("status") == "active" and p.get("role") != "read_only":
                any_allowed = True
                break
        if not any_allowed and len([p for p in principals_rows if isinstance(p, dict) and p.get("workspace_id") == workspace_id]) > 0:
            return _record("UNAUTHORIZED", _err("UNAUTHORIZED", "No active principal in workspace is authorized to mutate (read_only principals cannot mutate)."))

    def _contact_exists(cid):
        return any(isinstance(c, dict) and c.get("id") == cid and c.get("workspace_id") == workspace_id for c in contacts)

    def _principal_ok(pid):
        return any(isinstance(p, dict) and p.get("id") == pid and p.get("workspace_id") == workspace_id and p.get("status") == "active" for p in principals_rows)

    def _currency_ok(cur):
        if cur is None:
            return True
        return isinstance(cur, str) and re.match(r"^[A-Z]{3}$", cur) is not None

    transitions = {
        "active": ["inactive", "archived", "deleted"],
        "inactive": ["active", "archived", "deleted"],
        "open": ["won", "lost", "archived", "deleted"],
        "pending": ["paid", "cancelled", "refunded", "archived", "deleted"],
        "paid": ["refunded", "archived"],
        "refunded": ["archived"],
        "won": ["archived"],
        "lost": ["archived"],
        "cancelled": ["archived"],
        "archived": [],
        "deleted": []
    }

    def _creates_cycle(child_id, parent_id):
        # parent_object_id cannot create cycles
        seen = set([child_id])
        cur = parent_id
        by_id = {o.get("id"): o for o in bos if isinstance(o, dict)}
        while cur:
            if cur in seen:
                return True
            seen.add(cur)
            pobj = by_id.get(cur)
            if not pobj:
                break
            cur = pobj.get("parent_object_id")
        return False

    if action == "list":
        offset = _parse_cursor(cursor)
        if offset is None:
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor"))

        rows = [o for o in bos if isinstance(o, dict) and o.get("workspace_id") == workspace_id]
        if object_type_norm is not None:
            rows = [o for o in rows if o.get("object_type") == object_type_norm]
        if status is not None:
            rows = [o for o in rows if o.get("status") == status]
        if name is not None:
            if not isinstance(name, str):
                return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "name must be a string.", field="name"))
            rows = [o for o in rows if (o.get("name") or "") == name]
        if external_id is not None:
            if not isinstance(external_id, str):
                return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "external_id must be a string.", field="external_id"))
            rows = [o for o in rows if (o.get("external_id") or "") == external_id]
        if query is not None:
            if not isinstance(query, str):
                return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "query must be a string.", field="query"))
            q = query.lower().strip()
            if q:
                def _match(o):
                    return (str(o.get("name") or "").lower().find(q) >= 0) or (str(o.get("description") or "").lower().find(q) >= 0) or (str(o.get("external_id") or "").lower().find(q) >= 0)
                rows = [o for o in rows if _match(o)]

        def _key(o):
            v = o.get(sort_by)
            return -1 if (sort_by == "amount" and v is None) else ("" if v is None else v)
        rows.sort(key=_key, reverse=(sort_order == "desc"))

        total = len(rows)
        page = rows[offset: offset + limit]
        has_more = offset + limit < total
        next_cursor = _make_cursor(offset + limit) if has_more else None
        return _record("ok", {"data": page, "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor}})

    if action == "get":
        if not business_object_id:
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "business_object_id is required for get.", field="business_object_id"))
        o = next((x for x in bos if isinstance(x, dict) and x.get("id") == business_object_id and x.get("workspace_id") == workspace_id), None)
        if not o:
            return _record("NOT_FOUND", _err("NOT_FOUND", "Business object not found.", business_object_id=business_object_id))
        return _record("ok", {"data": o})

    if action == "create":
        if object_type_norm is None:
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "object_type is required.", field="object_type"))
        if properties is None:
            properties = {}
        if not isinstance(properties, dict):
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "properties must be an object.", field="properties"))
        if amount is not None:
            if not isinstance(amount, (int, float)) or amount < 0:
                return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "amount must be a number >= 0.", field="amount"))
        if not _currency_ok(currency):
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "currency must be 3 uppercase letters.", field="currency"))
        if contact_id is not None and not _contact_exists(contact_id):
            return _record("NOT_FOUND", _err("NOT_FOUND", "contact_id not found in workspace.", field="contact_id"))
        if created_by_principal_id is not None and not _principal_ok(created_by_principal_id):
            return _record("UNAUTHORIZED", _err("UNAUTHORIZED", "created_by_principal_id must reference an active principal in workspace.", field="created_by_principal_id"))

        # unique(workspace_id, object_type, external_id) where external_id not null
        if external_id is not None:
            if not isinstance(external_id, str) or not external_id.strip():
                return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "external_id must be a non-empty string when provided.", field="external_id"))
            for o in bos:
                if isinstance(o, dict) and o.get("workspace_id") == workspace_id and o.get("object_type") == object_type_norm and (o.get("external_id") or "") == external_id:
                    return _record("CONFLICT", _err("CONFLICT", "external_id must be unique per workspace+object_type.", field="external_id"))

        if parent_object_id is not None:
            parent = next((x for x in bos if isinstance(x, dict) and x.get("id") == parent_object_id and x.get("workspace_id") == workspace_id), None)
            if not parent:
                return _record("NOT_FOUND", _err("NOT_FOUND", "parent_object_id not found.", field="parent_object_id"))
            if object_type_norm == "ecom_payment" and parent.get("object_type") != "ecom_order":
                return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "ecom_payment parent_object_id must reference an ecom_order.", field="parent_object_id"))

        # default status
        st = status or ("open" if object_type_norm == "crm_deal" else "active")
        if st not in allowed_status:
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid status.", field="status"))

        bid = "brv_bus_" + base64.urlsafe_b64encode(os.urandom(14)).decode("utf-8").rstrip("=").upper()
        if parent_object_id is not None and _creates_cycle(bid, parent_object_id):
            return _record("CONFLICT", _err("CONFLICT", "parent_object_id would create a cycle.", field="parent_object_id"))

        now = _now()
        row = {
            "id": bid,
            "workspace_id": workspace_id,
            "object_type": object_type_norm,
            "status": st,
            "name": name,
            "description": description,
            "amount": float(amount) if isinstance(amount, (int, float)) else None,
            "currency": currency,
            "properties": properties,
            "contact_id": contact_id,
            "external_id": external_id,
            "parent_object_id": parent_object_id,
            "created_by_principal_id": created_by_principal_id,
            "created_at": now,
            "updated_at": now
        }
        bos.append(row)
        _save("business_objects.json", bos)
        return _record("ok", {"data": row})

    if action == "update":
        if not business_object_id:
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "business_object_id is required for update.", field="business_object_id"))
        o = next((x for x in bos if isinstance(x, dict) and x.get("id") == business_object_id and x.get("workspace_id") == workspace_id), None)
        if not o:
            return _record("NOT_FOUND", _err("NOT_FOUND", "Business object not found.", business_object_id=business_object_id))

        if amount is not None:
            if not isinstance(amount, (int, float)) or amount < 0:
                return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "amount must be a number >= 0.", field="amount"))
        if currency is not None and not _currency_ok(currency):
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "currency must be 3 uppercase letters.", field="currency"))
        if properties is not None and not isinstance(properties, dict):
            return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "properties must be an object.", field="properties"))
        if contact_id is not None and not _contact_exists(contact_id):
            return _record("NOT_FOUND", _err("NOT_FOUND", "contact_id not found in workspace.", field="contact_id"))

        # external_id uniqueness if changed/set
        if external_id is not None:
            if not isinstance(external_id, str) or not external_id.strip():
                return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "external_id must be a non-empty string when provided.", field="external_id"))
            for other in bos:
                if isinstance(other, dict) and other.get("id") != o.get("id") and other.get("workspace_id") == workspace_id and other.get("object_type") == o.get("object_type") and (other.get("external_id") or "") == external_id:
                    return _record("CONFLICT", _err("CONFLICT", "external_id must be unique per workspace+object_type.", field="external_id"))

        if parent_object_id is not None:
            parent = next((x for x in bos if isinstance(x, dict) and x.get("id") == parent_object_id and x.get("workspace_id") == workspace_id), None)
            if not parent:
                return _record("NOT_FOUND", _err("NOT_FOUND", "parent_object_id not found.", field="parent_object_id"))
            if o.get("object_type") == "ecom_payment" and parent.get("object_type") != "ecom_order":
                return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "ecom_payment parent_object_id must reference an ecom_order.", field="parent_object_id"))
            if _creates_cycle(o.get("id"), parent_object_id):
                return _record("CONFLICT", _err("CONFLICT", "parent_object_id would create a cycle.", field="parent_object_id"))

        # status transition
        if status is not None and status != o.get("status"):
            cur = o.get("status")
            if cur not in transitions or status not in transitions[cur]:
                return _record("INVALID_TRANSITION", _err("INVALID_TRANSITION", "Illegal status transition.", from_status=cur, to_status=status))

        changed = False
        for k, v in (
            ("name", name),
            ("description", description),
            ("amount", float(amount) if isinstance(amount, (int, float)) else None if amount is not None else None),
            ("currency", currency),
            ("properties", properties),
            ("contact_id", contact_id),
            ("external_id", external_id),
            ("parent_object_id", parent_object_id),
        ):
            if v is not None:
                # special handling for amount: allow setting to None? tool doesn't provide explicit null; treat None as "not provided"
                if k == "amount":
                    if amount is not None and o.get("amount") != v:
                        o["amount"] = v
                        changed = True
                else:
                    if o.get(k) != v:
                        o[k] = v
                        changed = True

        if status is not None and o.get("status") != status:
            o["status"] = status
            changed = True

        if not changed:
            return _record("CONFLICT", _err("CONFLICT", "No changes to apply."))

        o["updated_at"] = _now()
        for i, x in enumerate(bos):
            if isinstance(x, dict) and x.get("id") == business_object_id:
                bos[i] = o
                _save("business_objects.json", bos)
                break
        return _record("ok", {"data": o})

    return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Unsupported action."))

def whoami(workspace_id=None, include_workspaces=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0080000" if __import__("os").path.isdir("./environment_mix/0080000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "whoami"
    credential_used = None
    action = "get"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _today_key():
        return datetime.datetime.now(datetime.timezone.utc).date().isoformat()

    def _parse_cursor(c):
        if not c:
            return 0
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict) and isinstance(obj.get("offset"), int) and obj["offset"] >= 0:
                return obj["offset"]
        except Exception:
            return None
        return None

    def _make_cursor(offset):
        payload = json.dumps({"offset": offset}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    def _record(status_code, outcome):
        logs = _load("request_logs.json")
        ts = _now()
        latency_ms = int((time.time() - t0) * 1000)
        logs.append({
            "id": f"brv_req_{base64.urlsafe_b64encode(os.urandom(12)).decode('utf-8').rstrip('=')}".upper(),
            "endpoint": endpoint,
            "action": action,
            "workspace_id": workspace_id,
            "credential_used": credential_used,
            "status": status_code,
            "latency_ms": latency_ms,
            "timestamp": ts
        })
        _save("request_logs.json", logs)
        return outcome

    # global rate limit
    logs = _load("request_logs.json")
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    one_min_ago = (now_dt - datetime.timedelta(seconds=60)).isoformat()
    recent = 0
    for r in logs[-5000:]:
        if isinstance(r, dict) and r.get("timestamp") and r["timestamp"] >= one_min_ago:
            recent += 1
    if recent >= 600:
        return _record("RATE_LIMIT", _err("RATE_LIMIT", "Rate limit exceeded."))

    wsp_pat = re.compile(r"^brv_wsp_[0-9A-Z]{18,}$")
    if workspace_id is not None and (not isinstance(workspace_id, str) or not wsp_pat.match(workspace_id)):
        return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid workspace_id format.", field="workspace_id"))

    if include_workspaces is None:
        include_workspaces = False
    if not isinstance(include_workspaces, bool):
        return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "include_workspaces must be boolean.", field="include_workspaces"))

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid limit.", field="limit"))

    offset = _parse_cursor(cursor)
    if offset is None:
        return _record("VALIDATION_ERROR", _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor"))

    wss = _load("workspaces.json")
    prs = _load("principals.json")

    # Ambient auth resolution:
    # Choose an active principal if any; otherwise treat as system/service with access to all workspaces.
    principal = None
    for p in prs:
        if isinstance(p, dict) and p.get("status") == "active":
            principal = p
            break

    accessible_workspaces = [w for w in wss if isinstance(w, dict)]
    if principal:
        accessible_workspaces = [w for w in accessible_workspaces if w.get("id") == principal.get("workspace_id")]

    if workspace_id is not None:
        if not any(isinstance(w, dict) and w.get("id") == workspace_id for w in wss):
            return _record("NOT_FOUND", _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id))
        if not any(isinstance(w, dict) and w.get("id") == workspace_id for w in accessible_workspaces):
            return _record("UNAUTHORIZED", _err("UNAUTHORIZED", "Caller is not entitled to access the referenced workspace.", workspace_id=workspace_id))

    # increment api_calls for a workspace in scope (if provided) else any accessible one
    ws_scope = None
    if workspace_id:
        ws_scope = next((w for w in wss if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws_scope and accessible_workspaces:
        ws_scope = next((w for w in wss if isinstance(w, dict) and w.get("id") == accessible_workspaces[0].get("id")), None)

    if ws_scope:
        ut = ws_scope.get("usage_today")
        if not isinstance(ut, dict) or ut.get("date") != _today_key():
            ws_scope["usage_today"] = {"date": _today_key(), "emails_sent": 0, "sms_sent": 0, "whatsapp_sent": 0, "events_ingested": 0, "api_calls": 0}
        ws_scope["usage_today"]["api_calls"] = int(ws_scope["usage_today"].get("api_calls", 0)) + 1
        ws_scope["updated_at"] = _now()
        for i, w in enumerate(wss):
            if isinstance(w, dict) and w.get("id") == ws_scope.get("id"):
                wss[i] = ws_scope
                _save("workspaces.json", wss)
                break

    # Prepare entitlements/scopes
    def _scopes_for_role(r):
        if r in (None, ""):
            return ["system:read", "system:write"]
        if r == "owner":
            return ["workspace:read", "workspace:write", "contacts:write", "messaging:send", "business:write", "admin:manage"]
        if r == "admin":
            return ["workspace:read", "workspace:write", "contacts:write", "messaging:send", "business:write"]
        if r == "support":
            return ["workspace:read", "contacts:read", "messaging:read", "business:read"]
        if r == "analyst":
            return ["workspace:read", "contacts:read", "messaging:read", "business:read"]
        if r == "read_only":
            return ["workspace:read", "contacts:read", "messaging:read", "business:read"]
        return ["workspace:read"]

    identity = {
        "principal": principal,
        "role": principal.get("role") if principal else "system",
        "scopes": _scopes_for_role(principal.get("role") if principal else None),
    }

    # workspace-scoped quotas if requested
    workspace_entitlements = None
    if workspace_id:
        w = next((x for x in wss if isinstance(x, dict) and x.get("id") == workspace_id), None)
        if w:
            ut = w.get("usage_today") if isinstance(w.get("usage_today"), dict) else {}
            workspace_entitlements = {
                "workspace_id": workspace_id,
                "status": w.get("status"),
                "quota_daily": {
                    "emails": w.get("quota_daily_emails"),
                    "sms": w.get("quota_daily_sms"),
                    "whatsapp": w.get("quota_daily_whatsapp"),
                    "events": w.get("quota_daily_events")
                },
                "usage_today": ut
            }

    workspaces_page = None
    if include_workspaces:
        total = len(accessible_workspaces)
        page = accessible_workspaces[offset: offset + limit]
        has_more = offset + limit < total
        next_cursor = _make_cursor(offset + limit) if has_more else None
        workspaces_page = {"data": page, "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor}}

    return _record("ok", {"data": {"identity": identity, "workspace": workspace_entitlements, "workspaces": workspaces_page}})
